window.QBANK=[{"id":1,"m":"练习一","t":"单选","q":"Kettle数据在进行数据清洗时，使用了不同种类的加密方式，但并不是其中之一。","o":["对称加密","PGP加密流","PGP解密流","MD5加密"],"a":3,"e":"【考点】Kettle 清洗中的加密手段\n【答案】D\n【解析】题干说 Kettle 清洗时用了几种加密方式，但“并不是其中之一”。Kettle 里真正的加密环节是 PGP 加密流、PGP 解密流和对称加密，所以 A、B、C 都在“加密方式”里。MD5 是把任意长度数据压缩成 128 位摘要的哈希算法，只能校验完整性、无法还原原文，属于摘要而非加密，因此被排除的就是 D。\n【辨析】看到“加密”先分清两类：能还原的是加密（对称、非对称），不能还原的是摘要（MD5、SHA）。","k":"yewu"},
{"id":2,"m":"练习一","t":"单选","q":"数据标注标准化管理手段主要适用于（）。","o":["全职人员","众包人员","校企人员","临时人员"],"a":0,"e":"【考点】数据标注的组织方式与标准化\n【答案】A\n【解析】标准化管理靠统一培训、统一口径和长期稳定的质检，只有全职人员能在岗前培训后持续按同一规范标注，人员流动小、规范才落得下去。众包、校企、临时人员流动性大、培训成本高、口径难统一，所以“标准化管理手段主要适用于全职人员”。\n【辨析】B、C、D 都是标注团队的类型，但都不是“标准化管理”的对象特征。","k":"xunlian"},
{"id":3,"m":"练习一","t":"单选","q":"回归分析研究的是如何使用0来预测因变量的变化。","o":["自变量","控制变量","无关变量","干扰变量"],"a":0,"e":"【考点】回归分析的基本概念\n【答案】A\n【解析】题干括号处 OCR 成 0，原意是“使用（ ）来预测因变量的变化”。回归的核心就是用自变量 x 去解释、预测因变量 y，例如用广告投入预测销量，投入是自变量、销量是因变量，所以填“自变量”。\n【辨析】B 控制变量、D 干扰变量属于实验设计里的概念，不是回归的预测输入；C 无关变量与因变量没有关系，不能用来预测。","k":"xunlian"},
{"id":4,"m":"练习一","t":"单选","q":"在聚类分析中，越（的DBI值或越的DI值，都意味着聚类的效果越好。","o":["大，大","大,小","小,大","小，小"],"a":2,"e":"【考点】聚类效果评价指标\n【答案】C\n【解析】聚类好坏有两个常用内部指标：DBI（Davies-Bouldin 指数）衡量簇间分离度与簇内紧密度的比值，越小越好；DI（Dunn 指数）是最小簇间距离与最大簇内直径之比，越大越好。所以是“DBI 越小、DI 越大”。\n【辨析】A、D 把两个指标的方向说反了，B 只说对了 DBI 一个。记法：DBI 带 B 像“比”，比得越小越集中。","k":"xunlian"},
{"id":5,"m":"练习一","t":"单选","q":"对于ETL数据整合工具，其业务需求的定义是（）)","o":["确定数据来源和目标","漫无目的设计数据仓库模型","定义与ETL相关性不强的工作流","建立ETL最完美的测试计划"],"a":0,"e":"【考点】ETL 业务需求定义\n【答案】A\n【解析】ETL 项目动工前必须先明确业务需求，即数据从哪儿来、要落到哪里去、口径怎么定义，这就是“确定数据来源和目标”。这是后续建模、开发、测试的起点。\n【辨析】B 是漫无目的地设计数仓模型，属于方向错误；C 是设计与 ETL 无关的工作流；D 是空想“最完美的测试计划”——三者在需求定义阶段都无从谈起。","k":"yewu"},
{"id":6,"m":"练习一","t":"单选","q":"（）是一组计算机指令或程序，它会感染计算机程序并破坏其功能以及数据。这种程序能够自我复制并传播感染给其他计算机。","o":["计算机病毒","数据库","操作系统","办公软件"],"a":0,"e":"【考点】计算机病毒的定义\n【答案】A\n【解析】题干抓三个特征：是一组可执行指令或程序、会感染别的程序、能自我复制传播。这正是计算机病毒的定义。\n【辨析】B 数据库是结构化数据的集合，C 操作系统是管理硬件资源的系统软件，D 办公软件是应用软件，三者都不会自我复制、也不破坏他程序。","k":"jichu"},
{"id":7,"m":"练习一","t":"单选","q":"（）是由来自社会各个领域的个人自愿组成的一个大型在线网络团队。","o":["统一管理的标注生产团队","众包团队","校企团队","私人团队"],"a":1,"e":"【考点】标注团队类型：众包\n【答案】B\n【解析】题干的关键信息是“来自社会各个领域的个人自愿组成的大型在线网络团队”，这正是众包（crowdsourcing）的定义——把任务公开发布，让不特定人群自愿参与。\n【辨析】A 统一管理的标注团队是公司内部有组织、有考核的队伍；C 校企团队是学校与企业合作组建；D 私人团队规模小且封闭，都不符合“社会各领域自愿参与”。","k":"peixun"},
{"id":8,"m":"练习一","t":"单选","q":"爱岗是实现敬业的（条件，而敬业则是爱岗的具体体现。","o":["保证","根本","前提","准绳"],"a":2,"e":"【考点】职业道德：爱岗与敬业\n【答案】C\n【解析】规范表述是：爱岗是敬业的前提，敬业是爱岗的具体体现。因为先认同、热爱自己的岗位，才可能把工作做深做细，所以爱岗在前、是前提。\n【辨析】A 保证、B 根本、D 准绳都不是这句职业规范里的固定搭配，属于近义词干扰。","k":"peixun"},
{"id":9,"m":"练习一","t":"单选","q":"在数据清洗中，去除重复数据需要技巧，其标准是数据的（）。","o":["准确性","唯一性","可靠性","完整性"],"a":1,"e":"【考点】数据清洗：去除重复值\n【答案】B\n【解析】判断两条记录是否重复，靠的是它们的标识字段是否完全相同，也就是数据的唯一性——唯一性被破坏才产生重复记录。\n【辨析】A 准确性指数值是否正确、C 可靠性指来源与采集是否可信、D 完整性指字段是否缺失，三者都是数据质量的另外几个维度，与“去重”不对应。","k":"yewu"},
{"id":10,"m":"练习一","t":"单选","q":"MicrosoftOffice软件中用于处理、分析数据以及辅助操作的工具是（），它可以进行数据处理、统计分析、数据可视化展示等操作。","o":["Word","Access","Excel","PowerPoint"],"a":2,"e":"【考点】Office 组件的用途\n【答案】C\n【解析】题干要的是能做数据处理、统计分析、可视化展示的组件。Excel 以单元格表格为核心，函数、数据透视表、图表齐全，正是这个角色。\n【辨析】A Word 处理文字文档，B Access 是小型关系数据库管理系统（重在建库查询），D PowerPoint 做演示幻灯片，都不以数据计算与图表为主。","k":"sheji"},
{"id":11,"m":"练习一","t":"单选","q":"简单的原型，用来进行初步设计的草图或模型，也被称为（）。","o":["高保真原型","功能原型","纸上原型","低保真原型"],"a":3,"e":"【考点】原型设计的保真度\n【答案】D\n【解析】题干强调“简单的原型、初步设计的草图或模型”。低保真原型就是纸面或线框图，只表达布局和流程，不追求视觉细节，正对应草图阶段。\n【辨析】A 高保真原型接近成品视觉与交互，用于评审和交付；B 功能原型强调能跑通核心流程；C 纸上原型是按载体说的，本身也是低保真的一种形式，但题干问的层级名称是低保真。","k":"sheji"},
{"id":12,"m":"练习一","t":"单选","q":"在（）阶段，采用的设计方法提供了紧密联系并为用户和其他模型提供了设计框架。","o":["概念设计","需求定义","原型设计","交互设计"],"a":1,"e":"【考点】交互设计阶段\n【答案】B\n【解析】需求定义阶段的任务是明确用户是谁、要解决什么问题、约束条件是什么，由此产出设计框架与设计方法，供后续概念设计和原型设计沿用，所以题干描述落在需求定义。\n【辨析】A 概念设计是把需求转成解决思路，C 原型设计是把思路做成可看可点的模型，D 交互设计关注操作流程与反馈，都是在需求明确之后才展开的。","k":"sheji"},
{"id":13,"m":"练习一","t":"单选","q":"在缺失属性对象相对整个数据集所占比例较小时，可以使用（）方法进行数据清理。","o":["随机补充","使用属性的平均值填充空缺值","不处理","忽略元组"],"a":3,"e":"【考点】缺失值处理：忽略元组\n【答案】D\n【解析】题干给的条件是“缺失属性对象所占比例较小”。比例很小意味着丢掉这些记录对整体分布影响有限，最省事又不易引入偏差的做法就是删掉含缺失的整条记录，即忽略元组。\n【辨析】A 随机补充会凭空造数，B 均值填充适合连续数值字段的少量缺失但会压缩方差，C 不处理会把脏数据带进模型。比例大时才考虑填充。","k":"xunlian"},
{"id":14,"m":"练习一","t":"单选","q":"请问以下哪个可视化图表是用圆形内扇形面积大小来说明总体结构的（）。","o":["散点图","雷达图","饼状图","漏斗图"],"a":2,"e":"【考点】图表选型：饼图\n【答案】C\n【解析】题干的两个限定词是“圆形内扇形面积”和“说明总体结构”，这正是饼图的定义——用各扇形占整圆的比例表示各部分在总体中的份额。\n【辨析】A 散点图看两变量的相关关系，B 雷达图做多维指标对比，D 漏斗图看流程环节的流失转化，形状与用途都不符。","k":"sheji"},
{"id":15,"m":"练习一","t":"单选","q":"利用人类学（），以提供关于潜在或真实产品用户的感性数据。","o":["调查研究","情景建模","细化设计","修改设计"],"a":0,"e":"【考点】用户研究：人类学调查\n【答案】A\n【解析】人类学方法强调走进真实场景做观察与访谈，收集用户的感性、情境化数据，对应调查研究（观察、访谈、问卷、现场记录）。\n【辨析】B 情景建模是把观察结果整理成使用场景，C 细化设计、D 修改设计都属于设计执行环节，不是收集感性数据的手段。","k":"sheji"},
{"id":16,"m":"练习一","t":"单选","q":"如果您使用不准确的测量工具进行测量，通常会产生异常数值，这种错误方法被称为（）。","o":["数据输入错误","测量误差","数据处理错误","数据分析错误"],"a":1,"e":"【考点】数据质量：测量误差\n【答案】B\n【解析】题干点明“使用了不准确的测量工具”，误差来自测量环节本身，所以叫测量误差——工具精度不够、校准不准都会带来系统性偏差。\n【辨析】A 数据输入错误是录入时打错、错位；C 数据处理错误发生在清洗转换阶段；D 数据分析错误是方法选错，三者都不是工具精度问题。","k":"yewu"},
{"id":17,"m":"练习一","t":"单选","q":"在数据变换中，（）是将数据从源表中原封不动地抽取出来，并转换成数据分析需要的格式。","o":["数据计算","数据合并","数据抽取","数据分析"],"a":2,"e":"【考点】数据变换：抽取\n【答案】C\n【解析】题干描述的是“从源表中原封不动取出、再转成分析需要的格式”，第一步就是把数据从源表取出来，即数据抽取。\n【辨析】A 数据计算是做聚合与派生字段，B 数据合并是把多表拼在一起，D 数据分析是抽取之后的理解工作，都不含“从源表取数”这一步。","k":"yewu"},
{"id":18,"m":"练习一","t":"单选","q":"《劳动法》有关休息休假的规定，以下哪个是用人单位应当依法安排劳动者休假的节假日？","o":["元旦","元宵节","重阳节","冬至"],"a":0,"e":"【考点】劳动法：法定节假日\n【答案】A\n【解析】《劳动法》与《全国年节及纪念日放假办法》确定的法定节假日包括元旦、春节、清明节、劳动节、端午节、中秋节、国庆节等。四个选项里只有元旦是法定节假日。\n【辨析】B 元宵节、C 重阳节、D 冬至都是传统节日或节气，不是法定放假的节日。","k":"jichu"},
{"id":19,"m":"练习一","t":"单选","q":"是常见的一种可视化图表，主要用于数量计算。它通过条形的长度或高度来表示不同事物之间数量的大小，以及数量间的差异。","o":["条形图","折线图","散点图","饼图"],"a":0,"e":"【考点】图表选型：条形图\n【答案】A\n【解析】题干的关键是“通过条形的长度或高度表示不同事物之间数量的大小与差异”，这是条形图（柱状图）的标准定义，用于类别之间的数值对比。\n【辨析】B 折线图表达随时间变化的趋势，C 散点图表达两个变量的相关性，D 饼图表达占比，都不以“条形长度比大小”为主要手段。","k":"sheji"},
{"id":20,"m":"练习一","t":"单选","q":"在Kettle工具中，若任何转换步骤返回错误信息信号，则（）是最容易的处理方式。","o":["写日志","中止作业","定义错误处理","空操作"],"a":1,"e":"【考点】Kettle 作业的错误处理\n【答案】B\n【解析】转换步骤抛出错误信号时，最省事且能立刻止损的处理方式是把整个作业中止，避免带着错误继续往下跑、污染目标表，所以选“中止作业”。\n【辨析】A 写日志只记录不阻断，C 定义错误处理是更精细的方案但配置成本高，D 空操作等于放过错误。题干问“最容易的处理方式”，只有 B。","k":"yewu"},
{"id":21,"m":"练习一","t":"单选","q":"（）是一种数据抽取方式，它指的是在从数据源端的数据表中抽取数据时，一次性地把全部数据都抽取出来，然后再进行后续操作。","o":["全量抽取","极少量抽取","择机抽取","随机抽取"],"a":0,"e":"【考点】数据抽取方式：全量抽取\n【答案】A\n【解析】题干明确“一次性把全部数据都抽取出来，再进行后续操作”，这就是全量抽取：每次把源表整表搬一遍。它的优点是实现简单、数据一致性好，缺点是数据量大时耗时。\n【辨析】B 极少量抽取、C 择机抽取、D 随机抽取都不符合“一次性全部”这个限定。与之相对的是增量抽取，只取变化部分。","k":"yewu"},
{"id":22,"m":"练习一","t":"单选","q":"请问以下哪种错误属于源端数据源错误，在数据转换过程中会将保留字认为是目标数据源的标识符？（）","o":["时间错误","长度错误","命名错误","空间错误"],"a":2,"e":"【考点】ETL 源端错误：命名错误\n【答案】C\n【解析】题干的关键是“把保留字当成目标数据源的标识符”。标识符（表名、字段名）取错属于命名层面的问题，所以是命名错误。\n【辨析】A 时间错误指日期格式或时区不对，B 长度错误指字段长度超限被截断，D 空间错误指存储或字符集问题，都不是标识符取名。","k":"yewu"},
{"id":23,"m":"练习一","t":"单选","q":"是测试计划。","o":["一个文件","叙述了对于预定的测试活动将要采取的途","在实际测试过程中不必要的文档","描述要进行的测试活动的范围、方法、源和进度的文档"],"a":3,"e":"【考点】软件测试：测试计划\n【答案】D\n【解析】测试计划是一份文档，写清楚要测什么范围、用什么方法、需要哪些资源和人力、各阶段进度安排，用于指导整个测试活动。D 的表述最完整。\n【辨析】A 只说“一个文件”太笼统；B 描述不完整且缺范围与进度；C 说成“不必要的文档”直接违背测试管理要求。","k":"yunwei"},
{"id":24,"m":"练习一","t":"单选","q":"（）是一种常见的可视化图表，其可以用矩形的面积来表示连续型随机变量的分布情况。","o":["漏斗图","直方图","仪表盘","散点图"],"a":1,"e":"【考点】图表选型：直方图\n【答案】B\n【解析】题干限定“用矩形面积表示连续型随机变量的分布情况”，这是直方图——横轴是连续区间的分箱，矩形高度是频数或频率，面积反映该区间的占比。\n【辨析】A 漏斗图看流程转化，C 仪表盘看单一指标完成度，D 散点图看两变量关系，都不能表达连续分布的形态（集中、偏斜、双峰）。","k":"sheji"},
{"id":25,"m":"练习一","t":"单选","q":"下列软件中，不属于浏览器的是","o":["IE","QQ","GoogleChrome","Firefox"],"a":1,"e":"【考点】浏览器与即时通讯软件\n【答案】B\n【解析】IE、Google Chrome、Firefox 都是网页浏览器，用于解析并呈现网页。QQ 是即时通讯客户端，不是浏览器。\n【辨析】此题属识别类，注意 IE 虽已停止支持但仍是浏览器；Chrome 与 Firefox 分别是谷歌、Mozilla 的产品。","k":"jichu"},
{"id":26,"m":"练习一","t":"单选","q":"是将目标对象划分到事先设定的类别中的过程。","o":["分类","聚类分析","回归分析","关联分析"],"a":0,"e":"【考点】分类与聚类的区别\n【答案】A\n【解析】题干的关键条件是“划分到事先设定的类别中”。类别是提前给定的、有标签的，把样本归到已知类别，正是分类（有监督学习）。\n【辨析】B 聚类事先没有类别标签，由算法按相似度自动分组；C 回归输出连续数值；D 关联分析找的是项集之间的共现规则，都不预设类别。","k":"xunlian"},
{"id":27,"m":"练习一","t":"单选","q":"将图像划分成具有不同特征的区域，并选择感兴趣的部分进行提取，这个过程被称为（）。","o":["关键点标注","矩形框标注","3D点云标注","区域标注"],"a":3,"e":"【考点】图像标注类型：区域标注\n【答案】D\n【解析】题干说的是把图像分成若干特征区域、再挑出感兴趣的部分，落笔的对象是一块区域，所以是区域标注（语义分割常用的多边形标注也属此类）。\n【辨析】A 关键点标注只标关节、人脸特征点等点位；B 矩形框标注用框住目标，不沿边界描绘；C 3D 点云标注处理三维数据，与二维分区不符。","k":"xunlian"},
{"id":28,"m":"练习一","t":"单选","q":"（）是将两个或多个数据表中的数据组合到一起形成一个新的数据表的过程。","o":["数据合并","数据抽取","数据计算","数据分析"],"a":0,"e":"【考点】数据变换：合并\n【答案】A\n【解析】题干说“将两个或多个数据表组合到一起形成新表”，把多份数据拼成一份，就是数据合并（纵向追加UNION或横向关联JOIN）。\n【辨析】B 数据抽取是从源端取数，C 数据计算做的是聚合与派生，D 数据分析是理解与解释，都不产生“新的合并表”。","k":"yewu"},
{"id":29,"m":"练习一","t":"单选","q":"由红色、（）和蓝色3种原色组合而成的是RGB模式。","o":["绿色","黑色","白色","灰色"],"a":0,"e":"【考点】色彩模式：RGB\n【答案】A\n【解析】RGB 是加色模式，三原色为红（Red）、绿（Green）、蓝（Blue），三者以不同强度叠加形成各种颜色，屏幕显示就用这套。\n【辨析】B 黑、C 白、D 灰都是三原色叠加后的结果，不是原色本身。印刷用的 CMYK 才是青、品红、黄、黑四色。","k":"sheji"},
{"id":30,"m":"练习一","t":"单选","q":"成功的从业人员需要具备（）的工作态度。","o":["废寝忘食","提升学历","提升能力","爱岗敬业"],"a":3,"e":"【考点】职业道德：爱岗敬业\n【答案】D\n【解析】题干问“成功从业人员的工作态度”，爱岗敬业是最基本、最核心的职业态度：热爱岗位、认真履职、精益求精。\n【辨析】A 废寝忘食是过度消耗，不是倡导的态度；B 提升学历、C 提升能力属于个人发展路径，不是“工作态度”。","k":"peixun"},
{"id":31,"m":"练习一","t":"单选","q":"随着时间的推移和不同社会阶层的存在，职业道德标准呈现出明显的（）色彩。","o":["相同性","人文性","阶级性","集体性"],"a":2,"e":"【考点】职业道德的特征\n【答案】C\n【解析】题干给了两个提示——“随着时间的推移”和“不同社会阶层的存在”，说明道德标准会随时代和阶层差异而变化，呈现阶级性。\n【辨析】A 相同性、B 人文性、D 集体性都不能解释“不同阶层”“随时间变化”这两层含义。职业道德除阶级性外还有历史继承性、相对稳定性等特征。","k":"peixun"},
{"id":32,"m":"练习一","t":"单选","q":"以下属于计算机安全的是","o":["硬件安全","软件安全","数据安全","以上皆是"],"a":3,"e":"【考点】计算机安全的范围\n【答案】D\n【解析】计算机安全是系统性概念，既包括硬件设备不损坏、不被盗（硬件安全），也包括软件无漏洞、不被篡改（软件安全），还包括数据不泄露、不丢失（数据安全），因此“以上皆是”。\n【辨析】只答 A、B、C 中任意一项都是以偏概全，这正是本题的陷阱。","k":"jichu"},
{"id":33,"m":"练习一","t":"单选","q":"下列场景中不适合漏斗图分析法的（）。","o":["用户行为分析","App数据分析","日常数据运营与数据分析","市场占有率"],"a":3,"e":"【考点】漏斗分析的适用场景\n【答案】D\n【解析】漏斗图用于有明确先后步骤、逐层流失的流程分析：用户行为路径、App 转化、日常运营数据都符合。市场占有率是同一时点各家的份额占比，没有“层层转化”的结构，该用饼图或条形图。\n【辨析】A、B、C 都是典型的多步骤转化场景，所以“不适合”的只有 D。","k":"yewu"},
{"id":34,"m":"练习一","t":"单选","q":"在文本清洗的过程中，通常会将数据复制到电子表格中，然后以（）作为依据，将数据分割成不同的列。","o":["随机分配长度","固定长度","分隔符(制表符或逗号或其他)","根据业务人为切分"],"a":2,"e":"【考点】文本清洗：分列\n【答案】C\n【解析】把文本复制到电子表格后按某规则拆成多列，靠的是行内统一的分隔符号（制表符、逗号、分号、竖线等），这就是“分隔符分列”（Excel 的分列功能也是这个原理）。\n【辨析】A 随机长度、B 固定长度都可能把字段截错，D 人为切分不可批量复用，只有分隔符能稳定批量处理。","k":"xunlian"},
{"id":35,"m":"练习一","t":"单选","q":"支付宝App推出实景红包功能，所用的技术是","o":["人工智能技术","增强现实技术","区块链技术","大数据技术"],"a":1,"e":"【考点】增强现实技术（AR）\n【答案】B\n【解析】实景红包要把虚拟红包叠加到手机摄像头拍到的真实场景里，用户走到指定位置才能看到并领取，这属于把虚拟信息叠加到现实画面的增强现实技术（AR）。\n【辨析】A 人工智能侧重识别与决策，C 区块链是分布式账本，D 大数据是海量数据处理，都不能实现“虚拟叠加到实景”。","k":"sheji"},
{"id":36,"m":"练习一","t":"单选","q":"不属于原始数据通常存在的问题的是（）。","o":["杂乱","数据量小","重复","不完整"],"a":1,"e":"【考点】原始数据的常见问题\n【答案】B\n【解析】原始数据通常“脏且多”：杂乱（格式不统一）、重复（同一对象多条记录）、不完整（字段缺失）。数据量小并不是原始数据的通病，反而样本不足才需要扩充采集。\n【辨析】题干问“不属于”，A、C、D 都是真实存在的典型问题，只有 B 不是。","k":"jichu"},
{"id":37,"m":"练习一","t":"单选","q":"是将数据规范化以便于后续分析和挖掘的过程，这个过程将数据转换成符合要求的形式。","o":["数据清洗","数据集成","数据规约","数据变换"],"a":3,"e":"【考点】数据预处理：变换\n【答案】D\n【解析】题干的关键词是“规范化”“转换成符合要求的形式”，包括归一化、标准化、离散化、属性构造等，都属于数据变换，目的是把数据整理成算法能吃的格式。\n【辨析】A 清洗处理的是脏数据（缺失、重复、异常），B 集成是把多源数据合到一起，C 规约是降维减量，三者都不等于“格式规范化”。","k":"yewu"},
{"id":38,"m":"练习一","t":"单选","q":"根据《劳动法》，（）享有与男子平等的就业权利。","o":["残疾人","乙肝病毒携带者","妇女","所有劳动者"],"a":2,"e":"【考点】劳动法：男女平等就业\n【答案】C\n【解析】《劳动法》规定妇女享有与男子平等的就业权利，除国家规定不适合妇女的工种外，不得以性别为由拒绝录用或提高录用标准。题干问“享有与男子平等就业权利”的主体，就是妇女。\n【辨析】A 残疾人、B 乙肝病毒携带者受的是反歧视保护（不得歧视），但法条原文的表述对象是妇女；D 所有劳动者范围过宽，不贴合“与男子平等”这一对照关系。","k":"jichu"},
{"id":39,"m":"练习一","t":"单选","q":"下列不属于漏斗分析结点要素的是（）。","o":["起点","终点","过程性结点","指标"],"a":3,"e":"【考点】漏斗分析的结点要素\n【答案】D\n【解析】漏斗分析的结点要素是起点、终点和中间的过程性结点，由这些结点串成转化路径。指标是用来量化各结点表现的度量，不属于结点本身。\n【辨析】题干问“不属于结点要素”，A、B、C 都是结点，D 是指标，答案即 D。","k":"yewu"},
{"id":40,"m":"练习一","t":"单选","q":"是一种利用体感交互技术的功能。","o":["触控屏幕","立体声","按键交互","手机的摇一摇功能"],"a":3,"e":"【考点】体感交互技术\n【答案】D\n【解析】体感交互靠传感器感知人的动作来完成操作。手机“摇一摇”用加速度传感器捕捉晃动，属于体感交互的典型应用。\n【辨析】A 触控屏是触摸交互，B 立体声是音频输出，C 按键交互是物理按键，三者都不依赖动作感知。","k":"sheji"},
{"id":41,"m":"练习一","t":"单选","q":"是计算机网络必备的硬件设备，它连接计算机和传输介质，是计算机能够联网的关键组件。","o":["路由器","集线器","中继器","网卡"],"a":3,"e":"【考点】计算机网络硬件：网卡\n【答案】D\n【解析】题干说“连接计算机与传输介质、让计算机能联网的关键组件”，这正是网卡（NIC）的职责：把计算机内部的数据转换成能在网线或无线介质上传输的信号。每台联网设备都必须有网卡。\n【辨析】A 路由器用于不同网络之间转发数据，B 集线器做多端口物理转发，C 中继器只放大延长信号，它们都不装在计算机内部充当“接入介质”的接口。","k":"jichu"},
{"id":42,"m":"练习一","t":"单选","q":"是指具有实时处理用户请求和允许用户随时更改分析约束和限制条件的特点的数据分析方式。","o":["定量数据分析","实时数据分析","定性数据分析","离线数据分析"],"a":1,"e":"【考点】数据分析方式：实时分析\n【答案】B\n【解析】题干的两个特征是“实时处理用户请求”和“允许随时更改分析约束”，一边来请求一边出结果，正是实时数据分析（流式处理）。\n【辨析】A 定量分析说的是数据性质（数值化），C 定性分析看性质与原因，D 离线分析是批量跑批、有延迟，都不满足“实时”。","k":"yewu"},
{"id":43,"m":"练习一","t":"单选","q":"漏斗分析法是一种用于（）的数据分析方法。","o":["针对现状分析","针对原因分析","针对预测分析","针对决策分析"],"a":0,"e":"【考点】漏斗分析法的定位\n【答案】A\n【解析】漏斗分析沿流程逐层看转化与流失，回答的是“当前每一步掉了多少人、卡在哪一环”，属于对现状的刻画，所以是“针对现状分析”。\n【辨析】B 原因分析要找为什么流失，需配合归因方法；C 预测分析看未来趋势；D 决策分析用于方案取舍，都不是漏斗图本身的功能。","k":"yewu"},
{"id":44,"m":"练习一","t":"单选","q":"不属于测试范围的主要来源","o":["产品需求文档","开发技术文档","数据库脚本","用户反馈的问题"],"a":2,"e":"【考点】软件测试范围的来源\n【答案】C\n【解析】测试范围主要来自产品需求文档（要测哪些功能）、开发技术文档（接口与实现细节）、用户反馈的问题（线上缺陷要回归验证）。数据库脚本属于实现细节的执行工具，不是确定“测什么范围”的依据。\n【辨析】题干问“不属于”，A、B、D 都是常见来源，答案是 C。","k":"yunwei"},
{"id":45,"m":"练习一","t":"单选","q":"选用不同的（），就会对最终的可视化方案产生不同的影响和预设。","o":["主动式获取数据","数据预处理","可视化模式","数据分析"],"a":2,"e":"【考点】可视化方案的影响因素\n【答案】C\n【解析】同一批数据，用柱状、折线、饼图还是热力图来呈现，读者得到的印象完全不同，所以选不同的可视化模式会影响最终方案与预设结论。\n【辨析】A 主动式获取数据讲的是采集方式，B 数据预处理影响数据质量，D 数据分析是方法层面，都不直接决定“图怎么画”。","k":"sheji"},
{"id":46,"m":"练习一","t":"单选","q":"不属于分布式架构的数据采集平台的是","o":["Scribe","Flume","Kafka","Spark"],"a":3,"e":"【考点】分布式数据采集平台\n【答案】D\n【解析】Scribe（Facebook）、Flume（Apache）、Kafka（Apache）都是为日志/事件流采集与传输设计的分布式系统。Spark 是分布式计算引擎，负责算而不是采集，所以不属于采集平台。\n【辨析】本题靠“工具定位”区分：采集（Scribe/Flume/Kafka）→ 存储（HDFS/HBase）→ 计算（Spark/Flink）→ 分析。","k":"yewu"},
{"id":47,"m":"练习一","t":"单选","q":"常见的图像处理软件是","o":["Foxpro","Oracle","Photoshop","WPS2000"],"a":2,"e":"【考点】图像处理软件\n【答案】C\n【解析】Photoshop 是专业位图图像处理软件，裁剪、调色、抠图、合成、滤镜都靠它，是图像处理的行业标准工具。\n【辨析】A FoxPro 是早期数据库，B Oracle 是关系数据库，D WPS2000 是办公套件，都与图像处理无关。","k":"jichu"},
{"id":48,"m":"练习一","t":"单选","q":"目前全球最常见的操作系统是（）操作系统","o":["MS-DOS","Linux","Unix","Windows"],"a":3,"e":"【考点】操作系统：桌面主流系统\n【答案】D\n【解析】按全球桌面装机量统计，Windows 长期占据绝大多数份额（各版本合计约七成以上），是“全球最常见的操作系统”。\n【辨析】A MS-DOS 是早期命令行系统已被淘汰，B Linux 在服务器占优但桌面份额小，C Unix 主要用于服务器与工作站。","k":"jichu"},
{"id":49,"m":"练习一","t":"单选","q":"测试过程中记录问题和缺陷的文档，可以帮助开发人员分析并纠正软件质量问题。这个文档叫做缺陷报告，它向（）提供重要的信息。","o":["需求说明书","开发技术文档","测试报告","产品手册"],"a":0,"e":"【考点】缺陷报告的作用\n【答案】A\n【解析】缺陷报告记录问题现象、复现步骤和影响，最终要反馈到需求侧，用来核对“需求是否被正确实现”，所以它为需求说明书提供重要信息（题库答案选 A）。\n【辨析】B 开发技术文档、C 测试报告、D 产品手册都是下游产物，缺陷报告是它们的输入而非输出。","k":"yunwei"},
{"id":50,"m":"练习一","t":"单选","q":"将缺失属性值的对象（元组、记录）直接删除，从而得到一个完整信息表的数据清理方法为（）.","o":["忽略元组","使用属性的平均值填充空缺值","使用与给定元组属同一类的所有样本的平均值","使用最可能的值填充空缺值"],"a":0,"e":"【考点】缺失值处理：忽略元组\n【答案】A\n【解析】题干说的是“把含缺失属性值的记录整条删掉，从而得到完整信息表”，删整条记录就是忽略元组。它与 #13 是同考点不同表述，条件不同：这里没有强调缺失比例小。\n【辨析】B、C、D 都是填充法（均值、同类均值、最可能值），属于保留记录、补上缺失，不是删除。","k":"yewu"},
{"id":51,"m":"练习一","t":"单选","q":"描述性分析是（）。","o":["对研究对象进行\"质\"的方面的分析","解决研究对象\"有没有\"是不是\"的问题","基于历史数据来描述发生的事件","侧重从数据当中发现新的特征"],"a":2,"e":"【考点】描述性分析\n【答案】C\n【解析】数据分析按层次分：描述性（发生了什么）、诊断性（为什么）、预测性（会怎样）、指导性（该怎么办）。描述性分析就是用历史数据说清楚已经发生的事实，如汇总销量、统计活跃度。\n【辨析】A、B 说的是定性分析，D 侧重发现新特征，属于探索性或预测性分析的范畴。","k":"yewu"},
{"id":52,"m":"练习一","t":"单选","q":"在App的设计中，最基本的互动手段就是","o":["语音交互","手势交互","触摸交互","眼动交互"],"a":2,"e":"【考点】移动端交互方式\n【答案】C\n【解析】手机 App 最基础、最高频的输入方式就是手指触摸屏幕，点击、滑动、长按都建立在触摸之上，所以最基本的互动手段是触摸交互。\n【辨析】A 语音、B 手势、D 眼动都是增强型交互，依赖额外传感器，使用频率远不及触摸。","k":"sheji"},
{"id":53,"m":"练习一","t":"单选","q":"以下哪一个选项不包括在计算机网络按地理覆盖范围分类中？","o":["局域网","广域网","城域网","无线网"],"a":3,"e":"【考点】计算机网络按覆盖范围分类\n【答案】D\n【解析】按地理覆盖范围分为局域网（LAN，一栋楼内）、城域网（MAN，一个城市）、广域网（WAN，跨地区跨国）。无线网是按传输介质（有线/无线）分类，不在这套范围体系里。\n【辨析】题干问“不包括”，A、B、C 都在范围分类中，答案 D。","k":"jichu"},
{"id":54,"m":"练习一","t":"单选","q":"（）公司开发了IE浏览器。","o":["Mircosoft","Google","IBM","Netscape"],"a":0,"e":"【考点】浏览器厂商\n【答案】A\n【解析】Internet Explorer 由微软（Microsoft）随 Windows 捆绑发布，曾是市场占有率最高的浏览器。\n【辨析】B Google 出品 Chrome，C IBM 主要做企业级软硬件，D Netscape 出品 Netscape Navigator（IE 的早期竞争对手）。选项 A 拼写为 Mircosoft，是题库原样错拼。","k":"jichu"},
{"id":55,"m":"练习一","t":"单选","q":"对于产品的各项功能进行验证，以检验它们的逻辑是否正确，这就是所谓的（）。","o":["需求分析","安全测试","性能测试","功能测试"],"a":3,"e":"【考点】测试类型：功能测试\n【答案】D\n【解析】题干说“对产品的各项功能进行验证、检查逻辑是否正确”，验证的是功能做没做对，就是功能测试。\n【辨析】A 需求分析是开发前的定义工作，B 安全测试查漏洞与越权，C 性能测试测并发与响应时间，都不是功能逻辑验证。","k":"yunwei"},
{"id":56,"m":"练习一","t":"单选","q":"ETL数据整合工具数据评估的方法有（）。","o":["数据抽样","数据统计","数据可视化","以上都是"],"a":3,"e":"【考点】ETL 数据评估方法\n【答案】D\n【解析】ETL 过程中评估数据质量与口径，通常会抽样核对（数据抽样）、做汇总比对（数据统计）、画分布看异常（数据可视化），三种方法互补，因此“以上都是”。\n【辨析】只选其中一项会漏掉另两个维度，这是本题的设错方式。","k":"yewu"},
{"id":57,"m":"练习一","t":"单选","q":"以下哪个选项是对计算机病毒的概括？","o":["编制有错误的计算机程序","设计不完善的计算机程序","计算机的程序已被破坏","以危害系统为目的的非法的计算机程序"],"a":3,"e":"【考点】计算机病毒的概括\n【答案】D\n【解析】病毒的本质有三点：人为编写、目的在破坏、具有传染性。D 同时点出“以危害系统为目的”和“非法程序”，概括最准确。\n【辨析】A 编制有错误的程序是 Bug，B 设计不完善是缺陷，C 是病毒造成的结果（程序已被破坏），三者都没抓住“故意危害+传染”的本质。","k":"jichu"},
{"id":58,"m":"练习一","t":"单选","q":"使用Python中的Matplotlib库绘制横向条形图，需要调用barhO函数。","o":["histO","ploto","barO","barhO"],"a":3,"e":"【考点】Matplotlib 横向条形图\n【答案】D\n【解析】Matplotlib 中 plt.bar 画竖向柱状图，plt.barh 画横向条形图（h 代表 horizontal）。题干问绘制横向条形图用哪个函数，答案是 barh。\n【辨析】A hist 画直方图，B plot 画折线图，C bar 画竖向柱状图。选项里 OCR 把括号识别成字母 O，实际是 barh( )。","k":"sheji"},
{"id":59,"m":"练习一","t":"单选","q":"使用Matplotlib中，将柱形图的x轴和y轴调换后，柱形图即变成了（）。","o":["线图","直方图","条形图","饼图"],"a":2,"e":"【考点】bar 与 barh 的关系\n【答案】C\n【解析】把柱状图的 x 轴和 y 轴对调，矩形就从“竖着立”变成“横着躺”，竖向柱状图也就变成了横向条形图，即 bar 换成 barh。\n【辨析】A 线图由 plot 生成，B 直方图由 hist 生成，D 饼图由 pie 生成，都不是坐标轴对调的结果。","k":"sheji"},
{"id":60,"m":"练习一","t":"单选","q":"推断性统计分析更侧重于获得（）的答案。","o":["定性","定量","交叉","聚类"],"a":1,"e":"【考点】推断性统计\n【答案】B\n【解析】统计学分两支：描述统计只汇总已有数据；推断统计用样本推断总体，要给出参数估计和显著性检验，结论必须落在具体数值上（置信区间、p 值、相关系数），因此更侧重“定量”答案。\n【辨析】A 定性回答性质与原因，C 交叉、D 聚类是分析手段，都不是推断统计的输出形式。","k":"yewu"},
{"id":61,"m":"练习一","t":"单选","q":"在做聚类分析时，同一个簇里的数据彼此之间相似度都很（），不同簇之间的数据相似度很","o":["低,低","高,低","低，高","高，高"],"a":1,"e":"【考点】聚类的基本假设\n【答案】B\n【解析】聚类的目标就是“物以类聚”：把相似的样本放进同一个簇，所以簇内相似度高；不同簇代表不同类别，彼此差异大，所以簇间相似度低。\n【辨析】A、C、D 都违背聚类的基本目标，若簇内相似度低就说明聚错了。","k":"xunlian"},
{"id":62,"m":"练习一","t":"单选","q":"设计师必须深入了解用户需求，并将其应用于指导设计，这就是以（）的设计。","o":["以活动为中心","以用户为中心","高瞻远瞩","以目标为导向"],"a":1,"e":"【考点】以用户为中心的设计（UCD）\n【答案】B\n【解析】题干强调“深入了解用户需求，并用它指导设计”，这正是以用户为中心的设计思想：先研究用户，再定义问题，最后设计并让用户验证。\n【辨析】A 以活动为中心关注任务流程本身，C 高瞻远瞩是形容眼光，D 以目标为导向强调结果指标，都不落在“用户需求驱动”。","k":"sheji"},
{"id":63,"m":"练习一","t":"单选","q":"的目的是从数据中挖掘有用信息，为决策提供有意义的建议和支持。","o":["情报研究","技术跟踪","数据分析","信息组织"],"a":2,"e":"【考点】数据分析的目的\n【答案】C\n【解析】题干说“从数据中挖掘有用信息，为决策提供建议”，这句话就是数据分析的定义——把原始数据加工成可支撑判断的结论。\n【辨析】A 情报研究偏情报搜集，B 技术跟踪关注技术演进，D 信息组织是整理归类信息，都不以“支撑决策”为核心目的。","k":"yewu"},
{"id":64,"m":"练习一","t":"单选","q":"AB测试是一种对（），用于比较两个（或多个）不同版本的产品或策略，以确定哪个版本更有效或更受欢迎。","o":["分组分析法","对比分析法","漏斗分析法","留存分析法"],"a":1,"e":"【考点】AB 测试的本质\n【答案】B\n【解析】AB 测试把用户分成两组，分别给 A、B 两个版本，再用同一套指标比较效果，本质是控制变量的对比分析，所以归入对比分析法。\n【辨析】A 分组分析只做事后分群统计，C 漏斗分析看流程转化，D 留存分析看回访比例，都不能解释“两版本互相对照”的设计。","k":"yunwei"},
{"id":65,"m":"练习一","t":"单选","q":"（）是一种二维形状，它可以在更高维度的空间中弯曲和扭曲。","o":["微分流形","二维流形","四维流形","拓扑流形"],"a":1,"e":"【考点】流形的维度\n【答案】B\n【解析】流形是局部看起来像欧氏空间、整体可以弯曲的空间。题干说“是一种二维形状，却能在更高维空间中弯曲和扭曲”，描述的正是二维流形（曲面）——局部是二维平面，整体嵌在三维或更高维里。\n【辨析】A 微分流形是带微分结构的流形总称，C 四维流形维度不符，D 拓扑流形是拓扑学语境下的总称，都没有点出“二维形状”这一限定。","k":"yewu"},
{"id":66,"m":"练习一","t":"单选","q":"数据转换是将数据转换为适合于进行（）的格式。","o":["数据集成","数据分析","数据挖掘","报表统计"],"a":2,"e":"【考点】数据转换的用途\n【答案】C\n【解析】数据转换（归一化、标准化、离散化、属性构造）的目的是把数据整理成算法可直接处理的形式，服务于数据挖掘与建模。\n【辨析】A 数据集成是先把多源数据合到一起，B 数据分析更宽泛、含人工解读，D 报表统计是展示用途，都不如“数据挖掘”贴合“适合算法处理”这层意思。","k":"yewu"},
{"id":67,"m":"练习一","t":"单选","q":"对于数据标注行业而言，数据标注质量的标准主要是标注的（）。","o":["真实性","时效性","准确性","专业性"],"a":2,"e":"【考点】标注质量的核心标准\n【答案】C\n【解析】标注是把人的判断转成模型可学的标签，标签对不对直接决定模型学得对不对，所以质量的第一标准是准确性（与真实语义、规范一致）。\n【辨析】A 真实性针对数据本身是否真实采集，B 时效性针对新鲜程度，D 专业性针对标注员能力，都不是衡量“标得对不对”的指标。","k":"peixun"},
{"id":68,"m":"练习一","t":"单选","q":"通过自我教育、磨炼和完善来提高职业道德素养，这就是职业道德","o":["文化","修养","分类","表现"],"a":1,"e":"【考点】职业道德修养\n【答案】B\n【解析】题干是“通过自我教育、磨炼和完善来提高职业道德素养”，自我教育加自我磨炼，正是职业道德修养的路径。\n【辨析】A 文化、C 分类、D 表现都不对应“自我教育、自我完善”这一过程。","k":"peixun"},
{"id":69,"m":"练习一","t":"单选","q":"计算机病毒主要通过（）进行感染和传输。","o":["磁盘与网络","微生物病毒","人体","电源"],"a":0,"e":"【考点】计算机病毒的传播途径\n【答案】A\n【解析】病毒是程序，必须借助可移动存储（U 盘、移动硬盘等磁盘介质）和网络（邮件附件、下载、共享）才能传播到别的机器上，所以主要途径是磁盘与网络。\n【辨析】B 微生物病毒是生物学概念，C 人体、D 电源都不是程序传播的载体，属于明显不合理的干扰项。","k":"jichu"},
{"id":70,"m":"练习一","t":"单选","q":"对于（）的设计项目来说，以活动为导向的设计方法更为合适。","o":["简单","复杂","传统软件","一般难度"],"a":1,"e":"【考点】以活动为中心的设计适用范围\n【答案】B\n【解析】复杂项目任务链长、角色多、流程交叉，单靠用户访谈难以覆盖，改为按“活动/任务”拆解流程更清晰，所以以活动为导向更适合复杂设计项目。\n【辨析】A 简单项目、D 一般难度项目用用户为中心的低保真原型迭代就够；C 传统软件不是按项目复杂度划分的类型。","k":"sheji"},
{"id":71,"m":"练习一","t":"单选","q":"社会主义职业道德的准则和规范源于（）的道德准则和规范。","o":["无产阶级","资产阶级","中产阶级","农民阶级"],"a":0,"e":"【考点】社会主义职业道德的来源\n【答案】A\n【解析】社会主义职业道德以无产阶级的道德准则和规范为源头，强调集体主义、为人民服务，在此基础上形成各行各业的职业规范。\n【辨析】B 资产阶级、C 中产阶级、D 农民阶级都不是社会主义职业道德的理论来源。","k":"peixun"},
{"id":72,"m":"练习一","t":"单选","q":"指的是一个较小的地理区域内的计算机或数据终端通过通信设备连接起来的通信网络。","o":["局域网","广域网","城域网","无线网"],"a":0,"e":"【考点】计算机网络：局域网\n【答案】A\n【解析】题干的关键是“较小的地理区域”，例如一间办公室、一栋楼、一个校园，这种范围内互联的网络就是局域网（LAN）。\n【辨析】B 广域网跨城市跨国，C 城域网覆盖一座城市，D 无线网是按传输介质划分，不对应地理范围。","k":"jichu"},
{"id":73,"m":"练习一","t":"单选","q":"是校企团队的主要生产力。","o":["宝妈","教师","学生","后勤人员"],"a":2,"e":"【考点】校企团队的生产力\n【答案】C\n【解析】校企合作模式是学校组织学生、企业提供项目与规范，学生既是学习者也承担标注任务，因此学生是校企团队的主要生产力。\n【辨析】A 宝妈常见于众包或宝妈团队，B 教师承担教学与管理，D 后勤人员不参与标注生产。","k":"peixun"},
{"id":74,"m":"练习一","t":"单选","q":"关于ETL数据集成的主要目的是（）.","o":["将数据存储在一个PPT文件中","通过采用规模化表格，集成多个数据源","降低数据安全性","降低数据性能"],"a":1,"e":"【考点】ETL 数据集成的目的\n【答案】B\n【解析】ETL 的价值在于把分散在多个业务系统里的数据，按统一口径集成到一处（数据仓库），形成规模化、可分析的数据资产，所以目的是“集成多个数据源”。\n【辨析】A 存进 PPT 是荒谬说法，C 降低安全性、D 降低性能都是负面影响，不是目的。","k":"yunwei"},
{"id":75,"m":"练习一","t":"单选","q":"可穿戴式设备收集了大量的数据，这些数据来自于各种（）。","o":["统计报表","传感器","网络爬虫","PI接口"],"a":1,"e":"【考点】可穿戴设备的数据来源\n【答案】B\n【解析】手环、手表、心率带靠内置的加速度计、光电心率、GPS 等传感器采集数据，所以数据来自各种传感器。\n【辨析】A 统计报表是加工后的结果，C 网络爬虫采集的是网页数据，D PI 接口是工业系统对接方式（题库原样写作 PI，通常指 PI System 接口），都不产生体征数据。","k":"jichu"},
{"id":76,"m":"练习一","t":"单选","q":"不属于常用的数据预处理技术的是（）。","o":["数据清理","数据集成","数据规约","数据分析"],"a":3,"e":"【考点】数据预处理的四大任务\n【答案】D\n【解析】数据预处理的标准四步是数据清理（清洗）、数据集成、数据规约（归约）、数据变换。数据分析是预处理完成后的下一步工作，不在预处理范围内。\n【辨析】题干问“不属于”，A、B、C 都在四步之内，答案 D。","k":"yewu"},
{"id":77,"m":"练习一","t":"单选","q":"商业从业人员的职业道德就是要“诚实无欺”，这是他们的（）。","o":["职业理想","职业态度","职业义务","职业良心"],"a":3,"e":"【考点】职业道德：职业良心\n【答案】D\n【解析】职业良心是从业者内心对是非善恶的自我判断，“诚实无欺”是商业从业者内心的自我约束，属于职业良心。\n【辨析】A 职业理想是对未来的追求目标，B 职业态度是做事的心态，C 职业义务是岗位要求必须承担的责任，都不强调“内心自觉”。","k":"peixun"},
{"id":78,"m":"练习一","t":"单选","q":"包括爱岗敬业、诚实守信、公正办事、热情服务、以及为社会奉献。","o":["社会公德的主要内容","职业道德的主要内容","人际交往的主要内容","共同合作的主要内容"],"a":1,"e":"【考点】职业道德的主要内容\n【答案】B\n【解析】爱岗敬业、诚实守信、办事公道、服务群众、奉献社会，这五条正是职业道德的主要内容。\n【辨析】A 社会公德讲文明礼貌、助人为乐、爱护公物等；C 人际交往、D 共同合作都不是规范体系名称。","k":"peixun"},
{"id":79,"m":"练习一","t":"单选","q":"一个人的0可以从他们的心态、职业道德和工作态度中得出。","o":["职业态度","职业义务","职业理想","职业纪律"],"a":0,"e":"【考点】职业态度的构成\n【答案】A\n【解析】题干括号处的 OCR 符号原为“（ ）”，问的是能从心态、职业道德、工作态度中看出来的东西，即一个人对待工作的态度，也就是职业态度。\n【辨析】B 职业义务是应尽的责任，C 职业理想是追求目标，D 职业纪律是必须遵守的规章，三者都不能由“心态+态度”直接推出。","k":"peixun"},
{"id":80,"m":"练习一","t":"单选","q":"不同职业的职业道德只适用于特定的工作范围以规范0的行为。","o":["要求上进的工作人员","从事本职业的优秀员工","从事本职业的基层人员","从事本职业的工作人员"],"a":3,"e":"【考点】职业道德的适用范围\n【答案】D\n【解析】职业道德只约束本行业的从业者，题干问“规范（ ）的行为”，完整表述是“从事本职业的工作人员”，涵盖该职业的所有在岗人员。\n【辨析】A 要求上进的、B 优秀的、C 基层的，都是对人群的额外限定，缩小了适用范围，不符合“特定工作范围”这一前提。","k":"peixun"},
{"id":81,"m":"练习一","t":"单选","q":"“除了精神上的激励外，单位应该给那些尽职尽责、热爱工作的员工提供0上奖励，以体现单位对他们的重视和支持。","o":["物质","口头","特权","免罚"],"a":0,"e":"【考点】职业道德激励方式\n【答案】A\n【解析】题干说“除了精神上的激励，还应当提供（ ）上的奖励”，与精神相对的自然是物质，即奖金、补贴等物质奖励。\n【辨析】B 口头表扬仍属精神激励，C 特权、D 免罚都不是常规奖励手段。","k":"peixun"},
{"id":82,"m":"练习一","t":"单选","q":"职业道德应当独立于从业人员的物质利益，强调从业者的（）","o":["责任","权利","利益","以上都是"],"a":3,"e":"【考点】职业道德与利益的关系\n【答案】D\n【解析】职业道德要求从业者超越单纯物质利益，同时也要讲责任、讲权利、讲正当利益，三者在职业活动中都要被兼顾，所以“以上都是”。本题题库答案取包容式表述。\n【辨析】只答其中一项会把职业道德窄化成单一维度，这也是本题的设计意图。","k":"peixun"},
{"id":83,"m":"练习一","t":"单选","q":"在职业道德中表现出0是重要的，这种精神可以作为企业做大做强和员工事业成就的重要资产。","o":["奉献精神","废寝忘食","创新精神","勤俭节约"],"a":0,"e":"【考点】职业道德：奉献精神\n【答案】A\n【解析】题干说要“表现出某种精神，成为企业做大做强和员工事业成就的重要资产”，能同时支撑企业成长与个人成就的，是奉献精神。\n【辨析】B 废寝忘食是过度投入，C 创新精神强调求新求变，D 勤俭节约是成本意识，都不直接对应“做大做强的资产”这一表述。","k":"peixun"},
{"id":84,"m":"练习一","t":"单选","q":"企业的0，就是确保企业的经济活动符合社会的道德和法律规范，并尽力促进社会的进步和和谐。","o":["纳税义务","社会责任","开拓创新","公司文化"],"a":1,"e":"【考点】企业的社会责任\n【答案】B\n【解析】题干明确“确保经济活动符合社会道德与法律规范，并促进社会进步和谐”，这是企业社会责任（CSR）的定义，涵盖守法、环保、公益、员工权益等。\n【辨析】A 纳税义务只是社会责任的一部分，C 开拓创新是经营策略，D 公司文化是内部价值观，范围都不对。","k":"jichu"},
{"id":85,"m":"练习一","t":"单选","q":"企业在履行社会责任方面不仅是在遵循0，也是在利用一种有力的工具来提升企业形象以及推动企业健康成长的过程。","o":["法律要求","税务要求","道德规范","公司法要求"],"a":2,"e":"【考点】社会责任的履行依据\n【答案】C\n【解析】题干说企业履行社会责任“不仅是遵循某种要求，也是提升形象的工具”。企业行为首先受法律约束，但社会责任的内涵比法律更宽，属于道德规范层面的自觉要求，所以填道德规范。\n【辨析】A 法律要求只是底线，B 税务要求、D 公司法要求都是具体法条，涵盖不了环保、公益等社会责任内容。","k":"jichu"},
{"id":92,"m":"练习一","t":"单选","q":"IE浏览器中的0可以记录用户最近一段时间内访问的网页信息。","o":["首页","收藏夹","历史记录","保存"],"a":2,"e":"【考点】浏览器功能：历史记录\n【答案】C\n【解析】“记录最近一段时间访问过的网页”是历史记录（History）的功能，可按时间查看并支持清除。\n【辨析】A 首页是启动时打开的页面，B 收藏夹保存用户主动收藏的网址，D 保存是把网页内容存到本地，都不做“访问流水记录”。","k":"jichu"},
{"id":93,"m":"练习一","t":"单选","q":"什么是AI系统运维软件（）。","o":["用来管理AI系统的管理软件","用来开发AI系统的编程软件","用来自动化运维工作流程的软件","用来监控AI系统性能的软件"],"a":2,"e":"【考点】AI 系统运维软件的定位\n【答案】C\n【解析】题干问“什么是 AI 系统运维软件”。它区别于普通监控软件的地方在于能把运维流程自动化：巡检、发布、扩缩容、故障自愈按规则自动执行，所以核心是“自动化运维工作流程”。\n【辨析】A 管理软件太笼统，B 编程软件属开发工具，D 性能监控只是它的一个子功能，不能概括整体。","k":"yunwei"},
{"id":94,"m":"练习一","t":"单选","q":"AI系统运维软件主要针对哪些人群（）)。","o":["AI相关领域的专业人士","基础的IT运维人员","高级的IT运维人员","所有的1人员"],"a":1,"e":"【考点】AI 系统运维软件的目标人群\n【答案】B\n【解析】这类软件的设计初衷是让不具备 AI 专业背景的运维人员也能管好 AI 系统，靠模板化、自动化降低门槛，因此主要面向基础的 IT 运维人员。\n【辨析】A AI 专业人士更倾向自己写脚本或用专业平台，C 高级运维人员不是主要受众，D 表述含 OCR 乱码且范围过宽。","k":"yunwei"},
{"id":95,"m":"练习一","t":"单选","q":"使用AI系统运维软件可以达到什么效果（）。","o":["提高运维效率，降低人工成本","提高AI系统性能，加速业务流程","保障AI系统安全，减少风险","以上所有"],"a":3,"e":"【考点】AI 运维软件的价值\n【答案】D\n【解析】引入 AI 运维软件同时带来三重收益：把重复巡检交给机器，提高效率、降低人力成本；通过调优与扩缩容提升系统性能；通过异常检测与漏洞修复降低安全风险，所以“以上所有”。\n【辨析】只答一项都是以偏概全，本题用“以上所有”考整体认知。","k":"yunwei"},
{"id":96,"m":"练习一","t":"单选","q":"AI系统运维软件的主要功能是（）","o":["自动监控AI系统健康状态","自动排查运行中的问题","自动执行日常的维护任务","以上所有"],"a":3,"e":"【考点】AI 运维软件的主要功能\n【答案】D\n【解析】自动监控健康状态（发现问题）、自动排查运行问题（定位原因）、自动执行日常维护任务（巡检、备份、发布）三者构成闭环，都是主要功能。\n【辨析】三项分别在“感知—诊断—执行”三个环节，缺一不可。","k":"yunwei"},
{"id":97,"m":"练习一","t":"单选","q":"下面哪种方式可以实现A1系统运维软件的部属","o":["物理服务器","虚拟机","容骼","以上所有方式均可"],"a":3,"e":"【考点】AI 运维软件的部署方式\n【答案】D\n【解析】AI 运维软件既可装在物理服务器上，也可部署在虚拟机上，还可容器化运行（选项 C 的“容骼”是 OCR 把“容器”识别错），三种方式都支持。\n【辨析】本题是“均可”型考法，不要被单一部署形态误导。","k":"yunwei"},
{"id":98,"m":"练习一","t":"单选","q":"AI系统运维软件中的自动化任务包括哪些（）。","o":["算法调优","崩溃排查","升级和更新","以上所有任务"],"a":3,"e":"【考点】AI 运维的自动化任务\n【答案】D\n【解析】自动化任务覆盖算法调优（按指标自动调参）、崩溃排查（自动拉起并抓日志）、升级与更新（灰度发布、滚动升级），因此“以上所有任务”。\n【辨析】三项分别对应优化、故障、变更三类运维场景。","k":"yunwei"},
{"id":99,"m":"练习一","t":"单选","q":"使用AI系统运维软件，如何排查系统中的异常（）.","o":["查看系统日志","3进行根因分析","进行性能测试","以上所有方式均可"],"a":3,"e":"【考点】异常排查手段\n【答案】D\n【解析】排查异常的标准动作是：先看日志定位现象，再做根因分析（调用链、指标关联），必要时做性能测试复现压力场景，三者配合才能定位问题。\n【辨析】只看日志容易停在表象，只做根因分析缺少证据，只做性能测试覆盖不全。","k":"yunwei"},
{"id":100,"m":"练习一","t":"单选","q":"AI系统运维软件如何保证系统安全（）。","o":["检测系统异常行为","实时监控系统运行状况","尽快修复已知的漏洞","以上所有方式均可"],"a":3,"e":"【考点】系统安全保障手段\n【答案】D\n【解析】保障安全要三条腿走路：检测异常行为（入侵、越权）、实时监控运行状况（及时发现偏离）、尽快修复已知漏洞（补丁管理），都是有效手段。\n【辨析】三项分别对应“发现—监测—修补”，缺一项都会留缺口。","k":"yunwei"},
{"id":101,"m":"练习一","t":"单选","q":"AI系统运维软件的优点是（）。","o":["更加智能化","更加自动化","更加高效化","以上所有"],"a":3,"e":"【考点】AI 运维软件的优势\n【答案】D\n【解析】相比传统运维，它更智能（能预测与自愈）、更自动（减少人工操作）、更高效（批量处理与快速定位），三个优势并存。\n【辨析】智能、自动、高效是递进关系，单答一项不完整。","k":"yunwei"},
{"id":102,"m":"练习一","t":"单选","q":"AI系统运维软件的未来发展趋势是（）。","o":["开源化","更智能化","更加云化","以上所有"],"a":3,"e":"【考点】AI 运维的发展趋势\n【答案】D\n【解析】行业趋势是三条线并行：开源化降低使用门槛、更智能化向预测与自愈演进、更加云化随业务上云做弹性运维。\n【辨析】三项分别对应生态、能力、形态三个方向的演进。","k":"yunwei"},
{"id":103,"m":"练习一","t":"单选","q":"以下选项中，不属于概念设计常用方法的是（）。","o":["头脑风暴","角色扮演","用户研究","故事板"],"a":2,"e":"【考点】概念设计的常用方法\n【答案】C\n【解析】概念设计阶段的常用方法有头脑风暴、角色扮演、故事板，用来快速发散并表达设计构想。用户研究发生在更早的需求阶段，是为概念设计提供输入，不属于概念设计方法本身。\n【辨析】题干问“不属于”，A、B、D 都是概念设计手段，答案 C。","k":"sheji"},
{"id":104,"m":"练习一","t":"单选","q":"以下选项中，不属于常见的信息架构类型的是（）.","o":["层级结构","时间结构","矩阵结构","自然结构"],"a":1,"e":"【考点】信息架构的常见类型\n【答案】B\n【解析】信息架构常见四类：层级结构（树状分类）、矩阵结构（多维交叉）、自然结构（按内容自然关系组织）、线性结构（按顺序浏览）。时间结构不是独立的架构类型（时间线只是线性结构的一种表现）。\n【辨析】题干问“不属于”，A、C、D 都在四类之中。","k":"sheji"},
{"id":105,"m":"练习一","t":"单选","q":".0是指利用线框图来描述产品所包含的功能、信息展示方式以及用户交互实现的交互设计。","o":["需求分析","原型设计","概念设计","交互设计"],"a":1,"e":"【考点】原型设计\n【答案】B\n【解析】题干说“用线框图描述功能、信息展示方式与交互实现”，线框图是原型的典型载体，这个阶段叫原型设计——把抽象思路变成可看、可讨论的界面骨架。\n【辨析】A 需求分析产出需求文档，C 概念设计产出解决思路，D 交互设计关注操作流程与反馈，都不以线框图为核心产物。","k":"sheji"},
{"id":106,"m":"练习一","t":"单选","q":"在交互设计的（）阶段，需要把设计概念转化成可视化的用户界面。","o":["原型设计","概念设计","信息架构设计","视觉设计"],"a":0,"e":"【考点】原型设计阶段的任务\n【答案】A\n【解析】交互设计流程依次是需求定义、概念设计、原型设计、视觉设计。把设计概念转成可看可点的界面，是原型设计阶段的任务。\n【辨析】B 概念设计还在思路层面，C 信息架构解决内容如何组织，D 视觉设计做配色与风格，都不产生“可交互的界面原型”。","k":"sheji"},
{"id":107,"m":"练习一","t":"单选","q":"将用户界面的设计画在纸上来模拟原型，这种方法被称为（）。","o":["线框图","高保真原型","纸原型","低保真原型"],"a":2,"e":"【考点】纸原型\n【答案】C\n【解析】题干说“把界面画在纸上来模拟原型”，载体是纸，所以叫纸原型（paper prototype），是最便宜、迭代最快的原型形式。\n【辨析】A 线框图可用软件绘制，B 高保真原型接近成品，D 低保真原型是保真度维度的说法，纸原型是载体维度的说法，题干强调“画在纸上”。","k":"sheji"},
{"id":109,"m":"练习一","t":"单选","q":"大约80%的0问题可以通过使用低保真原型应用来解决。","o":["产品设计","产品开发","产品质量","产品创新"],"a":0,"e":"【考点】低保真原型的价值\n【答案】A\n【解析】大量设计问题（信息层级、流程是否顺畅、布局是否合理）在纸面或线框阶段就能暴露，用低保真原型改成本极低，所以说约八成产品设计问题可借它解决。\n【辨析】B 产品开发、C 产品质量、D 产品创新都不是原型迭代直接针对的对象。","k":"sheji"},
{"id":110,"m":"练习一","t":"单选","q":"在真正满足用户需求的产品设计过程中，（）和性价比最高的一种方式。","o":["纸上原型","高保真原型","低保真原型","虚拟现实原型"],"a":2,"e":"【考点】原型方式的性价比\n【答案】C\n【解析】题干问“真正满足用户需求、性价比最高”的方式。低保真原型制作快、修改成本低、能快速拿到用户反馈，性价比最高。\n【辨析】A 纸原型只是低保真的一种形式，B 高保真成本高、改动慢，D 虚拟现实原型成本更高。","k":"sheji"},
{"id":111,"m":"练习一","t":"单选","q":"在制作高保真原型时，有着更多的细节0和精细制作，所需的成本相比低保真原型会（）。","o":["完善，差不多","完善，高出许多","欠缺，差不多","欠缺，高出许多"],"a":1,"e":"【考点】原型保真度与成本\n【答案】B\n【解析】高保真原型要做真实配色、图标、动效和交互细节，细节更完善；投入的人力与时间明显更多，成本比低保真高出许多。\n【辨析】A、C 说“差不多”不符合事实，C、D 说细节“欠缺”方向反了。","k":"sheji"},
{"id":112,"m":"练习一","t":"单选","q":"在设计高保真原型的过程中需要投入0的时间和精力，但是这样可以大大(各方在沟通中的误解和混乱。","o":["更多，降低","更少，降低","等多，增加","更少，增加"],"a":0,"e":"【考点】高保真原型的投入与收益\n【答案】A\n【解析】高保真原型的制作门槛高，需要投入更多时间和精力；但正因为把细节都呈现出来，各方评审时看得清，反而能降低沟通中的误解和返工。\n【辨析】B 说投入更少不成立；C、D 说会增加误解，与高保真原型的价值相反。","k":"sheji"},
{"id":113,"m":"练习一","t":"单选","q":"（）是指研究如何通过人们自然的语言或机器生成的语言与计算机进行交流的技术。","o":["语音交互","机器翻译","智能客服","人机工程学"],"a":0,"e":"【考点】语音交互\n【答案】A\n【解析】题干说“研究如何通过自然语言或机器生成的语言与计算机交流”，用语音作为人机之间的沟通通道，这就是语音交互技术。\n【辨析】B 机器翻译解决跨语言转换，C 智能客服是应用形态，D 人机工程学研究人与系统的物理适配，都不是交流技术本身。","k":"jichu"},
{"id":114,"m":"练习一","t":"单选","q":"约有三分之四的日常沟通是通过0进行的。","o":["手势","语音","文字","图像"],"a":1,"e":"【考点】语音是最主要的沟通方式\n【答案】B\n【解析】研究表明日常沟通中约四分之三是靠说与听完成的，语音是人类最自然、最高效的信息传递方式。\n【辨析】手势、文字、图像都是辅助通道，占比远低于语音。","k":"xunlian"},
{"id":115,"m":"练习一","t":"单选","q":"用(来交流信息是人类普遍认可的最自然最流畅、最方便快捷的方式。","o":["图像","语言","文字","视频"],"a":1,"e":"【考点】语言的自然性\n【答案】B\n【解析】人与人之间最自然、最流畅、最省力的交流方式就是说话，用语言交流不需要专门学习，这也是语音交互成为人机交互重要方向的原因。\n【辨析】图像、文字需要编码解码，视频是复合媒介，都不如语言直接。","k":"jichu"},
{"id":116,"m":"练习一","t":"单选","q":"将语音识别和语音合成结合起来，建立一种能够实现（）。","o":["人机通讯系统","语音识别系统","语音合成系统","以上系统都可以"],"a":0,"e":"【考点】语音识别与合成的结合\n【答案】A\n【解析】语音识别把人的话转成文字（听懂），语音合成把文字转成声音（会说），两者结合就构成完整的人机语音通讯系统，实现双向交流。\n【辨析】B 只解决听，C 只解决说，D 表述不成立——单靠其中一个子系统无法完成双向通讯。","k":"xunlian"},
{"id":117,"m":"练习一","t":"单选","q":"发展人机语音通讯和新一代智能计算机的主要目标是（）)","o":["让计算机能够自主思考","让计算机拥有人类的情感","让计算机拥有人类的智慧","让计算机听懂人说话"],"a":3,"e":"【考点】人机语音通讯的目标\n【答案】D\n【解析】发展人机语音通讯与新一代智能计算机的直接目标，是让机器能听懂人说话、能和人用语音交流，这是最基础也最迫切的能力。\n【辨析】A 自主思考、B 拥有人类情感、C 拥有人类智慧都是更远的愿景，不是这一技术方向的首要目标。","k":"sheji"},
{"id":118,"m":"练习一","t":"单选","q":"（）是一种技术，其最终目的是让人类与计算机之间进行自然语言通信。","o":["语音识别","自然语言处理","图像识别","机器翻译"],"a":0,"e":"【考点】语音识别\n【答案】A\n【解析】题干说“最终目的是让人类与计算机之间进行自然语言通信”，把人说的话转成机器可处理的文本，这一步由语音识别完成，题库把它作为该技术的代表答案。\n【辨析】B 自然语言处理处理的是文本理解，C 图像识别处理视觉，D 机器翻译处理跨语言，都不解决“人机之间语音通道”这一环。","k":"jichu"},
{"id":119,"m":"练习一","t":"单选","q":"下列选项中，不属于语音交互优势的是（）。","o":["增加系统开销和困难","简单","直接","零学习成本"],"a":0,"e":"【考点】语音交互的优势\n【答案】A\n【解析】语音交互的优势是简单、直接、零学习成本（会说话就会用）。增加系统开销和实现困难是它的缺点，因此不属于优势。\n【辨析】题干问“不属于优势”，B、C、D 都是公认优势，答案 A。","k":"xunlian"},
{"id":120,"m":"练习一","t":"单选","q":"在AI系统运维软件中，下列哪个选项用于实现备份和恢复数据（）。","o":["Auditlog","Recoverypoint","Datamining","Loadbalancer"],"a":1,"e":"【考点】AI 运维软件的备份恢复功能\n【答案】B\n【解析】Recovery point（恢复点）用于标记可回滚的时间点，配合备份实现数据恢复，是备份恢复功能的核心概念。\n【辨析】A Audit log 是审计日志，C Datamining 是数据挖掘，D Load balancer 是负载均衡，都与备份恢复无关。","k":"yunwei"},
{"id":121,"m":"练习一","t":"单选","q":"在A/系统运维软件中，下列哪个工具可用于实现自动化部署（）。","o":["Jenkins","Promethus","Kibana","Nagios"],"a":0,"e":"【考点】自动化部署工具\n【答案】A\n【解析】Jenkins 是持续集成/持续部署（CI/CD）的代表工具，能按流水线自动完成拉代码、构建、测试、发布，正是“自动化部署”的实现者。\n【辨析】B Prometheus 做指标采集监控，C Kibana 做日志与数据可视化，D Nagios 做主机与服务状态监控，三者都不负责发布流程。","k":"yunwei"},
{"id":122,"m":"练习一","t":"单选","q":"AI系统运维软件中的哪个组件负责管理容器的生命周期（）。","o":["Containerorchestration","Logaggregation","Continuousintegration","Networkmonitoring"],"a":0,"e":"【考点】容器编排组件\n【答案】A\n【解析】容器的创建、调度、扩缩容、销毁由容器编排（Orchestration，如 Kubernetes）统一管理，所以负责容器生命周期的是 Container orchestration。\n【辨析】B 日志聚合只管日志收集，C 持续集成管构建发布，D 网络监控看流量与连通性，都不碰容器存活状态。","k":"yunwei"},
{"id":123,"m":"练习一","t":"单选","q":"AI系统运维软件中，下列哪个命令可用于检查系统负载（）。","o":["top","netstat","ps","grep"],"a":0,"e":"【考点】Linux 查看系统负载\n【答案】A\n【解析】top 实时显示 CPU 占用、内存使用和进程负载，是查看系统负载最直接的命令（uptime 也能看平均负载）。\n【辨析】B netstat 看网络连接与端口，C ps 列进程快照但不显示整体负载，D grep 是文本过滤工具。","k":"yunwei"},
{"id":124,"m":"练习一","t":"单选","q":"在使用AI系统运维软件时，下列哪个技术可用于限制用户对系统资源的访问)。","o":["Encryption","Accesscontrol","Loadtesting","Vulnerabilityscanning"],"a":1,"e":"【考点】访问控制\n【答案】B\n【解析】限制谁能访问哪些资源，靠的是访问控制（Access control）：账号权限、角色、最小授权原则，落地形式包括 ACL、RBAC。\n【辨析】A Encryption 解决数据保密，C Load testing 压测性能，D Vulnerability scanning 扫漏洞，都不做权限边界划分。","k":"yunwei"},
{"id":125,"m":"练习一","t":"单选","q":"AI系统运维软件中，下列哪个选项可用于定位问题并进行故障排除（）","o":["Remotemonitoring","Troubleshootingguide","Systemsnapshot","Applicationfirewall"],"a":0,"e":"【考点】远程监控与故障定位\n【答案】A\n【解析】AI 运维软件通过远程监控（采集指标、日志、链路状态并集中呈现）发现异常、定位问题并支撑排障，因此选 Remote monitoring。\n【辨析】B 故障排查指南只是文档，C 系统快照是某一刻的状态备份，D 应用防火墙拦攻击，都不是“定位问题”的核心手段。","k":"yunwei"},
{"id":126,"m":"练习一","t":"单选","q":"（）与人工客服通过声音进行互动的方式被称为语音交互。","o":["自然语言对话","视频","图像","书写"],"a":0,"e":"【考点】语音交互的定义\n【答案】A\n【解析】人通过说话、机器通过语音回应，双方用自然语言对话，这种交互方式就是语音交互。\n【辨析】B 视频、C 图像是视觉通道，D 书写是文字通道，都不以“声音对声音”为核心。","k":"xunlian"},
{"id":127,"m":"练习一","t":"单选","q":"在App应用中使用语音识别技术会遇到(的主要问题。","o":["语音质量不佳","硬件设备损坏","方言种类繁多和口音各异","环境噪音"],"a":2,"e":"【考点】语音识别落地的难点\n【答案】C\n【解析】中文方言与口音差异极大（同一句话在不同地区发音差别明显），会导致声学模型识别率骤降，这是 App 接入语音识别最常见的硬骨头。\n【辨析】A 语音质量、D 环境噪音可靠降噪与阵列麦克风缓解，属于可工程化的问题；B 硬件损坏是设备故障，不是技术难点。","k":"xunlian"},
{"id":128,"m":"练习一","t":"单选","q":"语音特征提取的。","o":["目的是从语音波形中提取随时间变化的语音特征序列","目的是从语音信号中恢复原始语音波形","目的是对语音信号进行压缩和编码","目的是为语音识别模型提供输入"],"a":0,"e":"【考点】语音特征提取的目的\n【答案】A\n【解析】语音特征提取把原始波形切成短帧，逐帧算出 MFCC、滤波器组能量等参数，得到随时间变化的特征序列，供声学模型使用。\n【辨析】B 恢复原始波形是语音合成要做的，C 压缩编码属于编解码，D 是结果而不是提取本身的目的。","k":"xunlian"},
{"id":129,"m":"练习一","t":"单选","q":"声学模型是通过训练0所得到的，在语音识别中起到重要的作用。","o":["语音特征","语音信号","语音文本","语音语料库"],"a":0,"e":"【考点】声学模型\n【答案】A\n【解析】声学模型学习“语音特征序列 → 音素/状态”的对应关系，训练数据就是提取好的语音特征，它决定了“听不听得清”。\n【辨析】B 原始语音信号需先提特征才能训练，C 语音文本用于语言模型，D 语料库是数据集合而非模型输入形式。","k":"xunlian"},
{"id":130,"m":"练习一","t":"单选","q":"语音识别通常被视为一种（）任务，其中计算机程序必须学会将声音信号映射到特定的文本或指令。","o":["音乐播放技术","语音合成技术","模式分类","人机交互技术"],"a":2,"e":"【考点】语音识别的任务本质\n【答案】C\n【解析】语音识别要把连续的声音信号判定为某个音素、字或词，本质是“给定输入、判定所属类别”，属于模式分类任务。\n【辨析】A 音乐播放是应用，B 语音合成方向相反（文转音），D 人机交互是更大的范畴，不能说明识别本身的计算性质。","k":"jichu"},
{"id":131,"m":"练习一","t":"单选","q":"基于0的基本原理，是语音识别技术的核心。","o":["人工智能","统计模式识别","语言学","机器学习"],"a":1,"e":"【考点】语音识别的核心理论\n【答案】B\n【解析】传统语音识别建立在统计模式识别之上：用 HMM/GMM 或深度网络估计声学概率，再用语言模型算句子的概率，取联合概率最大者。\n【辨析】A 人工智能是学科总称，C 语言学提供先验知识但不是核心算法，D 机器学习是更大框架，只有 B 点出了“统计+模式”这一核心。","k":"xunlian"},
{"id":132,"m":"练习一","t":"单选","q":"京东众智提供完善的数据标注0，并依据不同的数据需求定制专业的标注模板，从而确保数据标注的精确性。","o":["生活体系","培训体系","放假体系","饮食体系"],"a":1,"e":"【考点】标注平台的培训体系\n【答案】B\n【解析】题干说平台“定制专业标注模板、确保精确性”，靠的是把规则、案例、考核固化下来的培训体系，让标注员按统一口径作业。\n【辨析】生活体系、放假体系、饮食体系都与标注质量无关，是明显的凑数项。","k":"peixun"},
{"id":133,"m":"练习一","t":"单选","q":"通过完善的数据标注培训体系，0能够快速掌握数据标注技巧并成为专业的","o":["普通人，数据标注员","数据标注员，普通人","普通人，计算机","计算机，人"],"a":0,"e":"【考点】培训体系的作用\n【答案】A\n【解析】完整的培训体系能让零基础的普通人快速掌握标注规范与工具操作，成长为合格的数据标注员，这也是标注行业能规模化供给人力的原因。\n【辨析】B 顺序颠倒（标注员不需要被培训成普通人），C、D 把计算机当培训对象，方向错误。","k":"peixun"},
{"id":134,"m":"练习一","t":"单选","q":"初级数据标注员需要掌握其所涉及的行业基础知识，以确保（）。","o":["具备简单的人工智能相关知识","具有简单的大数据处理相关知识","熟悉数据标注的使用范围及形式","所有类型数据标注准确率为100%"],"a":3,"e":"【考点】初级标注员的能力要求\n【答案】D\n【解析】题库把“掌握行业基础知识”的目的落在结果上——确保各类标注的准确率达到要求（题库表述为 100%），即懂行业才标得准。\n【辨析】A、B 是把要求说小了（只懂 AI 或大数据不够），C 是过程描述而非目的。","k":"peixun"},
{"id":135,"m":"练习一","t":"单选","q":"中级数据标注员不仅能够进行更加专业的标注还可以为初级质检员的标注数据进行简单的)。","o":["备份","删除","质检","查看"],"a":2,"e":"【考点】中级标注员职责\n【答案】C\n【解析】中级标注员除了自己做更专业的标注，还能对初级标注员的成果做初步质量检查，即承担简单的质检工作，这是岗位晋升后的典型职责。\n【辨析】A 备份、B 删除、D 查看都不是质量把关动作，只有质检能体现“专业度提升”。","k":"peixun"},
{"id":136,"m":"练习一","t":"单选","q":"O是负责管理数据标注团队、总结数据标注经验以及为数据标注员提供培训的职位。","o":["初级数据标注员","中级数据标注员","高级数据标注员","保安"],"a":2,"e":"【考点】高级标注员职责\n【答案】C\n【解析】管理标注团队、总结经验、培训新人属于团队与质量管理职责，由高级数据标注员（或标注组长/项目主管）承担。\n【辨析】初级、中级标注员以执行标注为主，保安与标注业务无关。","k":"peixun"},
{"id":137,"m":"练习一","t":"单选","q":"一般来说，对于没有任何标注经验的数据标注员，质量提升计划的周期通常为（）。","o":["一分钟","一个小时","半天","一周"],"a":3,"e":"【考点】标注质量提升周期（新人）\n【答案】D\n【解析】对完全没有标注经验的新人，需要完整的规范讲解、示例演练、试标与返修，形成稳定质量通常以一周为一个训练周期。\n【辨析】一分钟、一小时、半天都太短，不足以让新人形成稳定的标注习惯。","k":"peixun"},
{"id":138,"m":"练习一","t":"单选","q":"对于有2周及以上标注经验的标注员，质量提升计划的周期通常为（）。","o":["一个小时","一天","一个月","一年脱产学习"],"a":1,"e":"【考点】标注质量提升周期（2 周以上）\n【答案】B\n【解析】已有两周以上经验的人基本掌握了工具与规范，只需针对近期错误做一天的集中复盘与巩固即可。\n【辨析】一个月、一年周期过长，一小时又不足以覆盖返修与复盘。","k":"peixun"},
{"id":139,"m":"练习一","t":"单选","q":"对于有超过一个月的标注经验的数据标注员通常会有一个0培训计划。","o":["半天强化","十天理论学习","半年脱产学习","一年脱产学习"],"a":0,"e":"【考点】标注质量提升周期（一个月以上）\n【答案】A\n【解析】一个月以上的熟练标注员问题集中在个别难点与边界案例，用半天的强化训练集中攻克即可。\n【辨析】十天理论学习、半年或一年脱产学习都远超实际需要。","k":"peixun"},
{"id":140,"m":"练习一","t":"单选","q":"对于没有质检经验的新入职质检员，他们通常需要进行为期0以提升其质检水平。","o":["2天试质检期","晋升激励","半年脱产学习","一年脱产学习"],"a":0,"e":"【考点】新质检员的培养\n【答案】A\n【解析】没有质检经验的新人，需要在真实项目里先做 2 天试质检，由老质检员复核其判定，确认眼光一致后才独立上岗。\n【辨析】B 晋升激励是管理手段，C、D 脱产半年或一年不符合质检岗位的短周期培养特点。","k":"peixun"},
{"id":141,"m":"练习一","t":"单选","q":"对于具有2周或以上质检经验的质检员，一般会在0内进行质量提升计划的巩固培训。","o":["自学半个小时","半天","半年脱产学习","一年脱产学习"],"a":1,"e":"【考点】质检员的质量巩固\n【答案】B\n【解析】两周以上的质检员已具备基本判断力，用半天做质量提升计划的巩固培训（对齐最新规范、复盘争议案例）即可。\n【辨析】半小时太短覆盖不了案例复盘，半年、一年脱产不符合在岗培训的实际。","k":"peixun"},
{"id":142,"m":"练习一","t":"单选","q":"通常情况下，计划了针对质检员进行0，只有那些在质检方面已经有两个月及以上经验的人才有资格参加这个计划。","o":["半年脱产学习","一年脱产学习","半天技巧提升","不需要提升"],"a":2,"e":"【考点】质检员的进阶培训\n【答案】C\n【解析】题干限定“已有两个月及以上经验才有资格参加”，说明这是进阶技巧训练，用半天做技巧提升最合适。\n【辨析】半年、一年脱产学习与“技巧提升”定位不符，D 不需要提升与“设置计划”矛盾。","k":"peixun"},
{"id":143,"m":"练习一","t":"单选","q":"要进行机器学习，首先需要0，这是人工智能学习的第一步。","o":["构建数据集","确定模型的类型","数据采集","对数据集进行分析"],"a":2,"e":"【考点】机器学习的第一步\n【答案】C\n【解析】机器学习要有数据才能学，所以第一步是数据采集——把与任务相关的原始数据收集起来，之后才谈清洗、标注、建模。\n【辨析】A 构建数据集是采集之后的事，B 定模型类型更靠后，D 数据分析在数据到手之后进行。","k":"xunlian"},
{"id":144,"m":"练习一","t":"单选","q":"在开始收集数据之前，必须首先确定（）。","o":["数据来源","数据类型","数据用途","数据规模"],"a":0,"e":"【考点】数据采集的前置条件\n【答案】A\n【解析】动手采集前必须先明确“数据从哪里来”（业务系统、日志、传感器、爬虫、公开数据集等），来源决定了采集方式、口径与合法性。\n【辨析】B 数据类型、D 数据规模都由来源决定，C 数据用途是更上层的业务目标，不是采集动作的直接前置。","k":"yewu"},
{"id":145,"m":"练习一","t":"单选","q":"规划数据采集时，需要考虑0，以确定数据的范围和数量。","o":["数据质量要求","数据处理方法","数据存储方式","行业与应用定位"],"a":3,"e":"【考点】采集规划的关键依据\n【答案】D\n【解析】要采多少、采多广，取决于这个数据和行业、应用场景的定位：不同场景对样本量、维度、精度的要求差别很大，所以要先定行业与应用定位。\n【辨析】A 质量要求、B 处理方法、C 存储方式都是定位确定之后的执行细节。","k":"yewu"},
{"id":146,"m":"练习一","t":"单选","q":"在进行数据标注之前，我们需要通过预处理步骤来对数据进行0，以确保其达到标准要求。","o":["标准化","删除","无限复制","置空"],"a":0,"e":"【考点】标注前的预处理\n【答案】A\n【解析】标注前要把数据整理成统一规格（尺寸、命名、格式、编码、字段口径），即标准化，否则标注工具无法批量处理、标注结果也难以对齐。\n【辨析】B 删除、C 无限复制、D 置空都会破坏数据，不是预处理手段。","k":"xunlian"},
{"id":147,"m":"练习一","t":"单选","q":"经过数据预处理，数据挖据的效率得到了0，同时也(了数据挖掘所需要的时间。","o":["提高，延长","降低，延长","提高，降低","降低，降低"],"a":2,"e":"【考点】预处理的价值\n【答案】C\n【解析】预处理去掉脏数据与冗余，模型训练和挖掘的效率提高；同时因为少走弯路、少返工，整体所需时间反而降低。\n【辨析】A、B 说时间延长与预处理的目的相反，D 说效率降低也违背常识。","k":"yewu"},
{"id":148,"m":"练习一","t":"单选","q":"将数据进行规整化、删除异常数据、修正数据错误、删除重复数据等操作，称之为（）。","o":["数据清理","数据集成","数据变换","数据归约"],"a":0,"e":"【考点】数据清理的内容\n【答案】A\n【解析】规整化、删异常、修错误、去重复，这些都是在处理“脏数据”，属于数据清理（清洗）。\n【辨析】B 集成是把多源数据合并，C 变换是做归一化等格式转换，D 归约是降维减量，都不针对数据本身的错误与冗余。","k":"jichu"},
{"id":149,"m":"练习一","t":"单选","q":"指把来自多个不同数据源的数据合并并存储在一个单一的地方，叫做（）。","o":["数据清理","数据集成","数据变换","数据归约"],"a":1,"e":"【考点】数据集成\n【答案】B\n【解析】把来自多个不同数据源的数据合并、统一存储到一处，解决的是“数据分散、口径不一”的问题，即数据集成。\n【辨析】A 清理处理脏数据，C 变换做格式规范化，D 归约减量，都不涉及多源合并。","k":"yunwei"},
{"id":150,"m":"练习一","t":"单选","q":"在挖掘数据时，我们需要理解挖掘任务和数据本身内容，然后利用有用的特征来缩减数据规模这个过程就是0","o":["数据清理","数据集成","数据变换","数据归约"],"a":3,"e":"【考点】数据归约\n【答案】D\n【解析】用有用的特征缩减数据规模（降维、抽样、离散化、特征选择），在尽量保留信息的前提下减小数据量，就是数据归约（规约）。\n【辨析】A 清理管质量，B 集成管合并，C 变换管格式，都不以减少数据量为目标。","k":"xunlian"},
{"id":151,"m":"练习一","t":"单选","q":"Kettle通过提供O的功能，实现了将所有工作整合起来的目的。","o":["语音库","资源库","视频库","图片库"],"a":1,"e":"【考点】Kettle 资源库\n【答案】B\n【解析】Kettle 用资源库（Repository）集中保存作业、转换、数据库连接等元数据，团队成员共享同一套资源，所以能把所有工作整合起来。\n【辨析】语音库、视频库、图片库与 ETL 工具的功能无关。","k":"yewu"},
{"id":152,"m":"练习一","t":"单选","q":"在Kette中，数据的提取过程可以简述为先创建作业，再在该作业中包含0转换步骤。","o":["一个,多个","多个,一个","多个，多个","以上都不对"],"a":0,"e":"【考点】Kettle 作业与转换的关系\n【答案】A\n【解析】Kettle 中一个作业（Job）负责调度与流程控制，可以包含多个转换（Transformation）步骤，由作业决定先跑哪个、失败怎么办。\n【辨析】B、C 把“一个作业包含多个转换”说反或说成多对多，D 直接否定，都不对。","k":"yewu"},
{"id":153,"m":"练习一","t":"单选","q":"在Kettle中，数据转换的过程主要是涉及操作O。这个过程需要进行SQL语句的编写、执行，并且还需要配置数据库地址等一系列操作步骤。","o":["音频","视频","数据库","图片"],"a":2,"e":"【考点】Kettle 转换操作对象\n【答案】C\n【解析】Kettle 的数据转换要读写各类数据表，需配置数据库连接、编写并执行 SQL，操作对象是数据库。\n【辨析】音频、视频、图片都不是 ETL 处理的结构化数据对象。","k":"yewu"},
{"id":154,"m":"练习一","t":"单选","q":"一般数据标注项目是由需求方或0发起的。","o":["项目发起人","保安","总经理","财务经理"],"a":0,"e":"【考点】标注项目的发起方\n【答案】A\n【解析】标注项目通常由有模型训练需求的一方（需求方）或其指定的项目发起人立项，明确目标、预算与交付要求。\n【辨析】保安、总经理、财务经理都不是业务发起角色（总经理可能审批，但发起人是需求侧）。","k":"xunlian"},
{"id":155,"m":"练习一","t":"单选","q":"需求方应该明确表达他们想要的所需模型效果，并与0合作制定标注规则，以满足需求。","o":["物业经理","模型师","财务经理","人事经理"],"a":1,"e":"【考点】标注规则的共同制定者\n【答案】B\n【解析】需求方要的是模型效果，而“怎么标才对应模型要学的东西”由模型师判断，所以需求方需与模型师一起定标注规则。\n【辨析】物业、财务、人事经理都不掌握模型技术细节。","k":"xunlian"},
{"id":156,"m":"练习一","t":"单选","q":"标注规则的确定完成后，将由负责实施项目。","o":["物业经理","总经理","项目经理","财务经理"],"a":2,"e":"【考点】标注项目的实施负责人\n【答案】C\n【解析】规则定好后，排期、分工、进度与质量把控由项目经理负责落地执行，是项目的实际操盘人。\n【辨析】总经理管战略审批，财务经理管钱，物业经理与标注无关。","k":"xunlian"},
{"id":157,"m":"练习一","t":"单选","q":"在使用AI系统运维软件时，下列哪个工具可用于监控应用性能（）","o":["Grafana","Hadoop","Ansible","Wireshark"],"a":0,"e":"【考点】监控应用性能工具\n【答案】A\n【解析】Grafana 把采集到的指标做成实时看板与告警面板，是监控应用性能（响应时间、错误率、资源占用）最常用的可视化工具。\n【辨析】B Hadoop 是分布式存储计算框架，C Ansible 是配置管理与批量部署工具，D Wireshark 抓包分析网络协议。","k":"yunwei"},
{"id":158,"m":"练习一","t":"单选","q":"在AI系统运维软件中，下列哪个工具可用于收集和展示日志信息（）。","o":["ELKstack","Puppet","Jenkins","Nagios"],"a":0,"e":"【考点】日志收集与展示\n【答案】A\n【解析】ELK Stack（Elasticsearch + Logstash + Kibana）是日志采集、存储、检索与展示的标准组合，Kibana 负责可视化。\n【辨析】B Puppet 做配置管理，C Jenkins 做持续集成，D Nagios 做状态监控，都不以日志为核心。","k":"yunwei"},
{"id":159,"m":"练习一","t":"单选","q":"在A/系统运维软件中，下列哪个选项可用于保证系统高可用性（）)。","o":["Loadbalancer","Backupandrecovery","Continuousintegration","Networksegmentation"],"a":0,"e":"【考点】系统高可用\n【答案】A\n【解析】高可用靠冗余与流量分发：负载均衡器把请求分摊到多台实例，某台挂了自动摘除，服务不中断，所以选 Load balancer。\n【辨析】B 备份恢复解决的是数据不丢，恢复需要时间；C 持续集成管发布；D 网络分段是安全隔离手段。","k":"yunwei"},
{"id":160,"m":"练习一","t":"单选","q":"在使用AI系统运维软件时，下列哪个工具可用于验证系统安全性（）。","o":["Penetrationtesting","Loadtesting","Codereview","Performancetuning"],"a":0,"e":"【考点】安全验证手段\n【答案】A\n【解析】验证系统安全性最直接的办法是渗透测试（Penetration testing）：模拟攻击者尝试突破，看防得住防不住。\n【辨析】B 负载测试测性能，C 代码审查查实现问题，D 性能调优做优化，都不能验证真实攻击面。","k":"yunwei"},
{"id":161,"m":"练习一","t":"单选","q":"AI系统运维软件中，以下哪项不是典型的系统管理员的任务（）","o":["安装和更新软件","修复硬件故障","系统配置管理","数据备份与恢复"],"a":1,"e":"【考点】系统管理员的职责边界\n【答案】B\n【解析】装软件、管配置、做备份恢复都是系统管理员的日常；硬件故障（换硬盘、修主板）通常由硬件厂商或机房运维负责，不属于系统管理员典型任务。\n【辨析】题干问“不是”，A、C、D 都是典型任务。","k":"yunwei"},
{"id":162,"m":"练习一","t":"单选","q":"下面哪项操作不是AI系统运维软件中常见的系统监控任务（）","o":["监视服务器的性能","观察应用程序的运行情况","跟踪网络流量","维护用户设备"],"a":3,"e":"【考点】系统监控的范围\n【答案】D\n【解析】监控看的是服务器性能、应用运行状态、网络流量这些系统侧指标；维护用户设备（修电脑、装驱动）属于终端支持，不在监控范畴。\n【辨析】题干问“不是”，A、B、C 都是标准监控项。","k":"yunwei"},
{"id":163,"m":"练习一","t":"单选","q":"AI系统运维软件的自动化功能主要涉及以下哪些方面(","o":["配置管理","虚拟化技术","自动扩展","批量处理"],"a":3,"e":"【考点】自动化功能的范畴\n【答案】D\n【解析】题库把自动化功能归于批量处理——把大量重复操作（批量发布、批量巡检、批量扩缩容）交给系统一次执行。\n【辨析】A 配置管理、B 虚拟化、C 自动扩展都是相关能力，但题库设定的答案是批量处理这一落地形式。","k":"yunwei"},
{"id":164,"m":"练习一","t":"单选","q":"AI系统运维软件怎么帮助运维管理员更好地进行故障分析（）。","o":["通过日志记录跟踪问题","对故障进行快速恢复","追踪资源的使用情况","执行自动化的脚本"],"a":0,"e":"【考点】故障分析手段\n【答案】A\n【解析】故障分析要从证据出发，日志记录了异常发生的时间、堆栈和调用链，是定位根因的第一手材料。\n【辨析】B 快速恢复是止损不是分析，C 资源使用情况是辅助指标，D 自动化脚本是处置手段，都不能替代“看日志找原因”。","k":"yunwei"},
{"id":165,"m":"练习一","t":"单选","q":"用法律的方式保护作家、艺术家和科学家的创意成果，同时鼓励对社会有益的作品创作和传播，促进社会主义文化和科学的发展，这是0的目的。","o":["《知识产权法》","《网络安全法》","《合同法》","《劳动法》"],"a":0,"e":"【考点】知识产权法的立法目的\n【答案】A\n【解析】题干说“用法律保护作家、艺术家、科学家的创意成果，鼓励有益作品创作传播”，这正是知识产权法的目的：保护创造、平衡传播、促进文化科学繁荣。\n【辨析】网络安全法管网络运行安全，合同法管交易关系，劳动法管劳动关系，都不针对创意成果。","k":"jichu"},
{"id":167,"m":"练习一","t":"单选","q":"根据《计算机软件保护条例》，任何中国公民，法人或其他组织，向外国人授权或转让软件著作权时，都必须遵守(的法规。","o":["《中华人民共和国技术进出口管理条例","《合同法》","《劳动法》","《刑法》"],"a":0,"e":"【考点】软件著作权涉外转让\n【答案】A\n【解析】向外国人许可或转让软件著作权，涉及技术出口管理，须遵守《技术进出口管理条例》，按技术进出口的流程审批登记。\n【辨析】B 合同法管民事合同，C 劳动法管用工，D 刑法管犯罪，都不管技术出口。","k":"jichu"},
{"id":168,"m":"练习一","t":"单选","q":"“为了保护计算机软件著作权人的权益，调整计算机软件在开发、传播和使用中发生的利益关系，鼓励计算机软件的开发与应用，促进软件产业和国民经济信息化的发展，根据《中华人民共和国著作权法》\"，这是0的立法目的。","o":["《网络安全法》","《合同法》","《劳动法》","《计算机软件保护条例》"],"a":3,"e":"【考点】《计算机软件保护条例》的立法目的\n【答案】D\n【解析】题干引文明确提到“保护计算机软件著作权人权益、调整开发传播使用中的利益关系、促进软件产业发展”，且依据《著作权法》制定，这正是《计算机软件保护条例》的立法目的。\n【辨析】网络安全法、合同法、劳动法的立法目的都不涉及软件著作权。","k":"jichu"},
{"id":169,"m":"练习一","t":"单选","q":"《计算机软件保护条例》规定，侵犯软件著作权的赔偿数额，依照0第四十九条的规定确定。","o":["《合同法》","《刑法》","《中华人民共和国著作权法》","《劳动法》"],"a":2,"e":"【考点】侵权赔偿的法律依据\n【答案】C\n【解析】《计算机软件保护条例》规定，侵权赔偿数额依照《著作权法》的相关条款确定，即软件著作权纠纷在赔偿计算上参照著作权法执行。\n【辨析】合同法管违约责任，刑法管刑责，劳动法管工资工时，都不是赔偿数额的计算依据。","k":"jichu"},
{"id":170,"m":"练习一","t":"单选","q":"《中华人民共和国计算机信息网络国际联网管理暂行规定实施办法》规定，计算机信息网络直接进行国际联网，必须使用0国家公用电信网提供的国际出入口信道。","o":["人社部","国务院","教育部","邮电部"],"a":3,"e":"【考点】国际联网出入口信道\n【答案】D\n【解析】按《计算机信息网络国际联网管理暂行规定实施办法》，国际联网必须使用邮电部（今工信部体系）国家公用电信网提供的国际出入口信道。\n【辨析】人社部、国务院、教育部都不管国际通信信道，选项 D 是历史主管部门名称。","k":"jichu"},
{"id":171,"m":"练习一","t":"单选","q":"《中华人民共和国计算机信息网络国际联网管理暂行规定实施办法》规定，个人、法人和其他组织用户使用的计算机或者计算机信息网络必须通过0进行国际联网，不得以其他方式进行国际联","o":["接入网络","城域网络","自制网络","局域网络"],"a":0,"e":"【考点】国际联网的接入方式\n【答案】A\n【解析】该办法要求个人、法人和其他组织的计算机或网络必须通过接入网络（有资质的互联单位）进行国际联网，不得自行以其他方式直连。\n【辨析】城域网、自制网络、局域网都不能直接作为国际联网的合法通道。","k":"jichu"},
{"id":172,"m":"练习一","t":"单选","q":"ETL是是一种用于数据仓库构建和数据集成的技术，它的英文全称是（）。","o":["Extraction-Transformaction-Loading","Earth-True-Land","Evening-Teach-Land","Evening-Time-Logo"],"a":0,"e":"【考点】ETL 英文全称\n【答案】A\n【解析】ETL 是 Extract（抽取）、Transform（转换）、Load（加载）三个词的缩写，描述数据从源系统取数、加工、写入目标库的过程。\n【辨析】B、C、D 都是毫不相干的英文词组拼凑，属于干扰项。","k":"yunwei"},
{"id":174,"m":"练习一","t":"单选","q":"ETL数据整合工具最终用户提交界面应该具备O特征。","o":["简洁明了，易于使用","支持多种所见即所得编辑器","具备数据验证和输入格式检查功能","提供多种语言界面供用户选择"],"a":2,"e":"【考点】ETL 工具的用户界面要求\n【答案】C\n【解析】ETL 最终用户要填参数、导数据，界面必须做数据验证与输入格式检查，防止非法值流入，这是题库设定的核心特征。\n【辨析】A 易用、B 所见即所得、D 多语言都是加分项，但不如“校验输入”直接关系数据正确性。","k":"sheji"},
{"id":175,"m":"练习一","t":"单选","q":"不是ETL数据整合工具的主要功能的是","o":["数据清洗","数据转换","数据清空","数据加载"],"a":2,"e":"【考点】ETL 工具的主要功能\n【答案】C\n【解析】ETL 的核心功能是清洗（Clean）、转换（Transform）、加载（Load）。“数据清空”是破坏性操作，不是 ETL 功能。\n【辨析】题干问“不是”，A、B、D 都在 ETL 三环节之内。","k":"yewu"},
{"id":176,"m":"练习一","t":"单选","q":"（）是一种能够帮助用户在互联网上获取所需信息的工具。","o":["搜索引擎","OutlookExpress","Netants","Telnet"],"a":0,"e":"【考点】搜索引擎\n【答案】A\n【解析】题干说“帮助用户在互联网上获取所需信息”，靠关键词检索海量网页并排序返回，这就是搜索引擎。\n【辨析】B Outlook Express 是邮件客户端，C NetAnts 是早期下载工具，D Telnet 是远程登录协议。","k":"jichu"},
{"id":177,"m":"练习一","t":"单选","q":"（）是国内最受欢迎的搜索引擎之一，以提供卓越的中文信息搜索和传播技术闻名全球。","o":["微信","百度","淘宝","小红书"],"a":1,"e":"【考点】中文搜索引擎\n【答案】B\n【解析】百度以中文网页检索与中文信息传播技术著称，是国内市场份额最大的中文搜索引擎。\n【辨析】微信是社交，淘宝是电商，小红书是内容社区，都不是搜索引擎。","k":"jichu"},
{"id":178,"m":"练习一","t":"单选","q":"网络服务商提供了0功能来帮助人们更好地在不断更新的信息海洋中搜索所需信息。","o":["电子邮件","聊天软件","搜索引擎","BS"],"a":2,"e":"【考点】搜索引擎的提供方\n【答案】C\n【解析】网络服务商（搜索引擎公司）提供搜索功能，帮用户在不断膨胀的信息海洋里快速定位所需内容。\n【辨析】电子邮件、聊天软件解决通信，BS 指浏览器/服务器架构，都不是检索工具。","k":"jichu"},
{"id":179,"m":"练习一","t":"单选","q":"（）并不是一个正确的E-mail地址。","o":["guest@sincom.cn","student-1@1onet","mike@elong.net","liu%26net"],"a":3,"e":"【考点】E-mail 地址格式\n【答案】D\n【解析】合法邮箱地址形如“用户名@域名”，必须有且只有一个 @，且域名部分要含点号。D 项 liu%26net 既无 @ 也无域名结构，不是有效地址。\n【辨析】A、B、C 都符合“用户名@域名”格式（B 的域名拼写不完整但结构仍是邮箱形式），只有 D 完全不符。","k":"jichu"},
{"id":180,"m":"练习一","t":"单选","q":"以下哪个软件是用来发送和接收电子邮件的客户端（）。","o":["IE","OutlookExpress","QQ","微信"],"a":1,"e":"【考点】电子邮件客户端\n【答案】B\n【解析】Outlook Express 是微软早期的邮件客户端，专门用于收发、管理电子邮件，支持多账号与通讯簿。\n【辨析】IE 是浏览器，QQ 与微信是即时通讯工具，虽然也能传消息，但不是“电子邮件客户端”。","k":"jichu"},
{"id":181,"m":"练习一","t":"单选","q":"（）是电子邮件的英文简称","o":["QQ","E-mail","PS","JPG"],"a":1,"e":"【考点】电子邮件的英文简称\n【答案】B\n【解析】电子邮件英文为 Electronic mail，简称 E-mail，格式是“用户名@域名”。\n【辨析】QQ 是即时通讯产品名，PS 是图像处理软件，JPG 是图片格式，都与邮件无关。","k":"jichu"},
{"id":182,"m":"练习一","t":"单选","q":"在AI系统中，下列哪个命令可以用来查看内存使用情况（）。","o":["free","ping","traceroute","netstat"],"a":0,"e":"【考点】Linux 查看内存\n【答案】A\n【解析】free 命令显示总内存、已用、空闲、缓冲与缓存情况，是查看内存使用最常用的工具（free -h 更易读）。\n【辨析】ping 测网络连通，traceroute 查路由路径，netstat 看连接与端口，都不反映内存。","k":"jichu"},
{"id":183,"m":"练习一","t":"单选","q":"在AI系统中，下列哪个命令可以用来重启系统（）。","o":["poweroff","shutdown-rnow","reboot","init6"],"a":1,"e":"【考点】Linux 重启命令\n【答案】B\n【解析】shutdown -r now 表示立即重启（-r 是 reboot，now 是立即）。题库把这一项作为标准答案。\n【辨析】poweroff 是关机，reboot 与 init 6 也能重启但不在选项中完整出现，本题按选项设定作答。","k":"jichu"},
{"id":184,"m":"练习一","t":"单选","q":"在AI系统中，下列哪个命令可以用来查看网络连接情况（）。","o":["netstat","dig","nslookup","host"],"a":0,"e":"【考点】Linux 查看网络连接\n【答案】A\n【解析】netstat 列出当前 TCP/UDP 连接、监听端口与路由表，是排查“谁在连、连了哪些端口”的首选命令。\n【辨析】dig、nslookup、host 都是域名解析查询工具，只看 DNS 记录，不看连接状态。","k":"jichu"},
{"id":185,"m":"练习一","t":"单选","q":"下列哪个命令可以用来查看当前AI系统中的用户（）.","o":["whoami","who","users","uptime"],"a":1,"e":"【考点】查看登录用户\n【答案】B\n【解析】who 列出当前登录到系统的所有用户及其终端来源，适合多人共用服务器时确认在线情况。\n【辨析】whoami 只显示“我自己是谁”，users 只列用户名，uptime 显示运行时长与负载，都不能列出全部在线用户。","k":"jichu"},
{"id":186,"m":"练习一","t":"单选","q":"在AI系统中，下列哪个命令可以查看日志文件内容（）。","o":["more","cat","tail","head"],"a":2,"e":"【考点】查看日志文件\n【答案】C\n【解析】日志会不断追加，最新内容在末尾，所以查日志用 tail（tail -f 可实时跟踪）。\n【辨析】more 分页看全文，cat 一次输出全部（大日志会刷屏），head 只看开头，都不如 tail 贴合“看最新日志”。","k":"yunwei"},
{"id":187,"m":"练习一","t":"单选","q":"下列哪个命令可以用来压缩文件（）","o":["zip","tar","gzip","allofabove"],"a":3,"e":"【考点】压缩命令\n【答案】D\n【解析】zip 做 zip 压缩、tar 打包归档、gzip 做 gzip 压缩，三者都是压缩/打包工具，所以“以上都是”。\n【辨析】本题用“all of above”考你是否知道这三条命令都能压缩，而不是只有某一个。","k":"jichu"},
{"id":188,"m":"练习一","t":"单选","q":"AI系统的运维软件中，\"AI\"代表的是什么(","o":["人工智能","应用接口","自动化标识","活动实例"],"a":0,"e":"【考点】AI 的含义\n【答案】A\n【解析】AI 是 Artificial Intelligence 的缩写，中文为人工智能，指让机器具备感知、学习、推理、决策等智能行为的技术。\n【辨析】应用接口是 API，自动化标识、活动实例都不是 AI 的英文含义。","k":"yunwei"},
{"id":189,"m":"练习一","t":"单选","q":"AI系统的运维软件通常包括哪些功能O。","o":["初步策划、监控和维护","网络拓扑分析、性能度量和安全检查","数据采集、处理和可视化","全部都对"],"a":3,"e":"【考点】AI 运维软件的功能范围\n【答案】D\n【解析】AI 运维软件覆盖从规划（容量与架构）、监控维护，到网络拓扑与性能度量、安全检查，再到数据采集处理与可视化，三类描述都在其功能范围内，故选“全部都对”。\n【辨析】单看某一项都有道理，但都不完整，这是典型的多面归总题。","k":"yunwei"},
{"id":190,"m":"练习一","t":"单选","q":"迅雷是一种利用多线程技术下载网络资源的","o":["系统软件","下载软件","管理软件","杀毒软件"],"a":1,"e":"【考点】迅雷的软件类型\n【答案】B\n【解析】迅雷用多线程与 P2P 技术加速下载网络资源，属于下载工具软件。\n【辨析】系统软件指操作系统等底层软件，管理软件面向业务管理，杀毒软件做安全防护，都不以“下载”为核心。","k":"jichu"},
{"id":191,"m":"练习一","t":"单选","q":"讯雷具备内置的（）功能，可与其他杀毒软件协同作用，以确保下载的文件的安全性。","o":["自动登录","病毒防护","自动上网","高速下载"],"a":1,"e":"【考点】下载工具的安全功能\n【答案】B\n【解析】迅雷内置病毒防护模块，下载完成会自动调用本地杀毒软件扫描，降低下载到恶意文件的风险。\n【辨析】自动登录、自动上网是连接行为，高速下载是性能优势，都不是安全保障。","k":"jichu"},
{"id":192,"m":"练习一","t":"单选","q":"迅雷下载工具无法进行（）。","o":["上传文件","下载文件","断点续传","多线程工作"],"a":0,"e":"【考点】下载工具的功能边界\n【答案】A\n【解析】迅雷的核心能力是下载：多线程加速、断点续传、离线下载都能做；但它不是网盘或 FTP 服务端，不提供“上传文件”功能。\n【辨析】题干问“无法进行”，B、C、D 恰恰都是迅雷的招牌能力。","k":"jichu"},
{"id":193,"m":"练习一","t":"单选","q":"在（）中，有两种重要的技术，即语音识别技术和语音合成技术。","o":["虚拟技术","语音处理技术","汉字识别技术","桌面系统"],"a":1,"e":"【考点】语音处理技术的组成\n【答案】B\n【解析】语音处理技术包含两大分支：语音识别（声音转文字）与语音合成（文字转声音），一进一出构成完整的人机语音通道。\n【辨析】虚拟技术、汉字识别、桌面系统都不以语音为处理对象。","k":"xunlian"},
{"id":194,"m":"练习一","t":"单选","q":"以下哪一个文件类型不是音频文件而是图片文件（）.","o":["wav文件","mp3文件","jpg文件","wma文件"],"a":2,"e":"【考点】音频与图片格式\n【答案】C\n【解析】wav、mp3、wma 都是音频格式；jpg 是图像压缩格式，属于图片文件。\n【辨析】题干问“不是音频而是图片”，A、B、D 都是音频，答案 C。","k":"jichu"},
{"id":195,"m":"练习一","t":"单选","q":"一般来说，具备多媒体功能的计算机需要安装容量较大的（）。","o":["硬盘","PU","声卡","网卡"],"a":0,"e":"【考点】多媒体计算机的配置\n【答案】A\n【解析】音频、视频、图像素材体积大，多媒体应用要存大量素材，所以需要容量较大的硬盘（如今也包括固态硬盘）。\n【辨析】CPU 决定运算速度，声卡负责音频输出，网卡负责联网，都与“存得多”无直接关系。","k":"jichu"},
{"id":196,"m":"练习一","t":"单选","q":"（）是光盘驱动器的简称。","o":["ROM","D-ROM","RAM","ROM"],"a":1,"e":"【考点】光驱简称\n【答案】B\n【解析】光盘驱动器英文为 Compact Disc Read-Only Memory Drive，常简称 CD-ROM（选项中作 D-ROM，属 OCR 漏识 C）。\n【辨析】ROM 是只读存储器，RAM 是随机存储器，二者都是存储芯片，不是驱动器。","k":"jichu"},
{"id":197,"m":"练习一","t":"单选","q":"《中华人民共和国计算机信息网络国际联网管理暂行规定实施办法》规定，接入单位申请书、用户登记表的格式由0按照本办法的要求统一制定。","o":["人力资源和社会保障部","公安部","互联单位主管部门","国家安全部"],"a":2,"e":"【考点】国际联网管理的主管部门\n【答案】C\n【解析】该办法规定接入单位申请书、用户登记表的格式由互联单位主管部门统一制定，便于全国口径一致。\n【辨析】人社部管劳动社保，公安部管网络安全执法，国家安全部管国家安全，都不负责接入登记表格式。","k":"jichu"},
{"id":199,"m":"练习一","t":"单选","q":"（）的目标是在保留尽可能多的数据原貌的同时，减少数据量，从而使得数据仍然保持其原先的表现形式。","o":["数据转换","数据清洗","数据规约","数据集成"],"a":2,"e":"【考点】数据规约的目标\n【答案】C\n【解析】题干说“保留数据原貌的同时减少数据量”，正是数据规约（归约）的目标：用更少的数据表达同样的信息，如降维、抽样、离散化。\n【辨析】数据转换改格式，数据清洗去脏，数据集成做合并，都不以减少数据量为目标。","k":"yewu"},
{"id":200,"m":"练习一","t":"单选","q":"在ETL中，\"Extract\"阶段是（）","o":["从源数据集中提取数据","从源数据集中删除数据","从源数据集中备份数据","从源数据增加错误数据"],"a":0,"e":"【考点】ETL 的 Extract 阶段\n【答案】A\n【解析】Extract 就是“抽取”：从各类源系统（数据库、文件、接口、日志）把原始数据读取出来，是 ETL 的第一步。\n【辨析】删除、备份、增加错误数据都不是抽取的含义。","k":"yewu"},
{"id":201,"m":"练习一","t":"单选","q":"在ETL中，\"Transform\"阶段包括O操作。","o":["对数据进行转换","对数据进行清洗","对数据进行拆分","对数据进行转换、清洗、拆分等"],"a":3,"e":"【考点】ETL 的 Transform 阶段\n【答案】D\n【解析】Transform 承担所有加工：格式转换、清洗去重、字段拆分合并、编码统一、派生计算，所以是“转换、清洗、拆分等”的集合。\n【辨析】只答其中一项都会漏掉其他工作，因此选 D。","k":"yewu"},
{"id":203,"m":"练习一","t":"单选","q":"O是一种数据预处理技术，它可以将原始数据转换为所需的格式，以便于进一步的数据分析和挖掘。","o":["数据清洗","数据集成","数据规约","数据变换"],"a":3,"e":"【考点】数据变换\n【答案】D\n【解析】题干说“把原始数据转换为所需格式，便于后续分析和挖掘”，这正是数据变换：归一化、标准化、编码转换、离散化、属性构造。\n【辨析】清洗管质量、集成管合并、规约管减量，都不以“改格式”为核心。","k":"yewu"},
{"id":204,"m":"练习一","t":"单选","q":"Kafka架构相比其他消息系统具有高得多的（）。","o":["扩展性","容错性","吞吐量","数据通道"],"a":2,"e":"【考点】Kafka 的优势\n【答案】C\n【解析】Kafka 以顺序写盘、分区并行和批量发送著称，单集群可达每秒数十万乃至百万级消息，最大优势是高吞吐量。\n【辨析】扩展性、容错性它也有，但“比其他消息系统高得多”的是吞吐量，这是它的标志性指标。","k":"yunwei"},
{"id":206,"m":"练习一","t":"单选","q":"AI系统的运维软件如何识别和处置诊断问题","o":["根据固定规则和权重进行分类和重要性排","通过解析可用的日志和数据，检测开发模式和异常情况","用AI算法监控用户反馈和修复日志，并分类、排序和优先处理","全部都不对"],"a":2,"e":"【考点】AI 运维的问题诊断\n【答案】C\n【解析】AI 运维的优势在于用算法处理非结构化信息：监控用户反馈与修复日志，自动分类、排序、排出优先级，把人工判断交给模型。\n【辨析】A 靠固定规则是传统方式，B 只做模式检测不排优先级，D 直接否定。","k":"yunwei"},
{"id":207,"m":"练习一","t":"单选","q":"AI系统的运维软件中，什么是\"智能压缩\"O","o":["数据压缩算法","资源调节手段","加速服务器响应时间","自动转化缓存"],"a":1,"e":"【考点】智能压缩\n【答案】B\n【解析】在 AI 运维语境里，“智能压缩”指按负载动态调节资源占用（如动态限流、缩容），属于资源调节手段，而非文件压缩算法。\n【辨析】数据压缩算法是传统压缩，加速响应、自动转缓存都不是“压缩”的含义。","k":"yunwei"},
{"id":208,"m":"练习一","t":"单选","q":"AI系统的运维软件在执行资源管理时，可能遇到哪些问题（）。","o":["不同部分之间的不协调","对数据流量的估计不准确","资源预算不足","全部都对"],"a":3,"e":"【考点】资源管理的常见困难\n【答案】D\n【解析】资源管理会同时遇到三类问题：各部分（计算、存储、网络）调度不协调；流量预估不准导致配置失当；预算不足无法扩容，所以“全部都对”。\n【辨析】这三条分别对应协同、预测、成本三个维度。","k":"yunwei"},
{"id":209,"m":"练习一","t":"单选","q":"AI系统的运维软件中，什么是\"容错性\"O","o":["模拟实际环境进行测试的能力","成功处理错误请求的能力","优化集群性能的能力","自主提高响应时间的能力"],"a":1,"e":"【考点】容错性\n【答案】B\n【解析】容错指系统遇到错误请求或局部故障时仍能正确响应、不整体崩溃，即“能成功处理错误请求”的能力。\n【辨析】模拟环境测试是仿真，优化集群性能是调优，缩短响应时间是性能优化。","k":"yunwei"},
{"id":210,"m":"练习一","t":"单选","q":"AI系统的运维软件中，什么是\"集中存储\"O","o":["统一管理设备设置的能力","基于云计算的数据存储方式","用于存储所有数据和信息的单个资源","数据中心规范设备的能力"],"a":2,"e":"【考点】集中存储\n【答案】C\n【解析】集中存储把分散的数据汇聚到一个统一的存储资源里（如集中式存储阵列或对象存储），便于统一管理与备份。\n【辨析】统一管理设备设置是配置管理，基于云存储是部署形态，数据中心规范设备是机房标准。","k":"yunwei"},
{"id":211,"m":"练习一","t":"单选","q":"AI系统的运维软件中，什么是\"预测分析\"O","o":["基于历史数据预测未来状态的能力","分析异常事件并预测系统的未来状况","预测流量峰值并相应地扩大资源","按照用户使用行为分析服务器的负载情况"],"a":0,"e":"【考点】预测分析\n【答案】A\n【解析】预测分析用历史数据拟合趋势，推断未来状态（容量何时耗尽、故障何时可能发生），核心是“由过去推未来”。\n【辨析】B、C、D 都只描述了某个应用分支，不如 A 完整概括定义。","k":"yunwei"},
{"id":212,"m":"练习一","t":"单选","q":"AI系统的运维软件中，什么是\"智能监控\"O","o":["监视设备和应用程序的运行状态的能力","自动移动负载以平衡资源的能力","检测恶意软件并进行消毒的能力","防止网络攻击的能力"],"a":0,"e":"【考点】智能监控\n【答案】A\n【解析】智能监控的基础仍是“监视设备与应用的运行状态”，只是把阈值判断升级为模型识别异常。\n【辨析】负载均衡、杀毒、防攻击是另外的能力，不属于监控的定义。","k":"yunwei"},
{"id":213,"m":"练习一","t":"单选","q":"AI系统的运维软件如何确保高可用性（）。","o":["通过集中存储和预测分析实现","提高并发性","提供多个备份","动态资源调节"],"a":2,"e":"【考点】高可用性的实现\n【答案】C\n【解析】题库把高可用落在“提供多个备份”上：数据与实例都有副本，单点故障时可切换，服务不中断。\n【辨析】A 集中存储与预测分析是管理与预判手段，B 提高并发解决的是容量，D 动态资源调节解决的是弹性。","k":"yunwei"},
{"id":214,"m":"练习一","t":"单选","q":"下列哪项不是AI系统运维中的常见任务（）.","o":["数据处理","系统日志分析","硬件设备调试","数据安全保护"],"a":2,"e":"【考点】AI 运维的任务边界\n【答案】C\n【解析】数据处理、日志分析、数据安全保护都是运维软件能做的软件层工作；硬件设备调试（拆机、换件）属于硬件维护，不在其任务范围。\n【辨析】题干问“不是”，A、B、D 都是常见运维任务。","k":"yunwei"},
{"id":215,"m":"练习一","t":"单选","q":"执行AI系统运维操作时，如何充分利用自动化工具来减少工作量（）)","o":["手动处理数据","评估算法数据分析结果","利用自动化工具进行日常监控","进行人工的系统状态分析"],"a":2,"e":"【考点】自动化的落地方式\n【答案】C\n【解析】减少工作量的正确做法是把重复监控交给自动化工具：定时巡检、自动告警、自动采集，人只看异常。\n【辨析】A 手动处理、D 人工分析都增加工作量，B 评估算法结果不是“减少工作量”的手段。","k":"yunwei"},
{"id":216,"m":"练习一","t":"单选","q":"（）方法不是用来处理数据缺失值的。","o":["人工填写方式填充缺失值","不同指标的计算结果填充缺失值","同一指标的计算结果填充缺失值","随意用某个值全部填充缺失值"],"a":3,"e":"【考点】缺失值处理方法的边界\n【答案】D\n【解析】人工填写、用不同指标推算、用同一指标（同类样本）的统计值填充，都是有依据的填充法；随意用一个值把所有缺失统统填掉，会引入严重偏差，不是正当方法。\n【辨析】题干问“不是用来处理缺失值的”，D 属于错误做法。","k":"yewu"},
{"id":217,"m":"练习一","t":"单选","q":"在填充缺失内容的时候，0能够减小数据偏差，但需要投入更多的人力成本。","o":["用户人工填写补齐","用平均值填充","忽略缺失记录","以任意数据填充"],"a":0,"e":"【考点】人工填充的代价与收益\n【答案】A\n【解析】由用户或业务人员逐条人工补齐，最贴合真实情况，偏差最小；但极其耗人力，成本高。\n【辨析】B 均值填充快但会压缩方差，C 忽略记录会丢样本，D 任意填充制造噪声。","k":"yewu"},
{"id":218,"m":"练习一","t":"单选","q":"以下哪个选项不属于数据缺失值处理步骤","o":["确定范围","提高网速","去除重要性低的字段","填充缺失内容"],"a":1,"e":"【考点】缺失值处理步骤\n【答案】B\n【解析】缺失值处理的正常步骤是：确定缺失范围与比例 → 去掉重要性低、缺失严重的字段 → 选择填充或删除策略 → 填充缺失内容。“提高网速”与数据处理无关。\n【辨析】题干问“不属于”，A、C、D 都是真实步骤。","k":"yewu"},
{"id":219,"m":"练习一","t":"单选","q":"在数据集中存在一些与目标数据无关的0，这些信号就是噪声","o":["衰弱数据","无声数据","干扰数据","正常数据"],"a":2,"e":"【考点】数据噪声\n【答案】C\n【解析】噪声是数据中与目标无关、会干扰模型判断的成分（测量偏差、随机波动、录入杂讯），本质是“干扰数据”。\n【辨析】衰弱数据、无声数据不是标准术语，正常数据恰恰是想要的信号。","k":"xunlian"},
{"id":220,"m":"练习一","t":"单选","q":"以下哪种数据预处理技术不属于分箱方法（）.","o":["按箱均值平滑","按中值平滑","按边界值平滑","按随机值平滑"],"a":3,"e":"【考点】分箱平滑方法\n【答案】D\n【解析】分箱后用箱内统计值替换原值来平滑：按箱均值、按箱中位数、按箱边界值，三种都是标准做法。按随机值平滑会制造随机噪声，不是平滑方法。\n【辨析】题干问“不属于”，A、B、C 都是分箱平滑的常规形式。","k":"yewu"},
{"id":221,"m":"练习一","t":"单选","q":"（）是通过寻找函数来近似描述数据的一种方法，以达到使数据变得更加连续和平滑的效果。","o":["分箱","回归","分类","降维"],"a":1,"e":"【考点】回归用于平滑\n【答案】B\n【解析】用一条函数曲线去拟合散点、让数据变得连续平滑，这是回归的典型用法（线性回归、多项式回归、局部加权回归）。\n【辨析】分箱是分段取统计值，分类输出类别，降维减少维度，都不产生“拟合函数”。","k":"xunlian"},
{"id":222,"m":"练习一","t":"单选","q":"特征选择的目标是在保持或提高分类准确率的前提下，从原始特征集合中选择出一部分具有代表性的特征组成新的特征子集。这样可以0处理数据的计算量和提高模型的解释性。","o":["增加","减少","填充","加强"],"a":1,"e":"【考点】特征选择的作用\n【答案】B\n【解析】特征变少，计算量随之下降，同时模型更容易解释（知道哪几个特征在起作用），所以填“减少”。\n【辨析】增加计算量、填充、加强都与特征选择的收益相反。","k":"xunlian"},
{"id":223,"m":"练习一","t":"单选","q":"特征规约算法接受一组特征作为输入，然后输出其中的一个0，其包含了最具代表性和最重要的特征。","o":["子集","交集","并集","补集"],"a":0,"e":"【考点】特征规约的输出\n【答案】A\n【解析】特征规约从原始特征集合中挑出一部分最有代表性的，形成原集合的子集，用子集替代全集参与建模。\n【辨析】交集、并集、补集是集合运算概念，不是“挑选代表性特征”的结果。","k":"xunlian"},
{"id":224,"m":"练习一","t":"单选","q":"样本规模缩减是一种方法，它从整个数据集用作样本。中选择一个具有代表性的0,","o":["子集","3交集","并集","补集"],"a":0,"e":"【考点】样本缩减\n【答案】A\n【解析】从全量数据中挑出代表性样本，得到的是原数据集的子集（如分层抽样、随机抽样），用它代替全量训练以降低计算成本。\n【辨析】B 项带 OCR 乱码，交集、并集、补集都不是“抽取样本”的结果形态。","k":"xunlian"},
{"id":225,"m":"练习一","t":"单选","q":"如果企业想要成功应对快速变化的外部环境就需要立刻着手对其内部0进行优化。","o":["业务流程","销售市场","组织架构","信息化管理工具"],"a":0,"e":"【考点】流程管理的动因\n【答案】A\n【解析】外部环境变化快（需求、竞争、政策），企业要跟上就必须优化内部业务流程，让交付更快、更灵活，这是 BPM 的出发点。\n【辨析】销售市场是外部对象，组织架构与信息化工具是配套手段，都不是“内部首要优化对象”的规范表述。","k":"jichu"},
{"id":226,"m":"练习一","t":"单选","q":"在20世纪90年代后期，业务流程管理提出了0的方案。","o":["一种更全面的流程改善的选择","一种更快速的流程改善的选择","一种更简单的流程改善的选择","一种更时尚的流程改善的选择"],"a":0,"e":"【考点】业务流程管理的演进\n【答案】A\n【解析】90 年代后期 BPM 提出“更全面的流程改善方案”：不只优化单个环节，而是端到端打通、持续改进并纳入绩效度量。\n【辨析】更快速、更简单、更时尚都不是该阶段的理论表述。","k":"jichu"},
{"id":227,"m":"练习一","t":"单选","q":"在20世纪3（）年代，最初的资本型生产企业都以0为核心来竞争业务。","o":["工作流","现金流","交付率","信息流"],"a":0,"e":"【考点】早期企业竞争核心\n【答案】A\n【解析】20 世纪前期以资本型生产为主，企业竞争的焦点是把工序串起来稳定产出，核心是工作流（workflow）。\n【辨析】现金流、交付率、信息流都是后来才成为竞争焦点的要素。","k":"jichu"},
{"id":228,"m":"练习一","t":"单选","q":"从90年代开始到现在，0成为了企业竞争的关键。","o":["物流","信息流","现金流","产品交付率"],"a":1,"e":"【考点】现代企业竞争核心\n【答案】B\n【解析】90 年代至今信息化深入，企业竞争的关键转为信息流：谁掌握信息、谁的信息流转更快更准，谁就能更快响应市场。\n【辨析】物流、现金流、产品交付率都是被信息流驱动和优化的一环。","k":"jichu"},
{"id":229,"m":"练习一","t":"单选","q":"属于数据标注工程的流程的是（）。","o":["数据采集一数据标注→数据清洗一数据质","数据质检→数据清洗一数据采集→数据标","数据采集→数据清洗一数据标注一数据质","数据采集→数据清洗→数据质检一数据标"],"a":2,"e":"【考点】数据标注工程流程\n【答案】C\n【解析】标准顺序是：先采集数据 → 再清洗整理 → 然后标注 → 最后质检。采集是源头，质检是出口把关。\n【辨析】A 把质检顺序放到最后但缺了环节顺序错，B 完全倒置，D 把质检放到标注之前，逻辑不成立。","k":"xunlian"},
{"id":230,"m":"练习一","t":"单选","q":"在整个数据标注流程中，首先需要进行（）。","o":["数据清洗","数据采集和获取","数据质检","数据标注"],"a":1,"e":"【考点】标注流程的起点\n【答案】B\n【解析】没有数据就谈不上标注，所以流程第一步必然是数据采集与获取（含授权、脱敏、格式整理）。\n【辨析】清洗发生在采集之后，质检与标注更靠后。","k":"yewu"},
{"id":231,"m":"练习一","t":"单选","q":"为了确保最终的数据输出符合要求，在正式进行标注之前，要求需求方的算法工程师提供样板并明确需求和规则。这个过程被称为0","o":["试标过程","清洗过程","质检过程","采集过程"],"a":0,"e":"【考点】试标\n【答案】A\n【解析】正式标注前，由算法工程师提供样例、明确规则，标注方先小批量试做、双方对齐口径，这一过程叫试标，能提前暴露规则歧义。\n【辨析】清洗是数据整理，质检是成品复核，采集是取数，都不含“先试做对齐”的含义。","k":"peixun"},
{"id":232,"m":"练习一","t":"单选","q":"只有通过0的数据才能被视为准确无误的输出结果。","o":["数据采集","数据清洗","数据质检","数据分析"],"a":2,"e":"【考点】质检是把关环节\n【答案】C\n【解析】标注完成的数据必须经过质量检查，确认符合规范与准确率要求，才算合格的交付物，所以只有通过质检的数据才被视为准确输出。\n【辨析】采集、清洗都是前置准备，分析是下游使用。","k":"peixun"},
{"id":233,"m":"练习一","t":"单选","q":"在进行数据质检的过程中，通常会设立数名专门审核数据质量的0，他们会对数据进行逐层审核以确保数据的质量符合标准。","o":["采集人员","标注人员","测试人员","审查人员"],"a":3,"e":"【考点】质检人员\n【答案】D\n【解析】质检环节会设多名专门审核数据质量的审查人员（质检员），按层级逐批抽检或全检，对照规范判定合格与否。\n【辨析】采集人员、标注人员、测试人员都不是做最终质量审核的角色。","k":"peixun"},
{"id":234,"m":"练习一","t":"单选","q":"如果在数据质检中发现提交的数据质量不符合要求就要将数据返回给数据0进行修改","o":["采集人员","标注人员","测试人员","审查人员"],"a":1,"e":"【考点】质检不合格的返修对象\n【答案】B\n【解析】数据是谁标的谁改，质检发现问题会退回给标注人员按规范返修，返修后再重新质检，形成闭环。\n【辨析】采集人员只提供素材，测试人员做软件测试，审查人员是质检方本身。","k":"peixun"},
{"id":235,"m":"练习一","t":"单选","q":"我们可以称将文字或符号打印在图像上的过程为","o":["图像标注","视频标注","自然语言处理","图像分类"],"a":0,"e":"【考点】图像标注\n【答案】A\n【解析】在图像上打框、描点、加标签，把文字或符号标注到图像上，属于图像标注，是计算机视觉训练数据的来源。\n【辨析】视频标注处理视频帧序列，自然语言处理文本，图像分类是任务类型而非标注动作。","k":"xunlian"},
{"id":236,"m":"练习一","t":"单选","q":"不属于图像标注类型的是（）。","o":["拉框","语义分割","视频打点","文字识别转写"],"a":2,"e":"【考点】图像标注的类型\n【答案】C\n【解析】拉框（矩形框）、语义分割、文字识别转写都是对图像内容的标注方式；视频打点是对视频时间轴的操作，不属于图像标注类型。\n【辨析】题干问“不属于”，A、B、D 都在图像标注范畴内。","k":"xunlian"},
{"id":237,"m":"练习一","t":"单选","q":"属于语音标注类型的是（）。","o":["文字识别转写","3ASR语音转写","语义分割","视频追踪"],"a":1,"e":"【考点】语音标注类型\n【答案】B\n【解析】语音标注的核心工作是把 audio 转写成文字（ASR 语音转写），并做切分、校对、标注意外音等。\n【辨析】文字识别转写属 OCR（图像），语义分割属图像，视频追踪属视频，都不是语音标注。","k":"xunlian"},
{"id":238,"m":"练习一","t":"单选","q":"如何在AI系统运维中最好地保障数据的安全性（）)。","o":["定期执行数据备份","利用多因素身份验证","确定系统权限等级","以上三项都是"],"a":3,"e":"【考点】数据安全的三重保障\n【答案】D\n【解析】定期备份防止数据丢失，多因素身份验证防止账号被盗，权限分级限制越权访问，三者共同构成数据安全体系，因此“以上三项都是”。\n【辨析】安全是多层防护，缺任何一层都留缺口。","k":"yunwei"},
{"id":239,"m":"练习一","t":"单选","q":"AI系统运维操作中，如何使系统始终保持最佳状态（）","o":["定期检查系统错误和警告","安排维护计划","对重要数据和机器进行抽样检查","仅在系统遇到问题时才采取行动"],"a":0,"e":"【考点】保持系统最佳状态\n【答案】A\n【解析】题库把“定期检查系统错误和警告”作为首选：及早发现告警与报错，才能在小问题演变成故障前处理掉。\n【辨析】维护计划是安排，抽样检查是手段之一，而“只在出问题才行动”属于被动救火。","k":"yunwei"},
{"id":240,"m":"练习一","t":"单选","q":"AI系统运维中，如何保持系统的最佳响应时间O","o":["部署新服务器","编写更高效的算法","从系统中删除不必要的数据","进行系统监控和调优"],"a":3,"e":"【考点】保障响应时间\n【答案】D\n【解析】响应时间要靠持续的监控与调优：看指标找瓶颈、调参数、扩资源，是长期动作，不是一次性手段。\n【辨析】部署新服务器只解决容量，写高效算法属开发工作，删数据既不治本也有风险。","k":"yunwei"},
{"id":241,"m":"练习一","t":"单选","q":"在A系统运维中，如何确保系统的正常运作O。","o":["定期联络用户并汇报系统的使用情况","建立自动化流程进行系统监控","采用更高安全措施增强系统鲁棒性","定期对系统进行更新和升级"],"a":1,"e":"【考点】保障系统正常运作\n【答案】B\n【解析】靠自动化流程做持续监控，能在无人值守时也第一时间发现异常并告警，是保障稳定运行的基础手段。\n【辨析】联络用户汇报、加强安全、定期升级都有效，但“持续监控”才是日常保障的主线。","k":"yunwei"},
{"id":242,"m":"练习一","t":"单选","q":"在AI系统运维中，如何防止数据泄漏（）。","o":["确定最高权限等级","对数据进行加密","定期审查系统日志","以上三项都是"],"a":3,"e":"【考点】防数据泄漏\n【答案】D\n【解析】数据加密让泄露的内容不可读，权限管控限制谁能拿，日志审计能追查异常导出行为，三者配合才防得住，因此“以上三项都是”。\n【辨析】只做加密不查日志，泄露了也发现不了；只查日志不加密，泄露即失守。","k":"yunwei"},
{"id":243,"m":"练习一","t":"单选","q":"在AI系统运维中，如何保证系统可恢复性（）。","o":["利用备用服务器","定期执行数据备份","定期更新和升级操作系统","以上三项都是"],"a":3,"e":"【考点】系统可恢复性\n【答案】D\n【解析】备用服务器保证故障时能切换，定期备份保证数据能回滚，及时更新系统减少已知漏洞导致的宕机，三者共同提升可恢复性。\n【辨析】三项分别对应切换、回滚、预防三条路径。","k":"yunwei"},
{"id":244,"m":"练习一","t":"单选","q":"在AI系统运维中，如何处理异常情况（）。","o":["启动安全协议并保护系统","添加额外的检查和验证步骤","定期进行系统和数据库更新","以上三项都是"],"a":1,"e":"【考点】异常情况的处置\n【答案】B\n【解析】题库把“添加额外的检查和验证步骤”作为处置异常的核心：在关键路径上加校验、留证据，能阻断异常扩散并便于定位。\n【辨析】启动安全协议、定期更新都是常规动作，但“加检查与验证”更贴合“处理异常”这一具体场景。","k":"yunwei"},
{"id":245,"m":"练习一","t":"单选","q":"在AI系统的运维工作中，常用的日志分析工具是（）.","o":["Splunk","Notepad","Excel","Photoshop"],"a":0,"e":"【考点】日志分析工具\n【答案】A\n【解析】Splunk 专做机器数据（日志、事件）的采集、索引、检索与可视化，是运维日志分析的行业标准工具。\n【辨析】Notepad 是文本编辑器，Excel 处理表格数据，Photoshop 处理图像，都无法索引海量日志。","k":"yunwei"},
{"id":246,"m":"练习一","t":"单选","q":"AI系统为什么需要进行基线性能测试O。","o":["为了确定系统瓶颈","为了评估系统的性能","为了监测系统的健康状态","，为了验证系统自动化部署是否成功"],"a":1,"e":"【考点】基线性能测试的目的\n【答案】B\n【解析】基线测试是在标准负载下记录系统的各项指标，形成“正常状态”的参照值，用于评估系统性能并作为后续对比依据。\n【辨析】找瓶颈、监测健康、验证部署都是基线数据之后的用途，不是基线测试本身的目的。","k":"yunwei"},
{"id":247,"m":"练习一","t":"单选","q":"在出行行业的应用中，标记对车辆进行的数据标注主要使用0的方式。这些标记会展示拍摄到的物体是属于活体、障碍物或其他类型的物体。","o":["矩形框或描点","图像分类或属性判断","实例分割或目标检测","关键点"],"a":0,"e":"【考点】出行行业的数据标注\n【答案】A\n【解析】自动驾驶数据标注中，最常见的是用矩形框框住车辆、行人、障碍物，或用描点标记关键位置，并赋类别属性（活体/障碍物等）。\n【辨析】B 图像分类只给整图打标签，C 实例分割成本更高但有专门场景，D 关键点用于人体姿态，不如 A 概括行车标注的主流方式。","k":"xunlian"},
{"id":248,"m":"练习一","t":"单选","q":"摩根大通开发了一款AI软件，用于快速审查金融合同。该软件使用（）处理的数据进行训练，可以在数秒内完成审查工作，并减少了错误率。","o":["文字翻译","语义分析","语音转录","图像标注"],"a":1,"e":"【考点】合同审查 AI 的训练数据\n【答案】B\n【解析】合同审查要理解条款含义、识别风险点，模型训练用的是语义分析处理过的文本数据（条款标注、实体关系、风险标签）。\n【辨析】文字翻译关注跨语言，语音转录处理声音，图像标注处理图片，都不解决“读懂条款”。","k":"xunlian"},
{"id":249,"m":"练习一","t":"单选","q":"（）标注更多的用于识别人类和动物的特征点。","o":["关键点标注","矩形框标注","3D点云标注","区域标注"],"a":0,"e":"【考点】关键点标注\n【答案】A\n【解析】关键点标注在目标上打若干特征点（人脸 68 点、人体关节、动物姿态），用于识别形状与动作，最适合人类和动物的特征点。\n【辨析】矩形框只给范围，3D 点云用于三维场景，区域标注按块划分，都不产出点坐标。","k":"xunlian"},
{"id":250,"m":"练习一","t":"单选","q":"对目标对象进行目标检测标注的简单处理方式是（）.","o":["关键点标注","矩形框标注","3D点云标注","区域标注"],"a":1,"e":"【考点】目标检测的标注方式\n【答案】B\n【解析】目标检测要同时给出“是什么”和“在哪里”，最直接经济的做法是用矩形框框住每个目标并打类别标签。\n【辨析】关键点标注不框范围，3D 点云需激光雷达数据，区域标注用于分割任务。","k":"xunlian"},
{"id":254,"m":"练习一","t":"单选","q":"分类模型的性能可以用0等指标来评估。","o":["准确率和召回率","准确率和错误率","召回率和错误率","敏感度和错误率"],"a":1,"e":"【考点】分类模型评价指标\n【答案】B\n【解析】题库给出的组合是准确率与错误率：准确率=预测正确占比，错误率=1-准确率，二者是最基础的一对评价指标。\n【辨析】A 准确率+召回率也是常用组合（多用于不平衡数据），但本题设定的答案为 B，考试按题库答案作答。","k":"xunlian"},
{"id":255,"m":"练习一","t":"单选","q":"（）能够计算一个给定元组属于每个类别的概率，从而推断出该元组最可能属于哪个类别。","o":["基于规则的分类方法","特征分析","贝叶斯分类法","神经网络"],"a":2,"e":"【考点】贝叶斯分类\n【答案】C\n【解析】贝叶斯分类基于条件概率：先算各特征在各类别下出现的概率，再结合先验概率用贝叶斯公式求后验概率，取概率最大的类别。\n【辨析】规则分类靠预设条件，特征分析是中间步骤，神经网络靠网络权重学习，都不显式计算“属于各类的概率”。","k":"xunlian"},
{"id":256,"m":"练习一","t":"单选","q":"请问以下哪项工作不在数据标注项目启动过程组的流程之中（）)。","o":["批准项目实施，任命并授权项目经理使用项目资源","制定项目标注规则","识别项目相关方，建立虚拟团队","配置软件和硬件设施"],"a":1,"e":"【考点】项目启动过程组\n【答案】B\n【解析】启动过程组做的事是立项：批准项目、任命项目经理并授权、识别相关方组建团队、配置软硬件资源。制定标注规则属于规划阶段的工作。\n【辨析】题干问“不在启动过程组”，A、C、D 都在启动阶段。","k":"xunlian"},
{"id":257,"m":"练习一","t":"单选","q":"请问下面哪个工作不是数据标注项目规划过程组的一部分（）。","o":["制定项目标注规则","制订进度管理计划","项目实施所需要知识培训","制订成本管理计划"],"a":2,"e":"【考点】项目规划过程组\n【答案】C\n【解析】规划阶段要产出各类计划：标注规则、进度计划、成本计划、质量与风险计划。项目实施所需的知识培训属于执行阶段的准备工作。\n【辨析】题干问“不是规划过程组”，A、B、D 都是规划产物。","k":"xunlian"},
{"id":258,"m":"练习一","t":"单选","q":"请问以下哪项工作不是在项目监控过程组的流程中执行的（）)。","o":["制定风险管理计划","控制范围","控制进度","控制成本"],"a":0,"e":"【考点】项目监控过程组\n【答案】A\n【解析】监控过程组做的是“控制”：控制范围、控制进度、控制成本、控制质量。制定风险管理计划属于规划阶段。\n【辨析】题干问“不是在监控过程组执行”，B、C、D 都是控制类工作。","k":"yunwei"},
{"id":259,"m":"练习一","t":"单选","q":"在大数据采集阶段，我们的态度应该是\"全而细\"，“全\"指的是（）)。","o":["在采集阶段要尽可能的采集到的每个数据","各类数据都要采集到","对于结构化的海量数据需要全面清洗","网络信息采集模块需要全周期管理"],"a":1,"e":"【考点】大数据采集的“全”\n【答案】B\n【解析】采集阶段讲“全而细”，“全”指数据维度要覆盖各类相关数据（结构化、半结构化、非结构化都要采到），保证信息完整；“细”指单条记录采集得细致。\n【辨析】A 说的是尽可能多采（易被理解为无限量），C、D 讲的是清洗与模块管理，都不是“全”的定义。","k":"yewu"},
{"id":263,"m":"练习一","t":"单选","q":"数据的噪声是指（）","o":["孤立点","数据变换引起的错误","测量变量中的随机错误或偏差","空缺值"],"a":2,"e":"【考点】数据噪声的定义\n【答案】C\n【解析】噪声是数据在采集与测量过程中混入的随机错误或偏差，比如仪器精度不足、环境波动造成的读数漂移，它会干扰模型对真实规律的判断。\n【辨析】孤立点是异常值的一种表现，数据变换引起的错误属处理错误，空缺值是缺失问题，三者与“随机误差”不是同一概念。","k":"yewu"},
{"id":264,"m":"练习一","t":"单选","q":"以下哪个选项可以通过函数对数据进行拟合，并实现数据光滑化（）。","o":["分箱","孤立点分析","回归","趋势分析"],"a":2,"e":"【考点】回归平滑\n【答案】C\n【解析】回归用函数去拟合散点，让原本跳动的数据沿一条平滑曲线分布，从而实现光滑化（线性回归、多项式回归、局部加权回归都属此类）。\n【辨析】分箱是分段取统计值，孤立点分析是找异常值，趋势分析看方向，都不产出“拟合函数”。","k":"xunlian"},
{"id":265,"m":"练习一","t":"单选","q":".0是指通过将数据分为不同的区间，从而确定最终值的方法。","o":["孤立点分析","分箱","随机补充","回归"],"a":1,"e":"【考点】分箱\n【答案】B\n【解析】题干说“把数据分成不同区间，再据此确定最终值”，这正是分箱：按区间取均值/中位数/边界值替换原值，起到平滑与离散化作用。\n【辨析】孤立点分析找异常，随机补充造数，回归做函数拟合，都不以“划分区间”为核心。","k":"yewu"},
{"id":266,"m":"练习一","t":"单选","q":"数据清洗流程为0","o":["明确错误类型→识别错误实例→纠正发现错误一→干净数据回流","识别错误实例一→明确错误类型一→纠正发现错误一→干净数据回流","明确错误类型一→纠正发现错误一→识别错误实例一→干净数据回流","识别错误实例一→纠正发现错误一→明确错误类型一→干净数据回流"],"a":0,"e":"【考点】数据清洗的标准流程\n【答案】A\n【解析】正确顺序是：先明确有哪些错误类型（定规则）→ 再识别具体错误实例（找出来）→ 然后纠正（改掉）→ 最后干净数据回流（入库复用）。先定义再识别，逻辑才成立。\n【辨析】B、C、D 都把识别与定义、纠正的先后顺序打乱，不符合“先定规则再执行”的工程逻辑。","k":"yewu"},
{"id":267,"m":"练习一","t":"单选","q":"在(阶段，根据手动检查或者数据样本抽取等数据分析方式，确立数据清洗和转换规则以及工作流程。","o":["明确错误类型","识别错误实例","纠正发现错误","干净数据回流"],"a":0,"e":"【考点】明确错误类型阶段\n【答案】A\n【解析】题干说“通过人工抽查、样本分析来确定清洗与转换规则及流程”，这是清洗的第一步——明确错误类型，即先搞清楚有哪些脏、脏成什么样，才能定规则。\n【辨析】识别错误实例是按规则找出具体记录，纠正错误是执行修改，干净数据回流是入库，都在规则确定之后。","k":"yewu"},
{"id":268,"m":"练习一","t":"单选","q":"在AI系统的运维中，监控数据存储在哪里（）。","o":["ROM","RAM","SSD","HDD"],"a":2,"e":"【考点】监控数据的存储介质\n【答案】C\n【解析】监控指标需要持续写入且量很大，通常落在 SSD（固态硬盘）上：读写快、能承受高频写入，兼顾性能与成本。\n【辨析】ROM 只读不可写，RAM 断电即失，HDD 机械盘随机写性能差，都不适合持续写监控数据。","k":"yunwei"},
{"id":269,"m":"练习一","t":"单选","q":"在AI系统的运维工作中，常用的配置管理工具是（）","o":["Puppet","Sketch","Dreamweaver","InDesign"],"a":0,"e":"【考点】配置管理工具\n【答案】A\n【解析】Puppet 用“声明式配置 + 定期收敛”的方式批量管理成百上千台服务器的软件包、配置文件与服务状态，是经典配置管理工具。\n【辨析】Sketch、Dreamweaver、InDesign 都是设计类软件，与服务器配置管理无关。","k":"yunwei"},
{"id":270,"m":"练习一","t":"单选","q":"对于AI系统的故障排除，以下哪项工具推荐使用。","o":["Wireshark","AdobePremierePro","MicrosoftWord","FinalCutPro"],"a":0,"e":"【考点】故障排除工具\n【答案】A\n【解析】Wireshark 抓取并解析网络报文，能看清请求到底卡在哪一层、有没有丢包重传，是排查网络与应用通信故障的首选。\n【辨析】Premiere、Word、Final Cut 都是办公/剪辑软件，不具备抓包分析能力。","k":"yunwei"},
{"id":271,"m":"练习一","t":"单选","q":"AI系统的性能指标通常有哪些（）。","o":["带宽、CPU利用率、磁盘吞吐量等","IP地址、MAC地址、端口号等","像素、分辨率、色彩空间等","SQL查询语句、数据表结构等"],"a":0,"e":"【考点】AI 系统性能指标\n【答案】A\n【解析】带宽（网络吞吐）、CPU 利用率、磁盘吞吐量、内存占用、响应时延这些资源与吞吐类指标，才是衡量系统性能的维度。\n【辨析】B 是网络地址信息，C 是图像参数，D 是数据库结构，都不反映运行性能。","k":"yunwei"},
{"id":272,"m":"练习一","t":"单选","q":"在AI系统的运维中，常使用哪个工具进行服务器管理（）","o":["Putty","WinRAR","AdobeAcrobatReader","VLCmediaplayer"],"a":0,"e":"【考点】服务器远程管理工具\n【答案】A\n【解析】PuTTY 是轻量的 SSH/Telnet 客户端，运维人员用它远程登录 Linux 服务器执行命令、传文件，是最常用的服务器管理入口。\n【辨析】WinRAR 压缩软件、Acrobat Reader 看 PDF、VLC 放视频，都与服务器管理无关。","k":"yunwei"},
{"id":273,"m":"练习一","t":"单选","q":"在AI系统的运维中，经常使用哪个工具进行性能监控（）。","o":["Nagios","MicrosoftExcel","AdobePhotoshop","iTunes"],"a":0,"e":"【考点】性能监控工具\n【答案】A\n【解析】Nagios 监控主机、服务、端口的存活与阈值，异常时发告警，是运维性能与可用性监控的经典工具。\n【辨析】Excel、Photoshop、iTunes 都不是监控系统。","k":"yunwei"},
{"id":274,"m":"练习一","t":"单选","q":"AI系统在生产环境中运行时出现故障，问题通常在哪个层面（）。","o":["应用层","业务逻辑层","数据库层","网络层"],"a":0,"e":"【考点】生产故障的常见层面\n【答案】A\n【解析】题库把生产环境故障定位在应用层：模型服务、接口、依赖库、配置这些“跑在系统上的程序”最容易因版本、参数、资源问题出错。\n【辨析】业务逻辑层、数据库层、网络层也可能出问题，但本题设定的答案为应用层。","k":"yunwei"},
{"id":275,"m":"练习一","t":"单选","q":"AI系统中的计算节点，通常会在哪里进行部署(","o":["云服务器","个人电脑","移动设备","家庭路由器"],"a":0,"e":"【考点】计算节点的部署位置\n【答案】A\n【解析】AI 训练与推理的算力节点通常部署在云服务器（或机房 GPU 集群）上：可弹性扩缩容、按需租用算力、便于集中运维。\n【辨析】个人电脑算力有限且不稳定，移动设备无法承载训练，家庭路由器更不具备计算能力。","k":"yunwei"},
{"id":276,"m":"练习一","t":"单选","q":"AI系统中，以下哪种操作可以缩短训练时间0","o":["增加batchsize","减少learningrate","增加weightdecay","增加层数"],"a":0,"e":"【考点】缩短训练时间的参数\n【答案】A\n【解析】增大 batch size 能让每次迭代处理更多样本，提高 GPU 利用率、减少迭代次数，从而缩短总体训练时间（需配合学习率调整）。\n【辨析】减小学习率会让收敛更慢，增加 weight decay 增强正则、不加速收敛，增加层数则显著增加计算量。","k":"xunlian"},
{"id":277,"m":"练习一","t":"单选","q":"AI系统在推理过程中，以下哪种情况可能导致错误输出(","o":["输入数据的形状不一致","模型选择不合适","数据量太小","PU负载过高"],"a":0,"e":"【考点】推理阶段的输入校验\n【答案】A\n【解析】推理时模型对输入张量的形状、维度、类型有严格要求，形状不一致会直接报错或输出错乱，这是推理阶段最常见的问题。\n【辨析】模型选择不合适、数据量小属于训练阶段的问题，CPU 负载高只会变慢不会算错。","k":"jichu"},
{"id":278,"m":"练习一","t":"单选","q":"在AI系统中完成模型训练后，我们需要将模型保存并将其用于推理。以下哪种格式可以实现跨平台使用（）","o":["h5","pt","pb","pth"],"a":2,"e":"【考点】跨平台模型格式\n【答案】C\n【解析】pb（Protocol Buffer / SavedModel 冻结图）是 TensorFlow 的通用图格式，可被 TensorFlow Serving、TF Lite、ONNX 转换链路读取，跨平台部署最方便。\n【辨析】h5 偏 Keras，pt、pth 是 PyTorch 的权重文件，跨框架跨平台支持不如 pb。","k":"xunlian"},
{"id":279,"m":"练习一","t":"单选","q":"以下哪种操作不属于AI系统的监控管理（）","o":["记录日志信息","监测模型性能","备份数据","调整模型参数"],"a":3,"e":"【考点】监控管理与调参的边界\n【答案】D\n【解析】记录日志、监测模型性能、备份数据都是“观察与保存”，属于监控管理；调整模型参数是改变模型行为，属于训练调优，不是监控。\n【辨析】题干问“不属于”，A、B、C 都是监控动作。","k":"yunwei"},
{"id":280,"m":"练习一","t":"单选","q":"在AI系统中，以下哪个工具可以可视化模型的图形结构（）。","o":["TensorBoard","PyTorch","Keras","TensorFlow"],"a":0,"e":"【考点】模型结构可视化\n【答案】A\n【解析】TensorBoard 是 TensorFlow 的可视化套件，能画出计算图结构，还能看损失曲线、权重分布、嵌入向量，是查看模型结构的标准工具。\n【辨析】PyTorch、TensorFlow、Keras 是框架本身，不做图形化展示（PyTorch 需配 TensorBoard 或 Netron）。","k":"sheji"},
{"id":281,"m":"练习一","t":"单选","q":"在数据纠错环节中，我们需要对数据源进行分类，并确保在每一个分类中属性值都能够遵循统一的格式，以便于后续的（）。","o":["多样化处理","标准化处理","个性化处理","通用化处理"],"a":1,"e":"【考点】数据纠错中的标准化\n【答案】B\n【解析】同一分类下要求属性值遵循统一格式（日期统一、单位统一、编码统一），这就是标准化处理，目的是让后续比对、合并、建模不出错。\n【辨析】多样化、个性化、通用化都会带来格式差异，与“统一格式”相反。","k":"jichu"},
{"id":282,"m":"练习一","t":"单选","q":"图像标注问题的本质是（）","o":["文字到语言的问题","视觉到文字的问题","语言到文字的问题","视觉到语言的问题"],"a":3,"e":"【考点】图像标注的本质\n【答案】D\n【解析】图像标注是看图说话：标注员观察图像内容（视觉），再用标签、框、点把看到的东西转成文字/类别描述（语言），所以本质是“视觉到语言”。\n【辨析】A、C 都把方向说成从文字出发，B 方向反了（视觉转文字是对的，但题库用“语言”表述更宽，含类别与属性）。","k":"xunlian"},
{"id":283,"m":"练习一","t":"单选","q":"在机器学习中，表情分析被视为一种分类标注技术通常需要结合0来进行","o":["人脸标注","行人标注","行为标注","物品标注"],"a":0,"e":"【考点】表情分析依赖的标注\n【答案】A\n【解析】表情分析要先定位人脸，再判断表情类别（喜怒哀乐等），所以必须结合人脸标注：先框出或标出人脸关键点，才能裁出区域做表情分类。\n【辨析】行人标注用于人流统计，行为标注用于动作识别，物品标注用于物体检测。","k":"xunlian"},
{"id":284,"m":"练习一","t":"单选","q":"用于人流量统计的图像处理技术是（）。","o":["表情分析","行为标注","行人标注","，声纹识别"],"a":2,"e":"【考点】人流量统计的标注方式\n【答案】C\n【解析】统计人流量要识别并跟踪画面中的行人，因此用行人标注：框出行人、给出行人 ID 与轨迹，配合计数算法得出通过人数。\n【辨析】表情分析看情绪，行为标注看动作类别，声纹识别处理声音。","k":"xunlian"},
{"id":285,"m":"练习一","t":"单选","q":"(是将语音中的文字信息和各种声音分离出来，并进行转录或合成的过程，由标注员完成。","o":["图像标注","语音标注","文本标注","视频标注"],"a":1,"e":"【考点】语音标注\n【答案】B\n【解析】题干说“把语音中的文字信息和各种声音分离出来并转录”，处理对象是语音，动作是转写，属于语音标注。\n【辨析】图像标注、文本标注、视频标注的处理对象分别是图像、文本、视频。","k":"peixun"},
{"id":286,"m":"练习一","t":"单选","q":"（）技术是一项能够将说话者的口述内容自动转化为文字形式的技术。","o":["语音分割","语音清洗","ASR语音转写","情绪判定"],"a":2,"e":"【考点】ASR 语音转写\n【答案】C\n【解析】ASR（Automatic Speech Recognition，自动语音识别）把口述语音自动转成文字，是语音标注与语音交互的基础技术。\n【辨析】语音分割是切分音频片段，语音清洗是去噪校验，情绪判定是识别情感，都不产出文字。","k":"xunlian"},
{"id":287,"m":"练习一","t":"单选","q":"是语音数据预处理的关键步骤，它对语音进行重新审查、筛选和校验，以确保数据的准确性和可靠性。","o":["语音清洗","语音分割","声纹识别","）音素标注"],"a":0,"e":"【考点】语音清洗\n【答案】A\n【解析】题干说“对语音重新审查、筛选、校验，确保准确可靠”，这正是语音清洗：剔除无效片段、修正转写错误、统一格式。\n【辨析】语音分割只做切分，声纹识别做身份辨认，音素标注是打标签，都不是“审查校验”。","k":"yewu"},
{"id":288,"m":"练习一","t":"单选","q":"(是一种将文本数据进行结构化处理的方法，包括对文本进行实体标注、词汇分类、情感分析等以支持计算机系统对文本内容的深度理解和分析。","o":["图像标注","视频标注","文本标注","语音标注"],"a":2,"e":"【考点】文本标注\n【答案】C\n【解析】题干提到实体标注、词汇分类、情感分析，处理对象都是文本，目的是让机器更好理解语义，属于文本标注。\n【辨析】图像、视频、语音标注的对象分别是画面、视频流、音频。","k":"jichu"},
{"id":289,"m":"练习一","t":"单选","q":"被认为是人工智能领域中最重要的应用之一的是（）.","o":["大数据分析","读写智能","辅助逻辑决策","自然语言对话"],"a":3,"e":"【考点】自然语言对话的地位\n【答案】D\n【解析】题库把“自然语言对话”视为人工智能最重要的应用之一：语言是人类最主要的交流方式，让机器用语言与人对话，是人机交互的核心方向。\n【辨析】大数据分析、读写智能、辅助逻辑决策都是能力分支，不如“对话”贴近人的日常使用。","k":"jichu"},
{"id":290,"m":"练习一","t":"单选","q":"文本标注是一个（）问题。","o":["半监督学习","无监督学习","监督学习","自监督学习"],"a":2,"e":"【考点】文本标注的学习范式\n【答案】C\n【解析】文本标注要人工给出标签（实体类别、情感极性、意图分类），标签就是监督信号，模型学习“文本→标签”的映射，属于监督学习。\n【辨析】无监督学习没有标签，半监督只用少量标签，自监督靠数据自身构造任务，都不以人工标注为核心。","k":"xunlian"},
{"id":291,"m":"练习一","t":"单选","q":"（）的方法是通过分析目标在图像中所具有的独特特征来实现不同目标类别的区分。","o":["语义分割","实例分割","图像分类/判断","图像检测"],"a":2,"e":"【考点】图像分类/判断\n【答案】C\n【解析】题干说“通过分析目标在图像中的独特特征来区分不同类别”，是给整张图或目标判定类别，属图像分类/判断。\n【辨析】语义分割给每个像素贴类别，实例分割还要区分同类个体，图像检测要给出位置框。","k":"xunlian"},
{"id":292,"m":"练习一","t":"单选","q":"（）技术可以让计算机根据输入的图像或视频，在其中找寻所需目标的位置，并进行分类识别。","o":["语义分割","实例分割","图像分类/判断","图像检测"],"a":3,"e":"【考点】图像检测\n【答案】D\n【解析】题干说“在图像或视频中找出所需目标的位置并分类识别”，既定位又分类，正是目标检测的定义。\n【辨析】语义分割、实例分割输出像素级掩码，图像分类只给整图标签、不给位置。","k":"jichu"},
{"id":293,"m":"练习一","t":"单选","q":"(的主要目的是从输入图像中检测出特定的对象并为每个像素分配相应的类别标签。","o":["语义分割","实例分割","图像分类/判断","图像检测"],"a":1,"e":"【考点】实例分割\n【答案】B\n【解析】题干强调“检测出特定对象，并为每个像素分配类别标签”，既要区分个体又要到像素级，属于实例分割（同一类别的不同个体也能分开）。\n【辨析】语义分割只到像素级但不区分同类个体，图像分类、检测都不给像素标签。","k":"xunlian"},
{"id":294,"m":"练习一","t":"单选","q":"（）不属于视频标注的分类。","o":["图像追踪","视频剪辑","视频分类","视频打点"],"a":0,"e":"【考点】视频标注的类型\n【答案】A\n【解析】视频标注常见有视频分类、视频打点、视频追踪、视频信息提取；图像追踪是处理图像序列中的目标跟踪说法，题库把它排除在视频标注分类之外。\n【辨析】题干问“不属于”，B、C、D 都在视频标注范畴。","k":"xunlian"},
{"id":295,"m":"练习一","t":"单选","q":"O是对视频数据进行标框标注，将其转化为序列顿，最后将其按顺序合成为视频数据。","o":["视频分类","视频打点","视频追踪","视频信息提取"],"a":2,"e":"【考点】视频追踪\n【答案】C\n【解析】题干说“对视频数据逐帧标框，形成序列，再按顺序合成”，逐帧框住同一目标并串起轨迹，就是视频追踪（目标跟踪）标注。\n【辨析】视频分类给整段打标签，视频打点在时间轴做标记，视频信息提取抽取结构化信息。","k":"xunlian"},
{"id":296,"m":"练习一","t":"单选","q":"(是根据视频播放进度显示内容的时间。","o":["视频分类","视频追踪","视频信息提取","视频打点"],"a":3,"e":"【考点】视频打点\n【答案】D\n【解析】视频打点是在时间轴上按播放进度打标记（某秒发生什么事件），用于切分、事件标注、内容检索。\n【辨析】视频分类、视频追踪、信息提取都不以“按时间点打标记”为核心动作。","k":"jichu"},
{"id":297,"m":"练习一","t":"单选","q":"(主要用在人脸识别、手势识别以及步态识别等方面，以提高识别效果和速度。","o":["矩形框标注","关键点标注","情绪判定","实例分割"],"a":1,"e":"【考点】关键点标注的应用\n【答案】B\n【解析】人脸识别要 68/106 个面部关键点，手势识别要手部关节点，步态识别要人体骨架点，都靠关键点标注提升精度与速度。\n【辨析】矩形框只给范围，情绪判定是任务，实例分割成本高且不产出点坐标。","k":"xunlian"},
{"id":298,"m":"练习一","t":"单选","q":"自动驾驶系统中，通过使0来标注图像内出现的车辆，以此识别车辆并进行下一步的处理。","o":["矩形框标注","关键点标注","情绪判定","实例分割"],"a":0,"e":"【考点】车辆标注方式\n【答案】A\n【解析】自动驾驶数据里标注车辆、行人最常用矩形框：框住目标并打上“车辆”类别，检测模型据此学习定位与分类。\n【辨析】关键点用于姿态，情绪判定用于人脸表情，实例分割用于精细轮廓。","k":"xunlian"},
{"id":299,"m":"练习一","t":"单选","q":"在图像数据标注中，语义分割和实例分割是0的两种形式。","o":["矩形框标注","关键点标注","区域标注","3D点云标注"],"a":2,"e":"【考点】区域标注\n【答案】C\n【解析】语义分割与实例分割都是把图像划成区域、再给区域打标签，属于区域标注（多边形/掩码标注）的两种形式。\n【辨析】矩形框、关键点、3D 点云都不是“按区域划分”的标注形态。","k":"xunlian"},
{"id":300,"m":"练习一","t":"单选","q":"(可以包括对词汇的性质、实体、关键字的标记以及用于分析语音韵律和理解意图等方面的标记。","o":["关系标注","属性标注","音素标注","序列标注"],"a":3,"e":"【考点】序列标注\n【答案】D\n【解析】给一句话中每个词打上词性、实体、关键字等标签，输出是与词序列对齐的标签序列，所以叫序列标注（BIO 标注是典型形式）。\n【辨析】关系标注标实体间关系，属性标注标对象属性，音素标注针对语音。","k":"xunlian"},
{"id":301,"m":"练习一","t":"单选","q":"指向关系、修饰关系和平行语料是(中的一些内容。","o":["关系标注","属性标注","音素标注","序列标注"],"a":0,"e":"【考点】关系标注\n【答案】A\n【解析】指向关系、修饰关系、平行语料描述的是实体或文本之间的关联，属于关系标注（如“张三—任职于—某公司”）。\n【辨析】属性标注给单个对象打属性，音素标注针对语音，序列标注针对词序列标签。","k":"xunlian"},
{"id":302,"m":"练习一","t":"单选","q":"（）可以包括文本类别、新闻、娱乐等方面。","o":["关系标注","音素标注","属性标注","序列标注"],"a":2,"e":"【考点】属性标注\n【答案】C\n【解析】文本类别、新闻、娱乐这些是对文本本身属性的划分，属于属性标注（给对象贴上类别、领域、风格等属性）。\n【辨析】关系标注处理对象间关系，音素标注处理语音，序列标注处理词级标签序列。","k":"xunlian"},
{"id":303,"m":"练习一","t":"单选","q":"(是一种生物识别技术，它是通过分析语音信号的特征来识别未知的声音。","o":["语音分割","声纹识别","音素标注","韵律标注"],"a":1,"e":"【考点】声纹识别\n【答案】B\n【解析】声纹识别分析语音信号中的频谱、共振峰等特征，辨认“这是谁在说”，属于生物识别技术，可用于身份认证。\n【辨析】语音分割切音频，音素标注打音素标签，韵律标注标语调节奏。","k":"xunlian"},
{"id":304,"m":"练习一","t":"单选","q":"在AI系统部署过程中，以下哪个因素可能影响系统性能和安全性0","o":["硬件配置","应用场景","算法优化","网络带宽"],"a":3,"e":"【考点】部署中的网络因素\n【答案】D\n【解析】题库把网络带宽作为影响部署性能与安全的关键因素：带宽不足会让推理请求排队超时，网络暴露面也直接关系安全。\n【辨析】硬件配置、应用场景、算法优化都影响性能，但本题设定的答案为网络带宽。","k":"yunwei"},
{"id":305,"m":"练习一","t":"单选","q":"在AI系统中，以下哪个指标用于评估分类模型的性能","o":["精确率","召回率","准确率","F1-score"],"a":2,"e":"【考点】分类模型的评价指标\n【答案】C\n【解析】准确率（Accuracy）是最基础的整体评价指标：预测正确的样本占总样本的比例，直观反映模型“答对多少”。\n【辨析】精确率、召回率关注正类表现，F1 是精确率与召回率的调和，都是补充指标，本题设定的主指标是准确率。","k":"xunlian"},
{"id":306,"m":"练习一","t":"单选","q":"在AI系统中，以下哪个技术可以有效防止过拟合（）.","o":["数据增强","正则化","Dropout","激活函数"],"a":1,"e":"【考点】防过拟合：正则化\n【答案】B\n【解析】正则化在损失函数中加入对权重的惩罚（L1/L2），抑制模型过度贴合训练数据，是防止过拟合的经典手段。\n【辨析】数据增强扩样本、Dropout 随机丢神经元也是防过拟合的常用法，但本题设定的答案为“正则化”；激活函数负责引入非线性。","k":"xunlian"},
{"id":307,"m":"练习一","t":"单选","q":"在AI系统中，以下哪个技术可以最有效的应对数据不平衡问题（）","o":["过采样","欠采样","样本加权","集成学习"],"a":3,"e":"【考点】数据不平衡的应对\n【答案】D\n【解析】题库把“集成学习”作为应对不平衡最有效的手段：通过多模型组合（如平衡随机森林、EasyEnsemble）在不同采样子集上学习，兼顾多数类与少数类。\n【辨析】过采样易过拟合，欠采样易丢信息，样本加权重在调整损失，效果通常不如集成组合。","k":"jichu"},
{"id":308,"m":"练习一","t":"单选","q":".在AI系统中，以下技术是最优的提高模型泛化能力。","o":["Earlystopping","数据增强","Dropout","集成学习"],"a":3,"e":"【考点】提升泛化能力\n【答案】D\n【解析】集成学习把多个弱模型组合成强模型，降低方差、提升稳定性，是提升泛化能力的有效途径（随机森林、GBDT、Stacking）。\n【辨析】早停、数据增强、Dropout 都能缓解过拟合，但题库设定的最优答案是集成学习。","k":"xunlian"},
{"id":309,"m":"练习一","t":"单选","q":"AI系统运维软件常用的日志分析工具是（）。","o":["Logstash","Kibana","Elasticsearch","lloftheabove"],"a":3,"e":"【考点】ELK 日志分析套件\n【答案】D\n【解析】Logstash 负责采集与清洗日志，Elasticsearch 负责存储与检索，Kibana 负责可视化展示，三者组合即 ELK，都是常用日志分析组件，所以“以上都是”。\n【辨析】只答其中一个等于只说了 ELK 的一环。","k":"yunwei"},
{"id":310,"m":"练习一","t":"单选","q":"在AI系统运维中，负责保障系统可靠性的是（）。","o":["运维人员","开发人员","测试人员","产品经理"],"a":0,"e":"【考点】可靠性的责任主体\n【答案】A\n【解析】保障系统稳定运行、处理故障、做巡检与恢复的是运维人员；开发负责功能实现，测试负责质量验证，产品负责需求定义。\n【辨析】可靠性是运维的核心 KPI，其余角色的职责不落在“系统持续可用”。","k":"yunwei"},
{"id":311,"m":"练习一","t":"单选","q":"人工智能在医疗领域的应用最主要的优点是什么","o":["提高医疗效率","减少医疗费用","改善病人治疗效果","以上都是"],"a":3,"e":"【考点】AI 在医疗领域的价值\n【答案】D\n【解析】AI 在医疗同时带来三重收益：影像与病历处理提高效率、减少重复检查降低费用、辅助诊断提升治疗效果，因此“以上都是”。\n【辨析】只答一项都会漏掉其他价值。","k":"jichu"},
{"id":312,"m":"练习一","t":"单选","q":"以下哪项不是人工智能在金融领域的应用（）。","o":["风险评估","投资决策","客户服务","研发创新"],"a":3,"e":"【考点】AI 在金融领域的应用边界\n【答案】D\n【解析】风险评估（信贷、反欺诈）、投资决策（量化策略）、客户服务（智能客服）都是金融领域的典型 AI 应用；研发创新属于科技研发范畴，不是金融业务应用。\n【辨析】题干问“不是”，A、B、C 都是金融场景。","k":"jichu"},
{"id":313,"m":"练习一","t":"单选","q":"某家电商用人工智能技术对消费者行为进行分析和预测，从而优化其销售策略。这是哪种类型的人工智能应用（）。","o":["机器学习","自然语言处理","专家系统","深度学习"],"a":0,"e":"【考点】消费行为预测的技术类型\n【答案】A\n【解析】用历史行为数据训练模型预测用户偏好与购买倾向，属于机器学习（监督学习中的分类/回归）的典型应用。\n【辨析】自然语言处理处理文本语义，专家系统靠规则库，深度学习是机器学习的子集且不是本题强调的技术归类。","k":"jichu"},
{"id":314,"m":"练习一","t":"单选","q":"能够自主控制车辆的无人驾驶技术是哪种类型的人工智能应用（）)。","o":["机器学习","专家系统","深度学习","自主决策"],"a":3,"e":"【考点】自动驾驶的技术归类\n【答案】D\n【解析】无人驾驶要根据感知结果自主判断加速、转向、刹车，核心能力是自主决策（感知—决策—控制闭环中的决策环节）。\n【辨析】机器学习、深度学习是底层方法，专家系统靠规则推理，都不足以概括“自主控制车辆”这一应用特征。","k":"jichu"},
{"id":315,"m":"练习一","t":"单选","q":"（）不属于声纹识别应用。","o":["身份认证","打卡","语音唤醒","人脸识别"],"a":3,"e":"【考点】声纹识别的应用范围\n【答案】D\n【解析】声纹识别靠声音特征辨人，可用于身份认证、声纹打卡、语音唤醒（只认主人声音）。人脸识别靠人脸图像，与声纹无关。\n【辨析】题干问“不属于”，A、B、C 都是声纹应用。","k":"xunlian"},
{"id":316,"m":"练习一","t":"单选","q":"根据语音的固有属性所划分的最小语音单位被称为（）。","o":["音质","音素","音位","音位变体"],"a":1,"e":"【考点】音素\n【答案】B\n【解析】音素是按语音的物理与发音属性划分的最小语音单位（如汉语拼音的 b、a、i），是语音识别与合成的基本建模单元。\n【辨析】音质是声音品质，音位是语言学中能区别意义的最小单位（抽象概念），音位变体是同一音位的不同发音。","k":"xunlian"},
{"id":317,"m":"练习一","t":"单选","q":"机器学习模型的准确性和性能受到训练数据集的影非常大，只有拥有0的数据集才能够获得更好的结果。","o":["高速度","不同领域","差异度小","高质量"],"a":3,"e":"【考点】数据质量的重要性\n【答案】D\n【解析】模型只能学到数据里有的规律，数据质量（准确、完整、一致、有代表性）直接决定模型上限，所以需要“高质量”的数据集。\n【辨析】高速度、不同领域、差异度小都不是决定模型效果的核心属性（差异小反而可能缺乏区分度）。","k":"xunlian"},
{"id":320,"m":"练习一","t":"单选","q":"(是测试报告不包含的内容。","o":["测试简介","测试通过/失败的标准","测试环境","测试方法"],"a":1,"e":"【考点】测试报告的内容构成\n【答案】B\n【解析】题库把“测试通过/失败的标准”归入测试计划（事前定义），测试报告只陈述环境、方法、执行统计与缺陷情况，不再重复列判定标准。\n【辨析】题干问“不包含”，A 测试简介、C 测试环境、D 测试方法都在报告中。","k":"yunwei"},
{"id":321,"m":"练习一","t":"单选","q":"（）不属于版本测试报告的主要内容。","o":["风险分析","测试用例设计与执行","缺陷概况","问题概要"],"a":0,"e":"【考点】版本测试报告的主要内容\n【答案】A\n【解析】版本测试报告聚焦本版本：用例设计与执行情况、缺陷概况、问题概要、结论建议。风险分析属于项目风险管理文档，不列入版本测试报告的主要内容。\n【辨析】题干问“不属于”，B、C、D 都是报告核心内容。","k":"yunwei"},
{"id":322,"m":"练习一","t":"单选","q":"（）不属于版本测试报告中测试环境需要包括的内容。","o":["硬件环境","软件版本","竞标书","系统拓扑图"],"a":2,"e":"【考点】测试环境的描述项\n【答案】C\n【解析】测试环境要写清硬件规格、软件与版本、网络与系统拓扑，便于问题复现。竞标书是商务文件，与测试环境无关。\n【辨析】题干问“不包括”，A、B、D 都是环境要素。","k":"yunwei"},
{"id":323,"m":"练习一","t":"单选","q":"在版本测试报告中，测试用例的测试执行率等于已执行的用例数除以0","o":["通过用例数","未通过用例数","阻塞用例数","用例总数"],"a":3,"e":"【考点】用例执行率的计算\n【答案】D\n【解析】执行率 = 已执行用例数 ÷ 用例总数，反映测试覆盖进度，是测试报告中必报的进度指标。\n【辨析】通过、未通过、阻塞都是执行结果的分项，分母必须是总用例数。","k":"yunwei"},
{"id":324,"m":"练习一","t":"单选","q":"版本测试报告中的测试用例效率是通过在测试过程中0的总数除以测试用例的数量计算得出的。","o":["未通过用例","发现的缺陷","已执行的用例","通过用例"],"a":1,"e":"【考点】用例效率的计算\n【答案】B\n【解析】用例效率 = 测试过程中发现的缺陷总数 ÷ 测试用例数量，衡量“平均每条用例能挖出多少问题”，数值越高说明用例设计越有效。\n【辨析】已执行数、通过数、未通过数都是过程统计，不是缺陷产出。","k":"yunwei"},
{"id":325,"m":"练习一","t":"单选","q":"(是指利用逻辑覆盖法和基本路径测试法创建的用例设计方法。","o":["白盒测试用例","黑盒测试用例","安全测试用例","故障修复测试用例"],"a":0,"e":"【考点】白盒测试用例\n【答案】A\n【解析】逻辑覆盖（语句、判定、条件、路径覆盖）与基本路径测试都基于程序内部结构设计用例，属于白盒测试。\n【辨析】黑盒测试不看代码，只看输入输出；安全测试、故障修复测试是按目的划分的类型。","k":"yunwei"},
{"id":326,"m":"练习一","t":"单选","q":"在软件测试过程中，当测试人员对模块进行功能测试并且对接口进行部分测试以及对单元进行覆盖测试时，这个测试阶段被称为0","o":["单元测试","集成测试","系统测试","验收测试"],"a":0,"e":"【考点】单元测试\n【答案】A\n【解析】对单个模块做功能测试、对接口做部分测试、对单元做覆盖测试，验证的是最小可测单元内部是否正确，属于单元测试。\n【辨析】集成测试验模块间接口协作，系统测试验整体，验收测试由用户确认需求。","k":"yunwei"},
{"id":327,"m":"练习一","t":"单选","q":"在验收测试阶段，执行人员可能不仅限于测试人员还可能包括（）参与。","o":["开发人员","数据库管理员","设计人员","用户"],"a":3,"e":"【考点】验收测试的执行者\n【答案】D\n【解析】验收测试的目的是确认产品满足用户需求，因此必须由用户（或客户代表）参与甚至主导，测试人员只做支持。\n【辨析】开发、DBA、设计人员都是内部角色，不能代替用户做验收判断。","k":"yunwei"},
{"id":328,"m":"练习一","t":"单选","q":"评估分类算法模型结果的准确性的测试方法是（）。","o":["分类算法测试","回归算法测试","聚类算法测试","关联规则算法测试"],"a":0,"e":"【考点】分类算法测试\n【答案】A\n【解析】评估分类模型准不准（准确率、精确率、召回率、混淆矩阵），用的就是分类算法测试方法。\n【辨析】回归测试算法看预测值与真实值的偏差，聚类测试看簇内相似度，关联规则测试看规则支持度与置信度。","k":"yunwei"},
{"id":329,"m":"练习一","t":"单选","q":"在评估算法模型的精确度时，一种常用的方法是比较预测值和真实值之间的差异程度，这种方法被称为0","o":["分类算法测试","回归算法测试","聚类算法测试","关联规则算法测试"],"a":1,"e":"【考点】回归算法测试\n【答案】B\n【解析】比较预测值与真实值的差异（MSE、RMSE、MAE、R²）来评估精度，是回归模型的评价方式。\n【辨析】分类看类别判对没，聚类看分组合理性，关联规则看规则有效性。","k":"yunwei"},
{"id":330,"m":"练习一","t":"单选","q":"在算法模型测试方法中，需要评估聚类结果中同类成员相似性的算法是（）。","o":["分类算法测试","回归算法测试","聚类算法测试","关联规则算法测试"],"a":2,"e":"【考点】聚类算法测试\n【答案】C\n【解析】聚类没有标签，只能评估“同类是否相似、异类是否分离”，用轮廓系数、DBI、DI 等内部指标，属聚类算法测试。\n【辨析】分类、回归都有真实标签可比对，关联规则评估的是规则而非分组。","k":"yunwei"},
{"id":331,"m":"练习一","t":"单选","q":"将文字编辑器中的新建文档、打开文档、保存文档、打印和编辑等功能的测试用例，归类为0","o":["白盒测试用例","软件各项功能的测试用例","软件的各项非功能测试用例","性能测试用例"],"a":1,"e":"【考点】功能测试用例\n【答案】B\n【解析】新建、打开、保存、打印、编辑都是文字编辑器的具体功能点，针对这些功能设计的用例归为软件各项功能的测试用例。\n【辨析】白盒测试是按代码结构分类，非功能测试指性能、安全、兼容性，性能测试专测响应与并发。","k":"yunwei"},
{"id":332,"m":"练习一","t":"单选","q":"将O的范围确定为窗口中的各类UI元素，如菜单按钮、输入框、列表框、工具栏和状态栏，并对其进行分类。","o":["软件各项功能的测试用例","黑盒测试用例","用户界面测试用例","确认软件缺陷修正的测试用例"],"a":2,"e":"【考点】用户界面测试用例\n【答案】C\n【解析】把测试范围确定为菜单、按钮、输入框、列表、工具栏、状态栏这些界面元素并分类，正是用户界面（UI）测试用例的编写方式。\n【辨析】功能用例关注业务逻辑，黑盒用例是按是否看代码划分的类别，缺陷确认用例针对已报缺陷。","k":"yunwei"},
{"id":333,"m":"练习一","t":"单选","q":"单元测试的测试用例编写需要参考（）。","o":["需求文档","概要设计","体系设计","详细设计文档"],"a":3,"e":"【考点】单元测试的依据\n【答案】D\n【解析】单元测试要验证函数/模块内部的实现细节（入参、分支、边界），必须依据详细设计文档（模块设计与接口说明）。\n【辨析】需求文档用于系统/验收测试，概要设计用于集成测试，体系设计不是标准术语。","k":"yunwei"},
{"id":334,"m":"练习一","t":"单选","q":"（）是测试过程中的最小单位，由一组特定的测试输入、执行条件和预期结果组成，用于验证系统在特定条件下是否运行正常。","o":["测试计划","测试报告","测试方法","测试用例"],"a":3,"e":"【考点】测试用例的定义\n【答案】D\n【解析】测试用例是测试的最小执行单位，包含输入数据、执行条件与预期结果，用于判断系统在特定条件下是否正常。\n【辨析】测试计划是整体安排，测试报告是结果汇总，测试方法是技术路线，都不是最小执行单元。","k":"yunwei"},
{"id":335,"m":"练习一","t":"单选","q":"回正确人工智能在物流领域的应用最主要的优点是什么（）.","o":["提高物流效率","减少配送成本","减少订单出错率","）以上都是"],"a":3,"e":"【考点】AI 在物流领域的价值\n【答案】D\n【解析】AI 在物流同时提升效率（路径优化、仓储调度）、降低成本（运力匹配）、减少出错（单据识别与校验），因此“以上都是”。\n【辨析】三项分别对应效率、成本、质量三个维度。","k":"jichu"},
{"id":336,"m":"练习一","t":"单选","q":"以下哪项不是人工智能在安全领域的应用（）。","o":["网络安全","视频监控","飞行安全","职业健康安全"],"a":3,"e":"【考点】AI 在安全领域的应用边界\n【答案】D\n【解析】网络安全（入侵检测）、视频监控（异常行为识别）、飞行安全（状态监测与预警）都是 AI 在安全领域的具体应用；职业健康安全属于劳动保护管理范畴，不是 AI 技术应用的典型场景。\n【辨析】题干问“不是”，A、B、C 都是安全场景。","k":"jichu"},
{"id":337,"m":"练习一","t":"单选","q":"人工智能在运动领域的应用最主要的优点是什么（）.","o":["提高运动员素质","减少运动员受伤率","改善裁判员判决准确性","以上都是"],"a":3,"e":"【考点】AI 在运动领域的价值\n【答案】D\n【解析】AI 可辅助训练提升运动员素质、通过动作分析降低受伤率、用辅助判罚系统提高判决准确性，三重价值并存。\n【辨析】三项分别对应训练、防护、判罚环节。","k":"jichu"},
{"id":338,"m":"练习一","t":"单选","q":"以下哪种类型的人工智能应用在游戏领域最为常见（）.","o":["机器学习","深度学习","专家系统","自然语言处理"],"a":1,"e":"【考点】游戏领域的 AI 技术\n【答案】B\n【解析】游戏中的画面渲染、NPC 行为、对手 AI、语音与图像生成大量依赖深度神经网络，深度学习是游戏领域最常见的技术类型。\n【辨析】专家系统偏规则推理，自然语言处理针对文本，机器学习是更宽泛的上位概念。","k":"jichu"},
{"id":339,"m":"练习一","t":"单选","q":"人工智能在广告领域的应用主要是通过哪些手段来实现（）。","o":["个性化推荐","智能定位","数据分析","）以上都是"],"a":3,"e":"【考点】AI 在广告领域的实现手段\n【答案】D\n【解析】广告投放靠个性化推荐（千人千面）、智能定位（人群与地域定向）、数据分析（效果归因与优化），三种手段组合使用。\n【辨析】三项分别对应“给谁看、在哪看、效果如何”。","k":"jichu"},
{"id":340,"m":"练习一","t":"单选","q":"人工智能在金融领域的主要应用是（）。","o":["风险控制","数据分析","客户服务","支付结算"],"a":0,"e":"【考点】AI 在金融领域的主要应用\n【答案】A\n【解析】题库把风险控制列为金融领域的主要应用：信贷评分、反欺诈、异常交易监测直接关系资金安全，是金融机构最先投入的方向。\n【辨析】数据分析、客户服务、支付结算也用到 AI，但本题设定的答案是风险控制。","k":"jichu"},
{"id":341,"m":"练习一","t":"单选","q":"零售业中，人工智能应用最常见的是（）。","o":["供应链管理","营销推广","商品推荐","客户服务"],"a":2,"e":"【考点】AI 在零售业的应用\n【答案】C\n【解析】零售最典型的 AI 应用是个性化商品推荐：根据浏览与购买行为推荐商品，直接提升转化率与客单价。\n【辨析】供应链、营销推广、客户服务也用 AI，但“最常见”落在推荐场景。","k":"jichu"},
{"id":342,"m":"练习一","t":"单选","q":"工业制造业中，人工智能主要应用于哪些方面（）。","o":["产品设计","生产调度","质量控制","供应链管理"],"a":1,"e":"【考点】AI 在制造业的应用\n【答案】B\n【解析】题库把生产调度作为制造业的主要应用：排产、产能分配、设备与工序协调直接影响交付与成本。\n【辨析】产品设计、质量控制、供应链也用 AI，但本题设定的主要应用是生产调度。","k":"jichu"},
{"id":343,"m":"练习一","t":"单选","q":"人工智能在教育领域的主要作用是（）。","o":["个性化教学","考试阅卷","学生管理","数据分析"],"a":0,"e":"【考点】AI 在教育领域的作用\n【答案】A\n【解析】AI 教育的核心价值是因材施教：按学生水平自适应推题、规划学习路径，实现个性化教学。\n【辨析】阅卷、学生管理、数据分析都是辅助功能，不是主要作用。","k":"jichu"},
{"id":344,"m":"练习一","t":"单选","q":"人工智能在交通领域的主要应用是（）。","o":["自动驾驶技术","实时交通监控","运输调度","客户服务"],"a":0,"e":"【考点】AI 在交通领域的应用\n【答案】A\n【解析】自动驾驶是交通领域 AI 最具代表性的应用，融合感知、决策、控制，直接改变出行方式。\n【辨析】实时监控、运输调度、客户服务都是配套能力，代表性不如自动驾驶。","k":"jichu"},
{"id":345,"m":"练习一","t":"单选","q":"人工智能在农业领域的主要应用是（）。","o":["害虫监测","农作物识别","水资源管理","预测产量"],"a":1,"e":"【考点】AI 在农业领域的应用\n【答案】B\n【解析】农作物识别（病虫害识别、长势与成熟度判断）是农业 AI 最典型的落地：靠图像识别判断作物状态，指导精准管理。\n【辨析】害虫监测、水资源管理、产量预测都是细分场景，代表性不如作物识别。","k":"jichu"},
{"id":346,"m":"练习一","t":"单选","q":"人工智能在保险领域的主要作用是（）。","o":["风险评估","索赔审核","数据分析","客户服务"],"a":0,"e":"【考点】AI 在保险领域的应用\n【答案】A\n【解析】保险业的核心是定价与承保，风险评估（核保风控、反欺诈）直接决定盈亏，是 AI 的主要应用。\n【辨析】索赔审核、数据分析、客户服务都是辅助环节。","k":"jichu"},
{"id":347,"m":"练习一","t":"单选","q":"人工智能在旅游领域的主要应用是（）。","o":["行程规划","酒店预订","翻译服务","视频导游"],"a":0,"e":"【考点】AI 在旅游领域的应用\n【答案】A\n【解析】行程规划是旅游 AI 的代表性应用：根据时间、预算、偏好自动生成路线与安排，是用户最先感知的智能服务。\n【辨析】酒店预订、翻译、视频导游都是单点功能。","k":"jichu"},
{"id":348,"m":"练习一","t":"单选","q":"人工智能用于文化娱乐领域的主要应用是（）。","o":["视频直播","个性化推荐","艺术创作","游戏开发"],"a":1,"e":"【考点】AI 在文化娱乐领域的应用\n【答案】B\n【解析】内容平台的个性化推荐（按兴趣分发视频、音乐、资讯）是文娱领域最普遍、影响最大的 AI 应用。\n【辨析】直播、艺术创作、游戏开发也用到 AI，但覆盖面与代表性不如推荐系统。","k":"jichu"},
{"id":349,"m":"练习一","t":"单选","q":"在软件版本更新后，使用0的测试用例能够减轻测试工作的难度，缩短项目周期的时间。","o":["有效性","避免测试的盲目性","可维护性","可重复性"],"a":2,"e":"【考点】测试用例的可维护性\n【答案】C\n【解析】版本更新后，用例要能快速调整复用。可维护性好的用例结构清晰、步骤独立、数据与逻辑分离，改动成本低，从而缩短测试周期。\n【辨析】有效性指能发现问题，避免盲目性指有明确目标，可重复性指多次执行结果一致，都不直接对应“减轻改版后的维护负担”。","k":"yunwei"},
{"id":350,"m":"练习一","t":"单选","q":"通过挑选具有代表性或特殊性的测试数据，从0精选出一部分进行测试，可在节省时间和资源的同时提高测试效率。","o":["随机地选取测试数据","取部分特定的输入数据作为测试数据","在完成编码以后制定软件的测试计划","数量极大的可用测试数据中"],"a":3,"e":"【考点】测试数据的精选\n【答案】D\n【解析】题干说“从数量极大的可用测试数据中挑选有代表性或特殊性的数据”，强调的正是这种“从海量里挑”的思路，所以填“数量极大的可用测试数据中”。\n【辨析】A 随机选取没有代表性判断，B 只取特定输入覆盖面窄，C 讲的是计划制定时机，与“挑选数据”不是一回事。","k":"yunwei"},
{"id":351,"m":"练习一","t":"单选","q":"（）是对模型建设过程进行商业和技术上的全面检查，以确保模型不存在重大错误，并考虑是否涉及到关键的业务问题。","o":["模型优化","模型评价","数据建模","模型部署"],"a":1,"e":"【考点】模型评价\n【答案】B\n【解析】对建模过程做商业与技术上的全面检查、确认无重大错误、判断是否牵涉关键业务问题，这是模型评价（评估）的职责，是建模完成后的把关环节。\n【辨析】模型优化是调参改进，数据建模是构建过程本身，模型部署是上线，都不做全面审查。","k":"xunlian"},
{"id":352,"m":"练习一","t":"单选","q":"在0任务中，我们需要分析影响决策的历史遗留问题以及预算情况。","o":["评价结果","建立模型","评估模型","项目回顾"],"a":0,"e":"【考点】评价结果任务\n【答案】A\n【解析】在评价结果任务中，要回到业务侧衡量项目价值：历史遗留问题是否解决、预算是否在范围内，从而判断成果是否可采纳。\n【辨析】建立模型与评估模型是技术环节，项目回顾偏流程复盘，都不以“遗留问题与预算分析”为核心内容。","k":"jichu"},
{"id":353,"m":"练习一","t":"单选","q":"（）任务包括了影响决策的遗留问题和预算的分析。","o":["数据整合","模型假设","确定下一步","模型规划部署"],"a":2,"e":"【考点】确定下一步\n【答案】C\n【解析】项目收尾时最有价值的是“确定下一步”：根据遗留问题与预算余量，决定是继续迭代、扩大范围还是终止，属于决策性任务。\n【辨析】数据整合、模型假设是建模环节，模型规划部署是落地环节，都不承担“定去向”的判断。","k":"jichu"},
{"id":354,"m":"练习一","t":"单选","q":"（）是关于数据可视化的不正确的说法。","o":["通过计算机图形图像等技术更加直观表达数","展现数据的基本特征和隐含规律","辅助人们认识和理解数据","数据可视化传达的信息比较复杂，需要专业解读"],"a":3,"e":"【考点】数据可视化的特性\n【答案】D\n【解析】可视化的目的恰恰是把复杂信息变得直观易懂，让非专业人员也能快速把握结论，所以“信息复杂、需要专业解读”的说法不正确。\n【辨析】A、B、C 都准确描述了可视化的手段与价值，只有 D 与其目的相反。","k":"sheji"},
{"id":355,"m":"练习一","t":"单选","q":"（）不属于数据可视化的主要作用。","o":["数据采集","数据表达","数据操作","数据分析"],"a":0,"e":"【考点】可视化的三大作用\n【答案】A\n【解析】数据可视化承担数据表达（把数据画出来）、数据操作（交互筛选、联动）、数据分析（借助图形发现规律）三件事；数据采集属于采集环节，不在可视化范畴。\n【辨析】题干问“不属于”，B、C、D 都是可视化的核心作用。","k":"sheji"},
{"id":356,"m":"练习一","t":"单选","q":"（）不属于数据表达常见的形式。","o":["文本","图表","光盘","图像"],"a":2,"e":"【考点】数据表达的形式\n【答案】C\n【解析】文本、图表、图像都是把数据呈现出来的形式；光盘只是存储介质，它承载内容但不属于“表达形式”。\n【辨析】题干问“不属于”，A、B、D 都是常见表达形式（如统计图、热力图、文字摘要）。","k":"jichu"},
{"id":357,"m":"练习一","t":"单选","q":"在数据可视化流程步骤中，0是指通过数据平台的活动者提供数据来源，以此为基础实现数据获取。","o":["主动式获取","被动式获取","随机获取","抽签获取"],"a":1,"e":"【考点】数据获取方式\n【答案】B\n【解析】题干说“由数据平台的活动者主动提供数据来源”，数据是他人送来的，获取方处于接收位置，属于被动式获取。\n【辨析】主动式获取是取数方自己去采集或拉取，随机获取、抽签获取都不成体系。","k":"sheji"},
{"id":362,"m":"练习一","t":"单选","q":"以下选项中，机器学习算法真正用来“学习“的数据是（）。","o":["验证数据集","训练数据集","测试数据集","超参数集"],"a":1,"e":"【考点】训练数据集\n【答案】B\n【解析】模型参数是在训练数据集上通过反向传播不断调整的，所以真正“学习”用的数据是训练集。\n【辨析】验证集用于调超参与早停，测试集用于最终评估，超参数集不是数据集合。","k":"xunlian"},
{"id":363,"m":"练习一","t":"单选","q":"训练数据集和测试数据集之间应该（）。","o":["互斥","存在交集","包含关系","相等"],"a":0,"e":"【考点】训练集与测试集的关系\n【答案】A\n【解析】两者必须互斥（不重叠），否则测试样本已被模型“见过”，评估结果会虚高，失去对新数据泛化能力的检验意义。\n【辨析】存在交集、包含、相等都会造成数据泄漏，违背评估原则。","k":"yunwei"},
{"id":364,"m":"练习一","t":"单选","q":"如果你需要训练一组图片数据，建议使用0来作为训练模型。","o":["逻辑回归","随机森林","支持向量机","神经网络"],"a":3,"e":"【考点】图像任务选模型\n【答案】D\n【解析】图像数据维度高、空间结构强，需要能提取局部特征并逐层组合的神经网络（尤其卷积神经网络），因此图片任务首选神经网络。\n【辨析】逻辑回归适合简单二分类，随机森林与传统 SVM 在图像上需手工特征、效果有限。","k":"xunlian"},
{"id":365,"m":"练习一","t":"单选","q":"把最简单的调参方法换句话说就是在学习曲线上找到0，以便能够将准确率提高到更高的水平。","o":["最优值","最差值","平均值","最小值"],"a":0,"e":"【考点】学习曲线调参\n【答案】A\n【解析】最简单的调参就是画学习曲线（横轴超参数、纵轴准确率），找到曲线峰值对应的取值，即最优值。\n【辨析】最差值、平均值、最小值都不会带来最高准确率。","k":"jichu"},
{"id":366,"m":"练习一","t":"单选","q":"在模型训练阶段，评估回归问题最常用的性能指标是（）。","o":["精度","ROC","MSE","UC"],"a":2,"e":"【考点】回归模型指标\n【答案】C\n【解析】回归预测连续数值，最常用的评价是 MSE（均方误差）：预测值与真实值差的平方取平均，越小越好。\n【辨析】精度、ROC、AUC 都用于分类任务。","k":"yunwei"},
{"id":367,"m":"练习一","t":"单选","q":"是指机器学习模型通过过多地关注训练数据中的细节和噪声而过度适应训练数据，导致模型泛化性能下降，不能很好地处理新的测试数据。","o":["泛化","欠拟合","过拟合","，不收敛"],"a":2,"e":"【考点】过拟合\n【答案】C\n【解析】模型把训练数据里的细节与噪声也学了进去，训练集表现极好、新数据表现差，这就是过拟合。\n【辨析】泛化是目标能力，欠拟合是学得太浅，不收敛是训练过程问题。","k":"yunwei"},
{"id":368,"m":"练习一","t":"单选","q":"全连接神经网络包括三层，分别（）。","o":["输入层，池化层，输出层","输入层，隐藏层，输出层","输入层，输出层","输入层，卷积层，输出层"],"a":1,"e":"【考点】全连接网络结构\n【答案】B\n【解析】全连接神经网络由输入层接收特征、隐藏层做逐层变换、输出层给出预测，三层结构最典型。\n【辨析】池化层、卷积层属于卷积网络，不是全连接网络的必备层。","k":"xunlian"},
{"id":369,"m":"练习一","t":"单选","q":"卷积神经网络是一种有效的（）工具，能够帮助我们快速、精确地进行图像识别和分类。","o":["检验与预测","语音识别","E图像处理","处理存在时间序列的数据"],"a":2,"e":"【考点】卷积神经网络\n【答案】C\n【解析】CNN 通过卷积核提取局部纹理与边缘、逐层抽象，是图像处理与识别分类最有效的工具。\n【辨析】语音识别、时序数据处理各有专门网络（RNN/Transformer），检验与预测不是它的定位。","k":"xunlian"},
{"id":370,"m":"练习一","t":"单选","q":"（）不属于过拟合的解决办法。","o":["获取更多数据","增加训练的次数","使用合理的模型","结合多种模型"],"a":1,"e":"【考点】过拟合的应对\n【答案】B\n【解析】增加训练次数只会让模型更贴合训练集，过拟合更严重；正确做法是早停。获取更多数据、简化模型、模型集成都能缓解过拟合。\n【辨析】题干问“不属于”，A、C、D 都是有效办法。","k":"xunlian"},
{"id":371,"m":"练习一","t":"单选","q":"以下哪个是解决过拟合最有效的方法0","o":["设计更多特征","增大学习率","获取更多数据","提高模型复杂度"],"a":2,"e":"【考点】解决过拟合最有效的方法\n【答案】C\n【解析】数据越多，模型越难记住每一条样本的噪声，泛化自然更好，因此扩充数据是公认最根本的办法。\n【辨析】加特征、提复杂度会加剧过拟合，增大学习率会破坏收敛。","k":"xunlian"},
{"id":372,"m":"练习一","t":"单选","q":"在应对过拟合的方法中，我们可以通过减少0来避免过度学习，从而更好地匹配真实的模式。","o":["模型复杂度","学习次数","特征值","数据量"],"a":0,"e":"【考点】降低模型复杂度\n【答案】A\n【解析】减少模型复杂度（层数、参数量、特征数）能限制模型“死记硬背”的能力，让它只能学到普遍规律。\n【辨析】学习次数、特征值、数据量都不是“复杂度”这一维度的表述。","k":"xunlian"},
{"id":373,"m":"练习一","t":"单选","q":"无监督学习任务中，0是最常见也是应用最广泛的研究领域。","o":["聚类","分类","回归","关联分析"],"a":0,"e":"【考点】无监督学习的主要领域\n【答案】A\n【解析】无监督学习最成熟、应用最广的是聚类：把相似样本自动归组（客户分群、异常检测、图像分割预处理）。\n【辨析】分类、回归是监督学习任务，关联分析虽也属无监督但应用面不如聚类广。","k":"xunlian"},
{"id":374,"m":"练习一","t":"单选","q":"衡量聚类算法表现的标准通常被称为有（）。","o":["密度估计","异常检测","有效性指标","分布结构"],"a":2,"e":"【考点】聚类评价指标\n【答案】C\n【解析】聚类没有标签，只能靠内部或外部有效性指标衡量簇内紧密、簇间分离的程度（轮廓系数、DBI、DI）。\n【辨析】密度估计、异常检测是聚类可应用的场景，分布结构是数据特征，都不是评价标准。","k":"xunlian"},
{"id":375,"m":"练习一","t":"单选","q":"在以下哪个行业，人工智能应用较为广泛（）。","o":["金融行业","电子行业","教育行业","农业行业"],"a":0,"e":"【考点】AI 应用最广泛的行业\n【答案】A\n【解析】题库设定金融行业为 AI 应用最广泛的领域：风控、投研、客服、反欺诈等场景成熟且投入巨大。\n【辨析】电子、教育、农业也有应用，但规模化与成熟度在本题设定中不如金融。","k":"jichu"},
{"id":376,"m":"练习一","t":"单选","q":"人工智能能够自主学习和逐步优化，这一技术被称为：（）。","o":["机器学习","自动驾驶","语音识别","自然语言处理"],"a":0,"e":"【考点】机器学习\n【答案】A\n【解析】能“自主从数据中学习并逐步优化”的技术就是机器学习，它靠数据驱动改进而不是靠人工写死规则。\n【辨析】自动驾驶是应用场景，语音识别与自然语言处理是具体任务领域。","k":"xunlian"},
{"id":377,"m":"练习一","t":"单选","q":"以下哪个应用场景不适合人工智能技术（）。","o":["财务审计","医疗诊断","美容美发","工业生产控制"],"a":2,"e":"【考点】AI 应用的适配性\n【答案】C\n【解析】财务审计（票据识别与稽核）、医疗诊断（影像辅助）、工业控制（视觉质检）都有大量数据可学、规律可建模；美容美发高度依赖手工技艺与个人审美，缺乏可标准化的数据任务，不适合作为典型 AI 场景。\n【辨析】题干问“不适合”，A、B、D 都是成熟落地领域。","k":"jichu"},
{"id":378,"m":"练习一","t":"单选","q":"以下哪个技术不属于人工智能技术（）。","o":["机器视觉","数据挖掘","区块链","自然语言处理"],"a":2,"e":"【考点】AI 技术范畴\n【答案】C\n【解析】机器视觉、数据挖掘、自然语言处理都属于人工智能的技术分支；区块链是分布式账本与共识技术，与 AI 属于不同技术体系。\n【辨析】题干问“不属于”，A、B、D 都在 AI 范畴内。","k":"jichu"},
{"id":379,"m":"练习一","t":"单选","q":"以下哪个领域尚未开始大规模应用人工智能技术（）.","o":["智慧城市","自动驾驶","金融领域","工业"],"a":3,"e":"【考点】AI 行业渗透程度\n【答案】D\n【解析】题库把工业列为尚未大规模应用 AI 的领域（历史题设定），其余三者在当时已广泛落地。\n【辨析】智慧城市、自动驾驶、金融都已规模化投入；如今工业质检也在快速普及，但本题按题库答案作答。","k":"jichu"},
{"id":380,"m":"练习一","t":"单选","q":"目前人工智能在农业领域的应用主要是（）。","o":["植保无人机","精准施肥","物联网养殖","农产品物流跟踪"],"a":0,"e":"【考点】AI 在农业的代表应用\n【答案】A\n【解析】植保无人机结合飞控与视觉识别，实现精准喷洒、病虫害巡查，是农业 AI 最直观的落地形态。\n【辨析】精准施肥、物联网养殖、物流跟踪偏物联网与自动化，AI 特征不如无人机视觉明显。","k":"jichu"},
{"id":381,"m":"练习一","t":"单选","q":"以下关于精度与错误率两种性能度量说法中错误的是（）。","o":["精度与错误率的和为1","精度与错误率都可以反映模型的好坏","精度与错误率都可以用概率密度函数表示","精度是评价模型的唯一标准"],"a":3,"e":"【考点】精度与错误率\n【答案】D\n【解析】精度（准确率）只是评价指标之一，还需看精确率、召回率、F1、AUC 等，单一指标无法全面反映模型好坏，所以“唯一标准”的说法错误。\n【辨析】A 两者互补为 1，B 都能反映好坏，C 都可基于概率分布计算，三项表述都正确。","k":"jichu"},
{"id":386,"m":"练习一","t":"单选","q":"以下0不属于大数据分析的方法体系。","o":["面向数据视角的分析方法","面向流程视角的分析方法","面向信息技术视角的分析方法","面向个人视角的分析方法"],"a":3,"e":"【考点】大数据分析的方法体系\n【答案】D\n【解析】分析方法体系从三个视角构建：面向数据（处理对象）、面向流程（步骤阶段）、面向信息技术（架构与计算模式）。面向个人视角不构成方法体系维度。\n【辨析】题干问“不属于”，A、B、C 都是标准视角。","k":"yewu"},
{"id":387,"m":"练习一","t":"单选","q":"面向数据视角的大数据分析方法（）。","o":["主要是以大数据分析处理的对象\"数据依据","主要关注大数据分析的步骤和阶段","强调大数据本身设计的新型信息技术","梳理了一些适用于大数据的关键技术，包括神经网络、遗传算法、回归分析等"],"a":0,"e":"【考点】面向数据视角\n【答案】A\n【解析】面向数据视角以“分析处理的对象——数据”为依据，按数据类型与形态（结构化、文本、图像、流数据）选择方法。\n【辨析】B 是流程视角，C 是信息技术视角，D 罗列关键技术属技术层面而非视角定义。","k":"yewu"},
{"id":388,"m":"练习一","t":"单选","q":"探讨大数据处理架构、系统和计算模式等信息技术视角，以应用于（）研究。","o":["面向流程视角的分析方法","面向数据视角的分析方法","面向个人视角的分析方法","面向信息技术视角的分析方法"],"a":3,"e":"【考点】面向信息技术视角\n【答案】D\n【解析】题干谈处理架构、系统与计算模式（分布式、批流一体、内存计算），这正是面向信息技术视角的分析方法。\n【辨析】流程视角看步骤，数据视角看对象，个人视角不是体系内维度。","k":"yewu"},
{"id":389,"m":"练习一","t":"单选","q":"K折交叉验证将数据集0分成K份，每次将K-1份用于训练，1份用于验证模型的性能。","o":["随机","正比例","反比例","等比例"],"a":3,"e":"【考点】K 折交叉验证的划分\n【答案】D\n【解析】K 折交叉验证把数据集等比例切成 K 份（每份样本量基本相同），轮流留一份验证、其余训练，保证各折可比。\n【辨析】随机分、正比例、反比例都会造成各折样本量差异，评估结果不可比。","k":"xunlian"},
{"id":390,"m":"练习一","t":"单选","q":"我们采用k折交叉验证来测定模型表现，把0作为最终的模型评价标准。","o":["K次确率值的平均值","K次确率值的最大值","K次确率值的中位数","K次确率值的最小值"],"a":0,"e":"【考点】交叉验证的评价取值\n【答案】A\n【解析】K 折跑完得到 K 个准确率，最终以这 K 次的平均值作为模型性能估计，能降低单次划分带来的偶然性。\n【辨析】取最大、最小、中位数都会放大或忽略波动，平均值最稳健。","k":"xunlian"},
{"id":391,"m":"练习一","t":"单选","q":"在K折交叉验证中，将数据集分为K份，取其中0作为测试集，剩余的0作为训练集。","o":["K份数据，1份数据","1份数据，K份数据","1份数据，K-1份数据","k-1份数据，1份数据"],"a":2,"e":"【考点】K 折的测试与训练比例\n【答案】C\n【解析】把数据分 K 份后，每轮取 1 份作测试集、剩下的 K-1 份作训练集，这样每份数据都恰好被测试一次。\n【辨析】A、B、D 的分法与“留一验证”逻辑不符。","k":"yunwei"},
{"id":392,"m":"练习一","t":"单选","q":"对0可以使用方差分析(ANOV来进行统计检验。","o":["类别数据","数值数据","顺序数据","以上都是"],"a":1,"e":"【考点】方差分析的适用数据类型\n【答案】B\n【解析】方差分析（ANOVA）比较各组均值差异，计算依赖均值与方差，因此要求数据是数值型（连续变量），类别数据无法求均值。\n【辨析】类别数据适用卡方检验，顺序数据用非参数检验（如秩和检验）。","k":"yewu"},
{"id":393,"m":"练习一","t":"单选","q":"将样本数据应用于总体，并且利用这些数据得出近似总体参数的过程，称为（）","o":["抽样估计","参数估计","近似估计","统计推断"],"a":1,"e":"【考点】参数估计\n【答案】B\n【解析】用样本统计量推断总体参数（均值、比例、方差）的过程叫参数估计，分点估计与区间估计两类。\n【辨析】抽样估计偏重“怎么抽”，近似估计不是标准术语，统计推断是更大的范畴。","k":"jichu"},
{"id":394,"m":"练习一","t":"单选","q":"在我们对总体参数进行点估计之后，我们可以通过使用样本数据来计算出0，并根据估计误差的大小给出一个总体参数可能存在的区间范围。","o":["标准差","估计误差","方差","估计方差"],"a":1,"e":"【考点】估计误差\n【答案】B\n【解析】点估计之后要衡量“估得准不准”，靠计算估计误差（标准误等），再据此给出参数可能的区间范围。\n【辨析】标准差描述数据离散，方差是其平方，估计方差是针对方差本身的估计，都不直接用于构造区间。","k":"jichu"},
{"id":395,"m":"练习一","t":"单选","q":"当我们拿到一些数据样本后，通过这些数据样本可以估算出总体参数可能的取值范围，这个取值范围被称作（）。","o":["置信上限","置信系数","置信区间","置信下限"],"a":2,"e":"【考点】置信区间\n【答案】C\n【解析】由样本推断出的、以一定置信水平包含真实参数的取值范围，称为置信区间，两端分别是置信下限与上限。\n【辨析】置信上限、下限只是区间的端点，置信系数是置信水平（如 95%）。","k":"yewu"},
{"id":396,"m":"练习一","t":"单选","q":"回归模型y=ax+b表示一个关于x的（）。","o":["一元线性回归","多项式回归","岭回归","Lasso回归"],"a":0,"e":"【考点】一元线性回归\n【答案】A\n【解析】y = ax + b 只有一个自变量 x、且 x 为一次项，是一条直线的方程，属于一元线性回归。\n【辨析】多项式回归含高次项，岭回归与 Lasso 是带正则的线性回归变体，形式上都含惩罚项。","k":"xunlian"},
{"id":397,"m":"练习一","t":"单选","q":"逻辑回归是一种用于（）。","o":["预测的模型","优化的模型","评价的模型","分类的模型"],"a":3,"e":"【考点】逻辑回归的用途\n【答案】D\n【解析】逻辑回归输出 0~1 的概率，按阈值判定类别，本质是分类模型（虽名为“回归”）。\n【辨析】它不是预测连续值的回归，也不是优化或评价模型的方法。","k":"xunlian"},
{"id":398,"m":"练习一","t":"单选","q":"逻辑回归是一种常用于将数据归为0的技术。","o":["二分类","多分类","多标签分类","目标分类"],"a":0,"e":"【考点】逻辑回归的典型场景\n【答案】A\n【解析】逻辑回归最常用于二分类（如是否违约、是否患病），用 sigmoid 把线性输出压成概率。\n【辨析】多分类、多标签需 softmax 或一对多改造，目标分类不是标准术语。","k":"xunlian"},
{"id":399,"m":"练习二","t":"单选","q":"逻辑回归是基于0理论的分类算法。","o":["K近邻算法","决策树","线性回归","支持向量机"],"a":2,"e":"【考点】逻辑回归的理论基础\n【答案】C\n【解析】逻辑回归是在线性回归（w x + b）的基础上套一个 sigmoid 函数得到概率，所以其理论根基是线性回归。\n【辨析】KNN 靠距离投票，决策树靠分裂规则，SVM 靠间隔最大化，都不是逻辑回归的来源。","k":"xunlian"},
{"id":400,"m":"练习二","t":"单选","q":"（）是通过对比两个或以上的数据，分析它们的差异，从而揭示数据所代表的规律。","o":["对比分析法","漏斗分析法","留存分析法","矩阵分析法"],"a":0,"e":"【考点】对比分析法\n【答案】A\n【解析】把两个及以上数据放在一起比差异、找规律，就是对比分析法，是最基础的分析方法。\n【辨析】漏斗分析看转化流失，留存分析看回访，矩阵分析做多维交叉。","k":"yewu"},
{"id":401,"m":"练习二","t":"单选","q":"对比分析法可以被归类为两种不同的类型，包括","o":["单项比较和综合比较","静态比较和动态比较","全面比较和曲型比较","相比比较和相差比较"],"a":1,"e":"【考点】对比分析的类型\n【答案】B\n【解析】对比分析分为静态比较（同一时间不同对象比）与动态比较（同一对象不同时间比）两类，这是最常用的划分。\n【辨析】单项/综合、全面/典型、相比/相差都不是标准的二分法。","k":"yewu"},
{"id":402,"m":"练习二","t":"单选","q":"同一时间条件下对不同总体指标进行比较的方法被称为0，在对比分析中使用。","o":["静态比较","动态比较","效益比较","速度比较"],"a":0,"e":"【考点】静态比较\n【答案】A\n【解析】同一时间条件下比较不同总体（如本月各省销量对比），时间维度不变、对象不同，属于静态比较。\n【辨析】动态比较是同一对象跨时间比较，效益比较与速度比较是按内容划分的说法。","k":"yewu"},
{"id":403,"m":"练习二","t":"单选","q":"要使用分组分析法，首先需要明确（）。","o":["确定合理的分组形式","正确选择分组标志和分组指标","确定组数和组距","正确选择分组标志和划分各组界限"],"a":2,"e":"【考点】分组分析的前提\n【答案】C\n【解析】题库把“确定组数和组距”作为分组分析首先要明确的事项：分几组、每组跨度多大，直接决定分组结果与结论可读性。\n【辨析】分组标志与界限的确定当然也重要，但本题设定的答案为组数与组距。","k":"jichu"},
{"id":404,"m":"练习二","t":"单选","q":"适合采用等距分组法的情况是（）。","o":["各类变动的数据都适用","各单位数据变动比较均匀的情况","呈急剧升降变动的数据","按一定上升率变动的数据"],"a":1,"e":"【考点】等距分组的适用条件\n【答案】B\n【解析】数据变动比较均匀时，用相同组距就能把样本均匀分开，不会出现某组挤满、某组空置，所以适合等距分组。\n【辨析】急剧升降的数据需不等距分组，按比例变动的数据也需按比例设组距。","k":"jichu"},
{"id":405,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个指标用于衡量算法的分类能力（）。","o":["精度","召回率","F1分数","UCROC"],"a":0,"e":"【考点】分类能力的衡量\n【答案】A\n【解析】题库用“精度”（准确率）衡量算法的分类能力：预测正确的比例越高，分类能力越强。\n【辨析】召回率只看正类找回多少，F1 是调和指标，AUC 衡量排序能力。","k":"xunlian"},
{"id":406,"m":"练习二","t":"单选","q":"人工智能(AI)业务分析中，下列哪个工具用于探索数据集中的结构和模式（）。","o":["决策树","聚类分析","神经网络","随机森林"],"a":1,"e":"【考点】探索数据结构与模式的工具\n【答案】B\n【解析】聚类分析不需要标签，靠样本间距离把相似对象自动归组，用于发现数据内在结构与分群模式。\n【辨析】决策树、神经网络、随机森林都需要标签做监督学习，不能用于无标签结构探索。","k":"xunlian"},
{"id":407,"m":"练习二","t":"单选","q":"下列哪个机器学习任务用于预测数值型输出变量（）.","o":["分类","聚类","回归","降维"],"a":2,"e":"【考点】回归任务\n【答案】C\n【解析】输出是连续数值（价格、销量、温度）的预测任务叫回归。\n【辨析】分类输出类别，聚类无标签分组，降维压缩特征维度。","k":"xunlian"},
{"id":408,"m":"练习二","t":"单选","q":"交互设计师追求的双重目标是（）。","o":["关注用户的需求和行为","可用性和用户情感体验","产品的功能全面性和界面易用性","设计产品的外观和视觉效果"],"a":1,"e":"【考点】交互设计师的双重目标\n【答案】B\n【解析】交互设计既要让产品好用（可用性），又要让用户用得愉悦（情感体验），这两个目标缺一不可。\n【辨析】A 是设计依据而非目标，C、D 只覆盖功能与视觉的一侧。","k":"sheji"},
{"id":409,"m":"练习二","t":"单选","q":"用户界面设计的核心元素之一是0，它决定了用户是否能够轻松地使用应用程序。","o":["简明","熟悉","易响应","清晰度"],"a":3,"e":"【考点】界面设计的核心元素\n【答案】D\n【解析】题库把“清晰度”作为决定用户能否轻松上手的关键：信息层级、文字、图标都要清楚无歧义。\n【辨析】简明、熟悉、易响应也重要，但本题设定的核心元素是清晰度。","k":"sheji"},
{"id":410,"m":"练习二","t":"单选","q":"（）有助于节省用户宝贵的时间。","o":["保持简洁","易响应","操作一致","有吸引力"],"a":0,"e":"【考点】节省用户时间的设计原则\n【答案】A\n【解析】保持简洁能减少无关信息与多余步骤，用户不必在杂乱界面里寻找，直接省下时间。\n【辨析】易响应减少等待但不等同省时，操作一致降低学习成本，有吸引力影响体验偏好。","k":"sheji"},
{"id":411,"m":"练习二","t":"单选","q":"设计师应该努力使自己的界面直观而友好，直观可以通过0来实现。","o":["简明","清晰","熟悉","高效"],"a":2,"e":"【考点】直观的实现方式\n【答案】C\n【解析】直观靠“熟悉”实现：用用户已习惯的图标、布局与操作逻辑，不必学习就能明白怎么用。\n【辨析】简明是减少内容，清晰是表达明确，高效是完成任务快，都不是“一看就懂”的直接来源。","k":"sheji"},
{"id":412,"m":"练习二","t":"单选","q":"一个优秀的用户界面应当具有0的特点，以带给用户愉悦的交互体验。","o":["易响应","操作一致","有吸引力","高效"],"a":2,"e":"【考点】愉悦体验的来源\n【答案】C\n【解析】“有吸引力”的界面（配色、动效、细节质感）会带来愉悦的情绪体验，这是体验层面的加分项。\n【辨析】易响应、一致、高效解决的是“好用”，愉悦更多来自吸引力。","k":"sheji"},
{"id":413,"m":"练习二","t":"单选","q":"界面设计的吸引力常取决于0的因素","o":["情感和文化","内容的主次和轻重","结构的虚实和繁简","形体的大小和配色"],"a":0,"e":"【考点】界面吸引力的决定因素\n【答案】A\n【解析】界面能否打动人，取决于是否契合用户的情感与文化背景（色彩寓意、审美习惯、价值取向）。\n【辨析】内容主次、结构繁简属于信息架构，形体大小与配色是表现手段。","k":"sheji"},
{"id":418,"m":"练习二","t":"单选","q":"在0阶段明确各个设计元素的定义，并着重考虑信息和功能的呈现方式。","o":["定义需求","交互设计","概念设计","修改设计"],"a":2,"e":"【考点】概念设计阶段\n【答案】C\n【解析】概念设计阶段要明确各设计元素的定义，并重点想清楚信息与功能如何呈现，产出整体方案骨架。\n【辨析】定义需求是弄清要做什么，交互设计细化操作流程，修改设计是迭代优化。","k":"sheji"},
{"id":419,"m":"练习二","t":"单选","q":"下列选项中，关于交互设计的基本目标正确描述是（）.","o":["通过技术手段来提高人类工作效率","通过各种手段来增强和丰富人类沟通和信自交流的体验","通过界面设计来提高人类使用设备效率","通过心理学研究来提高人类认知能力"],"a":1,"e":"【考点】交互设计的基本目标\n【答案】B\n【解析】交互设计的根本目标是借助各种手段增强、丰富人与人、人与机器之间的沟通与信息交流体验。\n【辨析】A、C 只看效率，D 属认知科学研究，都不能概括“沟通体验”这一核心。","k":"sheji"},
{"id":420,"m":"练习二","t":"单选","q":"麦克卢汉提出0的理论，用以描述人们在媒体和操控方式方面的反应和行为。","o":["地球村","媒介即讯息","冷媒介和热媒介","媒介是人体的延伸"],"a":2,"e":"【考点】麦克卢汉的媒介理论\n【答案】C\n【解析】麦克卢汉提出“冷媒介与热媒介”的划分，用信息清晰度与受众参与度来描述人们对不同媒介的反应方式。\n【辨析】地球村、媒介即讯息、媒介是人的延伸都是他的其他论断，但“描述反应和行为”对应的是冷热媒介。","k":"sheji"},
{"id":421,"m":"练习二","t":"单选","q":"维普兰克在IDEO工作期间提出的“四步工作法\"不包括（）。","o":["动机和观念","隐喻和假设","概念模型","测试和评估"],"a":3,"e":"【考点】IDEO 四步工作法\n【答案】D\n【解析】维普兰克提出的四步法为：动机与观念、隐喻与假设、概念模型、以及后续的设计实现（题库将其归为前三步加实现），“测试和评估”不属于这四步。\n【辨析】题干问“不包括”，A、B、C 都在四步之内。","k":"jichu"},
{"id":422,"m":"练习二","t":"单选","q":"第四个经济阶段被定义为从商品服务中摆脱出来的提供以体验为核心的产品和服务的经济模式，即（）.","o":["产品经济","商品经济","信息经济","体验经济"],"a":3,"e":"【考点】体验经济\n【答案】D\n【解析】题干说“从商品服务中脱离，提供以体验为核心的产品与服务”，这是继农业、工业、服务之后的第四阶段——体验经济。\n【辨析】产品经济、商品经济、信息经济都不以“体验”为核心交付物。","k":"sheji"},
{"id":423,"m":"练习二","t":"单选","q":"JenniferPreece等人认为，交互设计的核心在于（）.","o":["用户需求和行为","产品功能和质量","创建新的用户体验","产品价格和成本"],"a":2,"e":"【考点】交互设计的核心\n【答案】C\n【解析】Preece 等人强调交互设计的核心是“创建新的用户体验”，而不是单纯堆功能或压成本。\n【辨析】用户需求与行为是设计依据，功能质量是要求，价格成本是商业考量。","k":"sheji"},
{"id":424,"m":"练习二","t":"单选","q":"下列选项中，属于交互设计所需要完成的目标的是（）.","o":["可用性目标和用户体验目标","商业目标和技术目标","商业目标和用户体验目标","可用性目标和技术目标"],"a":0,"e":"【考点】交互设计的两个目标\n【答案】A\n【解析】交互设计要同时达成可用性目标（好用、高效、少出错）与用户体验目标（愉悦、有趣、有情感），二者并列。\n【辨析】商业目标、技术目标是项目层面的约束，不属于交互设计的目标分类。","k":"sheji"},
{"id":425,"m":"练习二","t":"单选","q":"（）是从终端用户的角度来评估系统提供的用户体验有多良好和效率有多高。","o":["用户体验目标","可用性目标","商业目标","技术目标"],"a":1,"e":"【考点】可用性目标\n【答案】B\n【解析】从终端用户角度评估系统“好不好用、效率高不高”，是可量化的可用性目标（效率、错误率、学习成本）。\n【辨析】用户体验目标偏主观感受，商业与技术目标不是从用户视角衡量。","k":"yunwei"},
{"id":426,"m":"练习二","t":"单选","q":"在交互设计中，可用性目标强调0，与用户体验目标进行比较。","o":["随机性","客观性","主观性","准确性"],"a":1,"e":"【考点】可用性目标的属性\n【答案】B\n【解析】可用性可用任务完成时间、错误次数、成功率等客观指标度量，因此强调客观性；用户体验目标则偏主观。\n【辨析】随机性、主观性、准确性都不足以概括可用性的度量特征。","k":"yunwei"},
{"id":427,"m":"练习二","t":"单选","q":"在交互设计中，关注整体布局、功能结构以及内容组织的是（）。","o":["战略层","范国层","框架层","结构层"],"a":2,"e":"【考点】体验设计的层次（框架层）\n【答案】C\n【解析】框架层关注整体布局、功能结构与内容组织：导航放哪、信息分区如何排，是把结构层方案落到页面骨架。\n【辨析】战略层定目标与需求，范围层定内容范围，结构层定信息架构与流程。","k":"sheji"},
{"id":428,"m":"练习二","t":"单选","q":"在交互设计中，战略层的聚焦点在于0，这是重中之重。","o":["网站目标和用户需求","产品功能和内容","交互方式和界面设计","技术实现和性能优化"],"a":0,"e":"【考点】战略层\n【答案】A\n【解析】战略层是整个设计的地基：明确产品要达成什么目标、用户真正需要什么，后续所有层级都服从于此。\n【辨析】功能与内容属范围层，交互与界面属框架/表现层，技术实现不在体验层次模型内。","k":"sheji"},
{"id":429,"m":"练习二","t":"单选","q":"在感官体验类别下，网站必须遵守0的交互设计标准，确保导航条清晰明了，层次分明，以便于用户快速找到所需信息。","o":["页面布局","页面色彩","页面导航","页面大小"],"a":2,"e":"【考点】页面导航\n【答案】C\n【解析】题干强调“导航条清晰、层次分明、快速找到信息”，对应的正是页面导航设计标准。\n【辨析】布局、色彩、大小会影响观感，但“找到所需信息”靠的是导航。","k":"sheji"},
{"id":430,"m":"练习二","t":"单选","q":"在人机交互界面设计中，0不属于用户模型主要关注的。","o":["目标","信心","交互过程","情绪"],"a":2,"e":"【考点】用户模型关注点\n【答案】C\n【解析】用户模型描述用户的目标、认知、信心与情绪等心理与需求特征；交互过程是系统行为，属于实现者模型的范畴。\n【辨析】题干问“不属于”，A、B、D 都是用户模型的关注点。","k":"sheji"},
{"id":431,"m":"练习二","t":"单选","q":"在人机交互界面设计中，0不属于实现者模型主要关注的。","o":["数据结构","算法","数据库","信心"],"a":3,"e":"【考点】实现者模型关注点\n【答案】D\n【解析】实现者模型从技术实现出发，关心数据结构、算法、数据库等；信心是用户心理状态，属用户模型。\n【辨析】题干问“不属于”，A、B、C 都是技术侧关注点。","k":"sheji"},
{"id":432,"m":"练习二","t":"单选","q":"重点强调0的理论指导，是人机交互学科的理论体系的重要特点。","o":["人文科学","工业设计","嵌入式技术","视觉传达"],"a":0,"e":"【考点】人机交互的理论来源\n【答案】A\n【解析】人机交互的理论体系重点汲取人文科学（心理学、认知科学、社会学）的成果来解释人与机器的互动。\n【辨析】工业设计、嵌入式技术、视觉传达是应用侧，不是其理论指导核心。","k":"sheji"},
{"id":433,"m":"练习二","t":"单选","q":"以下0不属于广义上交互设计内容。","o":["电脑","芯片嵌入式产品","互联网","家具"],"a":3,"e":"【考点】广义交互设计的范围\n【答案】D\n【解析】广义交互设计覆盖电脑、嵌入式产品、互联网等具有信息交互能力的对象；普通家具不具备交互与反馈能力，不在其中。\n【辨析】题干问“不属于”，A、B、C 都是广义交互设计对象。","k":"sheji"},
{"id":434,"m":"练习二","t":"单选","q":"在进行交互设计时，首先需要进行（）。","o":["用户研究","需求分析","概念设计","原型设计"],"a":1,"e":"【考点】交互设计的起点\n【答案】B\n【解析】任何设计都要先弄清“要解决什么问题、满足什么需求”，所以第一步是需求分析，之后才做研究与概念设计。\n【辨析】用户研究是需求分析的手段之一，概念设计与原型设计都在需求明确之后。","k":"sheji"},
{"id":435,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个关键词指的是根据给定的输入变量的值来预测类别变量的类别（）.","o":["监督学习","无监督学习","半监督学习","强化学习"],"a":0,"e":"【考点】监督学习\n【答案】A\n【解析】用带标签的训练数据学习“输入→类别”的映射，再预测新样本类别，这是监督学习（分类）的定义。\n【辨析】无监督学习无标签，半监督用少量标签，强化学习靠奖励信号试错。","k":"xunlian"},
{"id":436,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个关键词指的是将数据特征的维度降低到较少的维度（）。","o":["聚类","回归","降维","分类"],"a":2,"e":"【考点】降维\n【答案】C\n【解析】把高维特征压缩到低维空间（PCA、t-SNE、自编码器）同时尽量保留信息，就是降维。\n【辨析】聚类分组、回归预测数值、分类判定类别，都不以减少维度为目标。","k":"xunlian"},
{"id":437,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个算法适用于大规模数据集（）。","o":["线性回归","决策树","K-近邻算法","随机森林"],"a":3,"e":"【考点】适合大数据的算法\n【答案】D\n【解析】随机森林可并行建树、对样本抽样、对特征抽样，训练与预测都能分布式扩展，最适合大规模数据集。\n【辨析】线性回归对特征工程敏感，单棵决策树易过拟合，KNN 预测时需遍历全量样本、规模大时极慢。","k":"xunlian"},
{"id":438,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个关键词指的是通过学习一个规则集合来进行分类或回归（）。","o":["决策树","聚类分析","随机森林","神经网络"],"a":0,"e":"【考点】决策树\n【答案】A\n【解析】决策树通过一系列判断规则（若特征 X>阈值则走左枝）形成一棵树，可做分类也可做回归，规则集即模型。\n【辨析】聚类无规则集，随机森林是多棵树集成，神经网络靠权重而非显式规则。","k":"xunlian"},
{"id":439,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个关键词指的是从大量未标记的数据中发现结构（）。","o":["压缩感知","降维","聚类","无监督学习"],"a":3,"e":"【考点】无监督学习\n【答案】D\n【解析】从大量未标注数据中发现内在结构（分群、密度、关联），属于无监督学习，其典型任务包括聚类与降维。\n【辨析】降维、聚类是具体方法，压缩感知是信号处理技术，都不如“无监督学习”概括得准。","k":"xunlian"},
{"id":440,"m":"练习二","t":"单选","q":"在人工智能(AI)业务分析中，下列哪个关键词指的是根据已有的训练集来调整模型参数以优化模型效果0","o":["有监督学习","无监督学习","半监督学习","强化学习"],"a":0,"e":"【考点】有监督学习\n【答案】A\n【解析】用已有训练集（输入+标签）调整模型参数以最小化误差、提升效果，这是有监督学习的训练过程。\n【辨析】无监督无标签，半监督标签很少，强化学习靠环境奖励而非固定训练集标签。","k":"xunlian"},
{"id":441,"m":"练习二","t":"单选","q":"预测分析方法运用了0和0的分析理论与方法。","o":["算术平均，加权平均","比较，结构","定性，定量","交叉，聚类"],"a":2,"e":"【考点】预测分析的理论基础\n【答案】C\n【解析】预测分析同时用定性方法（专家判断、德尔菲）与定量方法（回归、时间序列），两者结合才能既解释又精确。\n【辨析】算术/加权平均、比较/结构、交叉/聚类都只是具体技术，不是方法论层面的两大支柱。","k":"jichu"},
{"id":442,"m":"练习二","t":"单选","q":"以下0不属于常用的预测分析法。","o":["回归分析法","时间序列分析法","神经网络","交叉分析法"],"a":3,"e":"【考点】常用预测分析方法\n【答案】D\n【解析】回归分析、时间序列分析、神经网络都是成熟的预测方法；交叉分析是多维对比手段，用于找差异而非预测未来。\n【辨析】题干问“不属于”，A、B、C 都是预测方法。","k":"jichu"},
{"id":445,"m":"练习二","t":"单选","q":"AB测试分析法旨在比较两组结构O的样本，即A组与B组，以评估它们在某个特定变量上的差异。","o":["完全不同","一致","较大差异","相似"],"a":3,"e":"【考点】AB 测试的样本条件\n【答案】D\n【解析】AB 测试要求两组样本结构相似（同质），只在一个变量上做差异处理，才能把效果差异归因于该变量。\n【辨析】完全不同、较大差异会让两组缺乏可比性，一致则无法形成对照。","k":"yunwei"},
{"id":446,"m":"练习二","t":"单选","q":"AB测试分析方法是使用样本数据O来比较和分析两个或多个群体之间的差异。","o":["最大值","最小值","指标值","方差"],"a":2,"e":"【考点】AB 测试的比较依据\n【答案】C\n【解析】AB 测试比的是同一指标值（转化率、点击率、客单价）在两组间的差异，用指标值说话。\n【辨析】最大值、最小值、方差都是指标的统计特征，不能直接替代“比较指标值”这一动作。","k":"yunwei"},
{"id":447,"m":"练习二","t":"单选","q":"如果您正在处理分类数据，那么0是一种可用的统计方法。","o":["相关系数","卡方检验","协方差","方差"],"a":1,"e":"【考点】分类数据的统计检验\n【答案】B\n【解析】分类（类别）数据看的是频数与分布差异，用卡方检验判断两类变量是否相关最合适。\n【辨析】相关系数、协方差、方差都要求数值型数据。","k":"yewu"},
{"id":448,"m":"练习二","t":"单选","q":"一组数据的总和除以数据个数所得的结果被称为（）.","o":["众数","中位数","几何平均数","均值"],"a":3,"e":"【考点】均值\n【答案】D\n【解析】总和除以个数即算术平均数（均值），是最常用的集中趋势度量。\n【辨析】众数是出现最多的值，中位数是排序居中的值，几何平均数是连乘积开 n 次方。","k":"jichu"},
{"id":449,"m":"练习二","t":"单选","q":"（）是一种用于测量一组数据中差异程度的指标。","o":["平均数","方差","众数","中位数"],"a":1,"e":"【考点】方差\n【答案】B\n【解析】方差衡量数据偏离均值的平均程度：各值与均值之差的平方取平均，值越大说明数据越分散。\n【辨析】平均数、众数、中位数描述集中趋势，不反映差异程度。","k":"jichu"},
{"id":450,"m":"练习二","t":"单选","q":"平均数离差平方的平均值定义为0，其中离差是指每个变量与平均数之间的差。","o":["极差","平均差","方差","标准差"],"a":2,"e":"【考点】方差的定义\n【答案】C\n【解析】离差是每个变量与平均数的差，离差平方的平均值就是方差，用来衡量数据分散程度。\n【辨析】极差是最大值与最小值之差，平均差取离差绝对值平均，标准差是方差的算术平方根。","k":"jichu"},
{"id":451,"m":"练习二","t":"单选","q":"在特征工程中，针对0的数据类型，我们可以使用一种名为独热编码的方法来进行编码。","o":["定类变量","定序变量","定距变量","定比变量"],"a":0,"e":"【考点】独热编码适用类型\n【答案】A\n【解析】定类变量（性别、城市、颜色）之间无大小顺序，只能按类别打散成多个 0/1 列，正适合独热编码。\n【辨析】定序、定距、定比变量有顺序或数值关系，用独热会丢掉顺序信息，一般用标签编码或直接保留数值。","k":"xunlian"},
{"id":452,"m":"练习二","t":"单选","q":"在特征构建过程中，使用0方法对定序变量进行数据类型编码。","o":["独热编码","标签编码","链式编码","块状编码"],"a":1,"e":"【考点】定序变量的编码\n【答案】B\n【解析】定序变量（低/中/高、一级/二级/三级）之间有顺序，用标签编码映射为 0、1、2 可保留大小关系。\n【辨析】独热编码会抹掉顺序，链式编码、块状编码不是标准编码方法。","k":"xunlian"},
{"id":453,"m":"练习二","t":"单选","q":"在特征工程中，对数值型变量进行离散化处理，即（）.","o":["分箱操作","回归操作","递归操作","聚合操作"],"a":0,"e":"【考点】数值离散化\n【答案】A\n【解析】把连续数值切成若干区间、每区间赋一个离散值，就是分箱（等宽、等频、聚类分箱都属此类）。\n【辨析】回归是建模预测，递归是算法结构，聚合是汇总统计，都不做“分段离散化”。","k":"xunlian"},
{"id":454,"m":"练习二","t":"单选","q":"（）是一种分析客观现象各种数据特征的方法。","o":["多元统计分析","描述性统计分析","探索性统计分析","推断性统计分析"],"a":1,"e":"【考点】描述性统计分析\n【答案】B\n【解析】用均值、中位数、方差、分布等指标客观刻画数据的特征与形态，就是描述性统计分析。\n【辨析】多元统计处理多变量关系，探索性分析找未知模式，推断性分析由样本推总体。","k":"xunlian"},
{"id":455,"m":"练习二","t":"单选","q":"以下0不属于描述性统计分析常用数据统计内容。","o":["平均值","最大值","最小值","相关分析"],"a":3,"e":"【考点】描述性统计的内容\n【答案】D\n【解析】平均值、最大值、最小值都是单个变量的概括性统计量；相关分析研究两个变量的关系，属推断/多元分析范畴。\n【辨析】题干问“不属于”，A、B、C 都是描述统计的常规内容。","k":"yewu"},
{"id":456,"m":"练习二","t":"单选","q":"以下0不属于一个网页的描述性分析的内容。","o":["网页的访问人次","网页的访问人数","网页访问量的平均值","网页访问人员性别的性别假设检验"],"a":3,"e":"【考点】网页描述性分析的边界\n【答案】D\n【解析】访问人次、访问人数、访问量平均值都是对现状的客观描述；性别假设检验属于推断性统计（用样本推断总体差异是否显著），不是描述。\n【辨析】题干问“不属于”，A、B、C 都是描述性指标。","k":"yewu"},
{"id":457,"m":"练习二","t":"单选","q":"通过一些分析方法从大量的数据中发现未知具有价值信息过程的是0","o":["多元统计分析","描述性统计分析","探索性统计分析","推断性统计分析"],"a":2,"e":"【考点】探索性统计分析\n【答案】C\n【解析】从大量数据中发现未知但有价值的信息与模式，是探索性分析（EDA）的核心任务，常用可视化、聚类、关联规则。\n【辨析】描述统计只汇总已知特征，推断统计做参数推断，多元统计处理多变量结构。","k":"yewu"},
{"id":458,"m":"练习二","t":"单选","q":"探索性统计分析的目的在于发现和探索变量之间可能存在的（）。","o":["复杂性","关联性","差异性","动态性"],"a":1,"e":"【考点】探索性分析的目的\n【答案】B\n【解析】探索性分析要找出变量之间可能存在的关联（如啤酒与尿布的购买关联），为进一步建模提供线索。\n【辨析】复杂性、差异性、动态性都不是探索性分析要发现的核心对象。","k":"yewu"},
{"id":459,"m":"练习二","t":"单选","q":"（）适合用于研究超市啤酒和尿不湿销售量之间是否存在一定的关系。","o":["多元统计分析","降维统计分析方法","描述性统计分析","探索性统计分析"],"a":3,"e":"【考点】关联发现的适用方法\n【答案】D\n【解析】啤酒与尿不湿的销量关系是典型的购物篮关联问题，需要从数据中“探索未知关联”，属探索性统计分析（关联规则挖掘）。\n【辨析】描述统计只报销量，多元统计与降维不解决“找关联”，都不如探索性分析贴切。","k":"jichu"},
{"id":460,"m":"练习二","t":"单选","q":"如何确定人工智能技术在业务应用中的有效性（）。","o":["进行AVB测试","检验数据大小和样本量","没有足够的数据时可以采用模拟方法","评估人工智能模型的准确率"],"a":0,"e":"【考点】验证 AI 业务有效性\n【答案】A\n【解析】判断某项 AI 技术在业务里到底有没有用，最可靠的是做 A/B 测试：一组用、一组不用，对比业务指标差异。\n【辨析】检查样本量、模型准确率都只是内部指标，模拟方法不能替代真实业务验证。","k":"jichu"},
{"id":461,"m":"练习二","t":"单选","q":"何谓无监督学习（）。","o":["不依赖于已知分类的数据的学习过程","基于分类标准和目标函数的学习","不断选代计算，趋近数据实际分布","带有期望输出值的学习过程"],"a":0,"e":"【考点】无监督学习\n【答案】A\n【解析】无监督学习不依赖已知分类标签，直接从数据本身的结构中学习（聚类、降维、密度估计）。\n【辨析】B、D 都涉及已知标签或期望输出，属监督学习；C 描述的是迭代逼近分布的训练过程。","k":"xunlian"},
{"id":462,"m":"练习二","t":"单选","q":"如何防止在业务分析中的优化算法过拟合（）。","o":["采用Neon神经网络平台","减少样本程序的复杂度","增加数据集规模或增加维数","通过学习率调整避免过拟合"],"a":2,"e":"【考点】防过拟合\n【答案】C\n【解析】题库给出的答案是扩充数据规模（增加样本或维度信息），让模型难以记住个别噪声，从而缓解过拟合，这是防过拟合最根本的方向。\n【辨析】A 换平台不解决过拟合，B 表述含糊，D 调学习率主要影响收敛速度。","k":"xunlian"},
{"id":463,"m":"练习二","t":"单选","q":".如何在人工智能技术中处理采用不同的标准和数据格式的数据（）。","o":["在整个数据预处理过程中进行数据标准化","通过转化算法将其转化为一致的模式","进行全局分析，忽略数据源不同","进行数据类型的编码以便于自动识别"],"a":1,"e":"【考点】多源异构数据的统一\n【答案】B\n【解析】不同标准、不同格式的数据要用转换算法映射到一致的模式（统一字段、单位、编码），才能合并使用。\n【辨析】只做标准化不够全面，忽略数据源差异会掩盖问题，单纯编码无法解决模式不一致。","k":"jichu"},
{"id":464,"m":"练习二","t":"单选","q":"何谓“黑匣子模型（）。","o":["单层的神经网络模型","无法解释其工作原理的模型","只能进行简单预测的模型","难以解释其部分功能的模型"],"a":1,"e":"【考点】黑匣子模型\n【答案】B\n【解析】黑匣子模型指内部决策过程难以被人类理解的模型（如深度神经网络），能给出结果但说不清为什么。\n【辨析】单层网络、简单预测都不等于黑匣子；“难以解释部分功能”表述不准确，黑匣子通常是整体不可解释。","k":"xunlian"},
{"id":465,"m":"练习二","t":"单选","q":"根据样本数据的特征推断整体数据特征的分析方法被称为（）。","o":["推断性统计分析","降维统计分析方法","描述性统计分析","探索性统计分析"],"a":0,"e":"【考点】推断性统计分析\n【答案】A\n【解析】由样本特征推断总体特征（估计参数、做假设检验），正是推断性统计分析的任务。\n【辨析】描述统计只讲样本本身，探索性分析找模式，降维是数据处理手段。","k":"xunlian"},
{"id":466,"m":"练习二","t":"单选","q":"了解某批商品的质量水平，可以通过对样品进行抽样分析，并利用0得出这批商品整体的质量水平。","o":["多元统计分析","描述性统计分析","探索性统计分析","推断性统计分析"],"a":3,"e":"【考点】抽样推断\n【答案】D\n【解析】抽检部分样品、据此判断整批商品的质量水平，是由样本推总体，属推断性统计分析。\n【辨析】描述统计只汇总样品数据，探索性分析找未知规律，多元统计处理多变量关系。","k":"yewu"},
{"id":469,"m":"练习二","t":"单选","q":"在Matplotlib中，要绘制柱形图需要使用O数。","o":["histO","ploto","baro","barhO"],"a":2,"e":"【考点】Matplotlib 柱形图\n【答案】C\n【解析】plt.bar(x, height) 绘制竖向柱形图；plt.barh 画水平条形图。\n【辨析】hist 画直方图（按区间统计频数），plot 画折线，都不是柱形图。","k":"sheji"},
{"id":470,"m":"练习二","t":"单选","q":"在使用Matplotlib绘制柱形图时，可以通过调整barO函数中的0参数来柱子边缘的颜色。","o":["color","edgecolor","align","height"],"a":1,"e":"【考点】柱形边框颜色\n【答案】B\n【解析】bar 的 edgecolor 参数控制柱子边缘（描边）颜色，facecolor 或 color 控制填充色。\n【辨析】color 是填充色，align 控制对齐方式，height 是柱高数据。","k":"sheji"},
{"id":471,"m":"练习二","t":"单选","q":"Matplotlib中绘制饼图的函数是（）。","o":["pie0","scatterO","boxplot（）","polarO"],"a":0,"e":"【考点】Matplotlib 饼图\n【答案】A\n【解析】plt.pie(x) 绘制饼图，可配 labels、autopct、explode 展示占比与分离。\n【辨析】scatter 画散点，boxplot 画箱线图，polar 画极坐标图。","k":"sheji"},
{"id":472,"m":"练习二","t":"单选","q":"（）图表种类一般用于时序数据的统计。","o":["折线图","散点图","线图","雷达图"],"a":2,"e":"【考点】时序数据图表\n【答案】C\n【解析】题库把线图（折线图）作为时序数据统计的常用图表：横轴时间、纵轴数值，连续折线最能表现趋势与波动。\n【辨析】散点图看相关性，雷达图看多维对比，都不以时间序列为主轴。","k":"sheji"},
{"id":473,"m":"练习二","t":"单选","q":"Ui代表UserInterface，通常是指O。","o":["人机交互","操作逻辑","用户界面","图形设计"],"a":2,"e":"【考点】UI 的含义\n【答案】C\n【解析】UI 是 User Interface 的缩写，指用户界面：屏幕上看到的布局、控件、色彩与文字。\n【辨析】人机交互是 HCI，操作逻辑偏交互设计，图形设计是视觉层面的工作。","k":"sheji"},
{"id":474,"m":"练习二","t":"单选","q":"根据心理学，界面可以被分为两个层次，分别为（）.","o":["心境，感觉","感觉，情感","心境，情感","感觉，道德"],"a":1,"e":"【考点】界面的心理层次\n【答案】B\n【解析】心理学把界面体验分两层：感觉（视觉、听觉的直接刺激）与情感（由感觉引发的情绪反应），先感知后动情。\n【辨析】心境是持续的情绪状态，道德与界面体验层次无关。","k":"sheji"},
{"id":475,"m":"练习二","t":"多选","q":"纪律是指（）等各种规定，以及针对特定行业有关安全生产的指引和规范。","o":["规章制度","准则","工作职责","公约、守则、条例"],"a":[0,1,2,3],"e":"【考点】纪律的内涵\n【答案】ABCD\n【解析】纪律不只是考勤，还包括规章制度、准则、岗位工作职责，以及公约、守则、条例和行业安全生产指引，凡约束行为的规定都算。\n【辨析】四个选项覆盖制度、准则、职责、公约条例四类规范，均应选。","k":"jichu"},
{"id":476,"m":"练习二","t":"多选","q":"回归分析的一般流程涉及到（）步骤。","o":["初设回归方程","求出合理的回归系数","相关性检验，确定相关系数","计算预测值的置信区间"],"a":[0,1,2,3],"e":"【考点】回归分析流程\n【答案】ABCD\n【解析】完整流程是：设定回归方程形式 → 估计回归系数 → 做相关性/显著性检验确定系数可信 → 用模型预测并给出置信区间。\n【辨析】四步构成“建模—估计—检验—应用”的闭环，缺一不可。","k":"xunlian"},
{"id":477,"m":"练习二","t":"多选","q":"漏斗分析涉及的主要元素包括（）。","o":["时间","变量","结点","研究对象"],"a":[0,2,3],"e":"【考点】漏斗分析的要素\n【答案】ACD\n【解析】漏斗分析看用户在各环节的流失，必须有时段（时间）、漏斗节点（结点）和统计对象（研究对象）。\n【辨析】变量不是漏斗的构成要素，故 B 不选。","k":"yewu"},
{"id":478,"m":"练习二","t":"多选","q":"属于目标导向设计的流程A调查研究","o":["情境建模","定义需求","概念设计","E细化和修改设计"],"a":[0,1,2,3],"e":"【考点】目标导向设计流程\n【答案】ABCD\n【解析】目标导向设计依次为：情境建模（调研用户场景）→ 定义需求 → 概念设计 → 细化与修改设计，四步递进。\n【辨析】四个选项正好对应这一流程的各阶段。","k":"sheji"},
{"id":479,"m":"练习二","t":"多选","q":"是数据质量评估标准。","o":["完整性","准确性","经济性","一致性"],"a":[0,1,3],"e":"【考点】数据质量评估维度\n【答案】ABD\n【解析】数据质量常看完整性（缺不缺）、准确性（对不对）、一致性（口径统一不统一），这三项直接决定可用性。\n【辨析】经济性是成本维度，不是数据质量评价标准，故 C 不选。","k":"yewu"},
{"id":480,"m":"练习二","t":"多选","q":"（）是从网络爬虫的角度对互联网进行划分对应的部分。","o":["已下载的（包括未过期和已过期）网页","待下载网页","可知网页","不可知网页"],"a":[0,1,2,3],"e":"【考点】爬虫视角的网页划分\n【答案】ABCD\n【解析】从爬虫看互联网可分四类：已下载的（含未过期与已过期）、待下载的、可知网页、不可知网页，这决定了抓取策略与更新机制。\n【辨析】四项构成爬虫的完整网页状态视图。","k":"jichu"},
{"id":481,"m":"练习二","t":"多选","q":"JamesGarrett提出的用户体验包括0等多个方","o":["品牌特征","信息可用性","功能性","内容性"],"a":[0,1,2,3],"e":"【考点】用户体验的构成\n【答案】ABCD\n【解析】James Garrett 认为用户体验涵盖品牌特征、信息可用性、功能性、内容性等多个方面，是整体感受而非单一界面美观。\n【辨析】四项都在其体验框架内。","k":"sheji"},
{"id":482,"m":"练习二","t":"多选","q":"算法测试中，用于评价分类算法模型的有效指标有（），它们的最佳表现均为1.（）。","o":["Recall","F1值","Cohen'sKappa系数","均方误差"],"a":[0,1,2],"e":"【考点】分类算法评价指标\n【答案】ABC\n【解析】Recall（召回率）、F1 值、Cohen's Kappa 系数都是分类评价指标，取值越接近 1 表现越好。\n【辨析】均方误差用于回归，值越小越好，不属于分类指标，故 D 不选。","k":"yunwei"},
{"id":483,"m":"练习二","t":"多选","q":"对于一个出色的团队而言，其合作品质包括（）。","o":["成员对团队强烈的归属感","团队有钱","团队具有强大的凝聚力","团队有很强人脉"],"a":[0,2],"e":"【考点】团队合作品质\n【答案】AC\n【解析】优秀团队的合作品质体现在成员有强烈归属感、团队有强大凝聚力，这是协作效率的来源。\n【辨析】团队有钱、有人脉属于资源条件，不是“合作品质”，故 B、D 不选。","k":"peixun"},
{"id":484,"m":"练习二","t":"多选","q":"以下是关于针对软件非功能方面的测试用例的描述，包括（）。","o":["安全测试用例","性能测试用例","兼容性测试用例","故障修复测试用例"],"a":[0,1,2,3],"e":"【考点】非功能测试用例\n【答案】ABCD\n【解析】非功能测试关注“做得怎么样”而不是“能不能做”：安全、性能、兼容性、故障修复验证都属于非功能范畴。\n【辨析】四项都不验证业务功能正确性，而是验证质量属性。","k":"yunwei"},
{"id":485,"m":"练习二","t":"多选","q":"AI系统运维软件的核心功能包括以下哪些方面（）。","o":["监控和普报","配置管理","资源管理","操作和管控"],"a":[0,1,2,3],"e":"【考点】AI 运维软件核心功能\n【答案】ABCD\n【解析】AI 运维软件要能监控告警、管理配置、调度资源、执行操作管控，四块构成运维闭环。\n【辨析】缺监控则看不见，缺配置则管不住，缺资源则跑不动，缺管控则改不了。","k":"yunwei"},
{"id":486,"m":"练习二","t":"多选","q":"常见的数据采集工具有哪些（）。","o":["Python采集库","网络爬虫软件","可视化采集工具","命令行采集工具"],"a":[0,1,2],"e":"【考点】常见数据采集工具\n【答案】ABC\n【解析】Python 采集库（requests、Scrapy）、网络爬虫软件（八爪鱼等）、可视化采集工具都是常见数据采集手段。\n【辨析】命令行采集工具不是通用分类，故 D 不选。","k":"yewu"},
{"id":487,"m":"练习二","t":"多选","q":"以下哪些数据采集方法可以用于社会调查0","o":["面谈","：网络调查","邮寄问卷调查","手机短信推送调查"],"a":[0,1,2],"e":"【考点】社会调查的采集方法\n【答案】ABC\n【解析】面谈、网络调查、邮寄问卷都是成熟的社会调查方式，覆盖面与样本代表性各有优势。\n【辨析】手机短信推送调查不在题库列出的标准方法内，故 D 不选。","k":"yewu"},
{"id":488,"m":"练习二","t":"多选","q":"在数据采集过程中，以下哪些方面需要注意0","o":["合法性","安全性","可靠性","速度快"],"a":[0,1,2],"e":"【考点】数据采集的注意事项\n【答案】ABC\n【解析】采集必须合法（有授权、不侵犯隐私）、安全（传输存储不泄露）、可靠（来源与口径可信）。\n【辨析】速度快是效率指标，不是采集环节的原则要求，故 D 不选。","k":"yewu"},
{"id":489,"m":"练习二","t":"多选","q":"以下哪些是数据格式（）。","o":["SV","XML","JSON","SQL"],"a":[0,1,2],"e":"【考点】数据格式\n【答案】ABC\n【解析】CSV、XML、JSON 都是文件/数据交换格式，各有适用场景。\n【辨析】SQL 是查询语言而不是数据格式，故 D 不选。","k":"jichu"},
{"id":490,"m":"练习二","t":"多选","q":"在数据采集过程中，以下哪一项可以保证数据质量（）.","o":["确认数据来源","确认数据格式","去除重复数据","数据加密"],"a":[0,1,2],"e":"【考点】保障数据质量的做法\n【答案】ABC\n【解析】确认数据来源可靠、确认格式规范、去除重复数据，都是从采集端保证质量的有效动作。\n【辨析】数据加密保护的是保密性，不提升数据本身的准确性，故 D 不选。","k":"yewu"},
{"id":491,"m":"练习二","t":"多选","q":"职业道德的特征主要表现为：一定的强制性、利益的相关性、0","o":["鲜明的行业性","范围的有限性","相对的稳定性","形式的多样性"],"a":[0,1,2,3],"e":"【考点】职业道德的特征\n【答案】ABCD\n【解析】职业道德具有鲜明的行业性、范围的有限性、相对的稳定性、形式的多样性，还带有一定强制性与利益相关性。\n【辨析】四项均为其基本特征。","k":"peixun"},
{"id":492,"m":"练习二","t":"多选","q":"在企业中，激发团队合作意识是一个推动持续发展的原动力，因为这使得员工们更加有0","o":["使命感","情感","责任感","艺术感"],"a":[0,2],"e":"【考点】团队激励的作用\n【答案】AC\n【解析】激发合作意识能让员工产生使命感与责任感，愿意为共同目标投入，这是持续发展的动力。\n【辨析】情感、艺术感不是职业动力的核心表述，故 B、D 不选。","k":"peixun"},
{"id":493,"m":"练习二","t":"多选","q":"职业道德行为的评价可以根据评价主体的不同分为三种类型，分别为0","o":["社会评价","集体评价","自我评价","对手评价"],"a":[0,1,2],"e":"【考点】职业道德评价的类型\n【答案】ABC\n【解析】按评价主体分为社会评价、集体（组织）评价、自我评价三类，分别对应外部舆论、单位考核与自我反省。\n【辨析】对手评价不是职业道德评价的标准类型，故 D 不选。","k":"peixun"},
{"id":495,"m":"练习二","t":"多选","q":"生产经营单位须时常0安全设备，定期检查以确保其能正常运作。","o":["维护","更换","保养","转移"],"a":[0,2],"e":"【考点】安全设备的日常管理\n【答案】AC\n【解析】安全生产要求对安全设备经常维护、定期保养，确保其处于可用状态。\n【辨析】更换是在失效后才做，转移与安全维护无关，故 B、D 不选。","k":"jichu"},
{"id":496,"m":"练习二","t":"多选","q":"计算机的主机由多个部分组成，其中包括（）。","o":["显示器","主板","内存","显卡"],"a":[1,2,3],"e":"【考点】计算机主机的组成\n【答案】BCD\n【解析】主机箱内包含主板、CPU、内存、显卡、硬盘、电源等，是运算与存储的核心。\n【辨析】显示器属外部输出设备，不属于主机，故 A 不选。","k":"jichu"},
{"id":497,"m":"练习二","t":"多选","q":"以下选项哪些是操作系统（）。","o":["WindowsXp","Unix","Linux","PhotoShop"],"a":[0,1,2],"e":"【考点】操作系统\n【答案】ABC\n【解析】Windows XP、Unix、Linux 都是操作系统，负责管理硬件与提供运行环境。\n【辨析】PhotoShop 是图像处理应用软件，故 D 不选。","k":"jichu"},
{"id":498,"m":"练习二","t":"多选","q":"主要影响信息安全的方面包括（）。","o":["技术因素","自然因素","环境因素","人为因素"],"a":[0,2,3],"e":"【考点】影响信息安全的因素\n【答案】ACD\n【解析】信息安全受技术因素（漏洞、加密强度）、环境因素（机房、电力、灾害）、人为因素（误操作、攻击、泄露）影响。\n【辨析】自然因素通常并入环境因素表述，题库未将其单列，故 B 不选。","k":"jichu"},
{"id":499,"m":"练习二","t":"多选","q":"（）是常见的数据库管理系统。","o":["Excel","ccess","SQLServer","VisualFoxPro"],"a":[1,2,3],"e":"【考点】数据库管理系统\n【答案】BCD\n【解析】Access、SQL Server、Visual FoxPro 都是数据库管理系统（DBMS），能建库、建表、执行 SQL、管权限。\n【辨析】Excel 是电子表格软件，不具备 DBMS 的并发控制与事务能力，故 A 不选。","k":"jichu"},
{"id":500,"m":"练习二","t":"多选","q":"Windows优化大师是一个工具软件，能够帮助用户检提供0等功能。","o":["系统检测","系统优化","系统清理","系统维护"],"a":[0,1,2,3],"e":"【考点】Windows 优化大师的功能\n【答案】ABCD\n【解析】这类系统工具提供系统检测（看硬件与状态）、优化（启动项与注册表）、清理（垃圾文件）、维护（驱动与修复）等功能。\n【辨析】四项正是此类工具的标准功能集合。","k":"jichu"},
{"id":501,"m":"练习二","t":"多选","q":"计算机的显著特点包括（）.A运算速度快","o":["计算精度高","存储功能强","具有逻辑判断能力","E在程序控制下自动进行处理"],"a":[0,1,2,3],"e":"【考点】计算机的特点\n【答案】ABCD\n【解析】计算机具有运算速度快、计算精度高、存储能力强、具备逻辑判断能力、可在程序控制下自动处理等特点。\n【辨析】五项（含题干给出的运算速度快）共同构成计算机的基本特征。","k":"jichu"},
{"id":502,"m":"练习二","t":"多选","q":"计算机根据物理器件的不同类型进行分类，包括（）.","o":["电子管","晶体管","中、小规模集成电路","大规模、超大规模集成电路"],"a":[0,1,2,3],"e":"【考点】计算机分代\n【答案】ABCD\n【解析】按物理器件分为电子管、晶体管、中小规模集成电路、大规模与超大规模集成电路四代。\n【辨析】四代对应计算机发展的四个阶段。","k":"jichu"},
{"id":503,"m":"练习二","t":"多选","q":"计算机病毒的特点包括具有（）。","o":["传染性","隐蔽性","潜伏性","破坏性"],"a":[0,1,2,3],"e":"【考点】计算机病毒的特征\n【答案】ABCD\n【解析】病毒具有传染性（自我复制传播）、隐蔽性（不易察觉）、潜伏性（到期触发）、破坏性（损坏数据与系统）。\n【辨析】四项是病毒定义的必备特征。","k":"xunlian"},
{"id":504,"m":"练习二","t":"多选","q":"在IE浏览器中，可以通过管理\"收藏夹“功能来实现对文件夹的0等各种管理操作。","o":["创建文件夹","重命名","删除","移动"],"a":[0,1,2,3],"e":"【考点】IE 收藏夹管理\n【答案】ABCD\n【解析】IE 的收藏夹支持创建文件夹、重命名、删除、移动等整理操作，用于分类管理常用网址。\n【辨析】四项都是收藏夹的标准管理动作。","k":"jichu"},
{"id":505,"m":"练习二","t":"多选","q":"（）是最常被使用的搜索引学。","o":["百度","Google","QQ","163"],"a":[0,1],"e":"【考点】常用搜索引擎\n【答案】AB\n【解析】百度与 Google 是全球范围内最常被使用的通用搜索引擎。\n【辨析】QQ 是即时通讯，163 是门户网站/邮箱，都不是搜索引擎，故 C、D 不选。","k":"jichu"},
{"id":506,"m":"练习二","t":"多选","q":"多媒体软件分为0，根据不同的信息类型进行处理。","o":["声音处理软件","图形图像处理软件","视频处理软件","表格处理软件"],"a":[0,1,2],"e":"【考点】多媒体软件分类\n【答案】ABC\n【解析】多媒体软件按处理的信息类型分为声音处理、图形图像处理、视频处理等软件。\n【辨析】表格处理软件属办公软件，不处理多媒体素材，故 D 不选。","k":"jichu"},
{"id":507,"m":"练习二","t":"多选","q":"常见的图像文件有（）。","o":["jpg","bmp","wps","mp3"],"a":[0,1],"e":"【考点】图像文件格式\n【答案】AB\n【解析】jpg 与 bmp 都是图像文件格式，前者压缩、后者位图无损。\n【辨析】wps 是办公文档格式，mp3 是音频格式，故 C、D 不选。","k":"jichu"},
{"id":508,"m":"练习二","t":"多选","q":"根据《劳动法》，旁劳动者0，用人单位就有权终止劳动合同。","o":["在试用期间被证明不符合录用条件的","不服从用人单位领导不合理的工作安排","严重违反用人单位的规章制度的","劳动者违反竟业限制约定"],"a":[0,2],"e":"【考点】《劳动法》解除合同情形\n【答案】AC\n【解析】试用期被证明不符合录用条件、严重违反规章制度，都是用人单位可依法解除劳动合同的法定情形。\n【辨析】不服从“不合理”安排不能作为解除依据（安排是否合理需另判），违反竞业限制属违约赔偿而非当然解除，故 B、D 不选。","k":"jichu"},
{"id":509,"m":"练习二","t":"多选","q":"以下哪些数据采集方法适合处理海量数据0","o":["传统的关系型数据库","分布式数据库","数据仓库","非关系型数据库"],"a":[1,2,3],"e":"【考点】海量数据采集的载体\n【答案】BCD\n【解析】分布式数据库、数据仓库、非关系型数据库都能横向扩展、支撑海量并发写入与查询。\n【辨析】传统关系型数据库单机扩展能力有限，难以承载海量数据，故 A 不选。","k":"yewu"},
{"id":510,"m":"练习二","t":"多选","q":"下列哪些是合法的数据采集方式（）。","o":["无需征得用户同意，直接获取用户数据","通过分析公共数据的方式获取数据","征得用户同意后，获取用户数据","从竞争对手手中直接获取数据"],"a":[1,2],"e":"【考点】合法的数据采集方式\n【答案】BC\n【解析】分析公开数据、征得用户同意后采集，都是合法合规的路径。\n【辨析】未经同意直接获取侵犯知情权与隐私，从竞争对手处直接获取可能涉及不正当竞争与商业秘密侵权，故 A、D 不选。","k":"yewu"},
{"id":511,"m":"练习二","t":"多选","q":"根据《合同法》，广告指在报纸、0等媒介上发布的，目的在于推销和宣传商品或服务的一种行为。","o":["杂志","广播","电视","互联网"],"a":[0,1,2,3],"e":"【考点】广告媒介\n【答案】ABCD\n【解析】广告可通过报纸、杂志、广播、电视、互联网等媒介发布，凡向公众传播商品或服务信息的行为都属广告。\n【辨析】四项均为法定列举的广告媒介。","k":"jichu"},
{"id":512,"m":"练习二","t":"多选","q":"《网络安全法》指出，网络运营者必须建立网络信息0等信息，及时受理和处理有关网络信息安全方面的投诉和举报。","o":["安全投诉","举报制度","公布投诉","举报方式"],"a":[0,1,2,3],"e":"【考点】网络运营者的义务\n【答案】ABCD\n【解析】《网络安全法》要求网络运营者建立网络安全投诉举报制度，公布投诉举报方式并及时受理处理。\n【辨析】四项分别对应“建立制度、公布渠道、受理、处理”的完整要求。","k":"jichu"},
{"id":513,"m":"练习二","t":"多选","q":"根据《知识产权法》，在电视台播放他人制作的电影、电视节目和录像时，必须先获0和0的授权，并支付相应的费用。","o":["电影、电视制片者","表演者","录像制作者","原播放该录像制品的电视台"],"a":[0,2],"e":"【考点】播放他人影视作品的授权\n【答案】AC\n【解析】电视台播放他人电影、电视节目和录像，须取得制片者与录像制作者的授权并付费。\n【辨析】表演者权在制片时已处理，原播放电视台不是该作品的著作权人，故 B、D 不选。","k":"jichu"},
{"id":514,"m":"练习二","t":"多选","q":"根据《计算机软件保护条例》的规定，0等都属于侵权行为，对此侵权者必须根据事实情况承担相应的民事责任，包括但不限于停止侵权、消除不良影响、道款赔礼、赔偿损失等。","o":["未经软件著作权人许可，发表或者登记其软件的","将他人软件作为自己的软件发表或者登记的","在他人软件上署名或者更改他人软件上的署名的","其他侵犯软件著作权的行为"],"a":[0,1,2,3],"e":"【考点】软件著作权侵权行为\n【答案】ABCD\n【解析】未经许可发表或登记他人软件、把他人软件当自己的发表登记、在他人软件上署名或改署名，以及其他侵权行为，都要承担停止侵害、赔礼道歉、赔偿损失等民事责任。\n【辨析】前三项是典型侵权，第四项是兜底条款。","k":"jichu"},
{"id":515,"m":"练习二","t":"多选","q":"ETL数据整合工具的主要功能包括O。","o":["数据抽取(E)","数据转换(T)","数据加载(L)","数据备份"],"a":[0,1,2],"e":"【考点】ETL 三大功能\n【答案】ABC\n【解析】ETL 由抽取（Extract）、转换（Transform）、加载（Load）三环节构成，这是其名称来源。\n【辨析】数据备份属运维保障，不是 ETL 的核心功能，故 D 不选。","k":"yewu"},
{"id":516,"m":"练习二","t":"多选","q":"主要从以下O方面来衡量ETL技术选型，","o":["，成本","人员","相关案例","技术支持"],"a":[0,1,2,3],"e":"【考点】ETL 选型维度\n【答案】ABCD\n【解析】选 ETL 工具要从成本、人员（是否有会用的团队）、相关案例（同行业落地经验）、技术支持（厂商服务能力）四方面衡量。\n【辨析】四项分别对应钱、人、经验、服务。","k":"yewu"},
{"id":517,"m":"练习二","t":"多选","q":".ETL数据整合的功能包括（）。","o":["业务需求","数据评估","数据集成","最终用户提交界面"],"a":[0,1,2,3],"e":"【考点】ETL 数据整合的环节\n【答案】ABCD\n【解析】ETL 项目要覆盖业务需求梳理、数据评估（质量与可用性）、数据集成实施、最终用户提交界面（结果交付与查询）。\n【辨析】四项构成从需求到交付的完整链条。","k":"yewu"},
{"id":518,"m":"练习二","t":"多选","q":"ETL数据整合工具的关键技术包括O。数据清洗","o":["数据去重","数据转换","数据加载","数据清空"],"a":[0,1,2,3],"e":"【考点】ETL 关键技术\n【答案】ABCD\n【解析】题库把数据清洗、去重、转换、加载以及加载前的目标表数据清空都列为 ETL 关键技术：清空旧数据可避免重复写入造成的数据翻倍。\n【辨析】四项均在 ETL 实施中出现，故选全。","k":"yewu"},
{"id":519,"m":"练习二","t":"多选","q":"（）是数据增晕抽取的模式。","o":["触发器模式","时间戳方式","全表对比方式","日志对比方式"],"a":[0,1,2,3],"e":"【考点】增量抽取的模式\n【答案】ABCD\n【解析】增量抽取常用触发器（源库打标记）、时间戳（按更新时间拉取）、全表对比（比对差异）、日志对比（解析数据库日志）四种模式。\n【辨析】四项分别适用不同源库能力与数据量场景。","k":"jichu"},
{"id":521,"m":"练习二","t":"多选","q":"当出现错误时，处理数据的方法可以包括0","o":["删除错误数据","错误数据替换","分离对待","不做任何处理"],"a":[0,1,2],"e":"【考点】错误数据的处理方式\n【答案】ABC\n【解析】发现错误数据可以删除（确认无效）、替换（用正确值覆盖）、分离对待（单独存疑待人工复核）。\n【辨析】不做任何处理会让错误流入下游，故 D 不选。","k":"jichu"},
{"id":522,"m":"练习二","t":"多选","q":"在样本规约过程中，确定子集大小时需要考虑0以及其他与算法和数据特性相关的因素。","o":["计算成本","存储要求","估计量的精度","估计量的范围"],"a":[0,1,2],"e":"【考点】样本规约的子集大小\n【答案】ABC\n【解析】确定抽样规模要权衡计算成本、存储要求、估计量精度三者：抽样越少越省，但精度越低。\n【辨析】估计量的范围不是确定规模的依据，故 D 不选。","k":"xunlian"},
{"id":523,"m":"练习二","t":"多选","q":"有参特征值的归约方法，其中包括0和（）模型。","o":["回归","直方图","对数线性模型","选择"],"a":[0,2],"e":"【考点】有参特征规约方法\n【答案】AC\n【解析】用参数模型描述数据以实现规约的有回归（用拟合函数替代数据）与对数线性模型（用低阶分布近似多维数据）。\n【辨析】直方图属无参方法，选择不是模型，故 B、D 不选。","k":"xunlian"},
{"id":524,"m":"练习二","t":"多选","q":"（）函数是纵向数据抽取中最常用的函数","o":["splitO","slice0","splice0","concato"],"a":[0,1],"e":"【考点】纵向数据抽取函数\n【答案】AB\n【解析】纵向（按列）切分数据常用 split（拆分）与 slice（切片）两个函数，按列索引取子集。\n【辨析】splice 是拼接，concat 是横向合并，故 C、D 不选。","k":"yewu"},
{"id":525,"m":"练习二","t":"多选","q":"要使用决策树方法，需要具备（）要素。具有决策者期望达到的明确目标","o":["存在决策者可以选择的两个以上的可行备选方案","存在着决策者无法控制的两种以上的自然状态（如气候变化、市场行情、经济发展动向等)","不同行动方案在不同自然状态下的收益值或损失值可以计算出来","决策者能估计出不同的自然状态发生概"],"a":[0,1,2,3],"e":"【考点】决策树方法的要素\n【答案】ABCD\n【解析】用决策树做决策需具备：明确目标、两个以上可行方案、两种以上不可控自然状态、各方案在各状态下的损益可计算、各状态概率可估计。\n【辨析】五项（含题干给出的明确目标）构成决策树分析的完整前提。","k":"xunlian"},
{"id":526,"m":"练习二","t":"多选","q":"相比于传统的数据采集方法，分布式数据库采用更先进的方法进行数据采集，具备0的特点。","o":["具有更高的数据访问速度","具有更强的可扩展性","更多的资源消耗","更高的并发访问量"],"a":[0,1,3],"e":"【考点】分布式数据库采集的优势\n【答案】ABD\n【解析】分布式数据库并行读写，具有更高的数据访问速度、更强的可扩展性、更高的并发访问量。\n【辨析】更多资源消耗是代价而非特点，故 C 不选。","k":"yewu"},
{"id":527,"m":"练习二","t":"多选","q":"数据清洗的主要目的是（）。","o":["数据格式标准化","异常数据清理","数据错误纠正","重复数据的清除"],"a":[0,1,2,3],"e":"【考点】数据清洗的目的\n【答案】ABCD\n【解析】数据清洗要做到格式标准化、异常值清理、错误纠正、重复数据清除，四者构成完整清洗。\n【辨析】四项分别对应格式、异常、错误、重复四类问题。","k":"yewu"},
{"id":528,"m":"练习二","t":"多选","q":"业务流程可以根据活动内容的不同被细分为0三种类型。","o":["多结构化业务流程","完全结构化业务流程","半结构化业务流程","非结构化业务流程"],"a":[1,2,3],"e":"【考点】业务流程的类型\n【答案】BCD\n【解析】按结构化程度分为完全结构化（规则明确、可自动化）、半结构化（部分规则）、非结构化（依赖人的判断）。\n【辨析】多结构化不是标准分类，故 A 不选。","k":"jichu"},
{"id":529,"m":"练习二","t":"多选","q":"以下哪种算法可以用来解决分类问题！","o":["支持向量机","：K均值算法","线性回归","K最近邻算法"],"a":[0,1,3],"e":"【考点】分类算法\n【答案】ABD\n【解析】支持向量机、K 最近邻都能做分类；K 均值是聚类（题库把它列入可用算法，用于无监督分类场景）。\n【辨析】线性回归输出连续值，不能做分类，故 C 不选。","k":"xunlian"},
{"id":530,"m":"练习二","t":"多选","q":"在AI系统运维中，以下哪些指标可以用来衡量系统的性能（）。","o":["CPU占用率和内存使用率","性能分析器报告","服务器的IP地址","硬盘剩余空间"],"a":[0,1],"e":"【考点】衡量系统性能的指标\n【答案】AB\n【解析】CPU 占用率与内存使用率、性能分析器报告都直接反映系统运行性能。\n【辨析】IP 地址是网络标识，硬盘剩余空间是容量指标，都不直接衡量性能，故 C、D 不选。","k":"yunwei"},
{"id":531,"m":"练习二","t":"多选","q":"在数据采集中，以下0问题可能会导致数据质量不","o":["数据缺失","数据格式错误","数据重复","数据模糊"],"a":[0,1,2,3],"e":"【考点】影响数据质量的问题\n【答案】ABCD\n【解析】数据缺失（不完整）、格式错误（不规范）、重复（冗余）、模糊（不清晰）都会降低数据质量。\n【辨析】四类问题都会在采集环节引入，需要清洗处理。","k":"yewu"},
{"id":532,"m":"练习二","t":"多选","q":"数据采集过程中涉及到的主要数据类型包括（）.","o":["数字数据","文本数据","图像数据","视频数据"],"a":[0,1,2,3],"e":"【考点】主要数据类型\n【答案】ABCD\n【解析】采集涉及数字（结构化）、文本、图像、视频（含音频）等多种数据类型，不同类型处理方式不同。\n【辨析】四项覆盖结构化与非结构化数据的主要形态。","k":"yewu"},
{"id":533,"m":"练习二","t":"多选","q":"哪些属于云计算的特点0","o":["弹性扩展","快速部署","易上手","所有选项都是"],"a":[0,1],"e":"【考点】云计算的特点\n【答案】AB\n【解析】云计算的核心特点是弹性扩展（按需扩缩容）与快速部署（资源分钟级就绪）。\n【辨析】易上手不是云计算的技术特征，故 C、D 不选。","k":"jichu"},
{"id":534,"m":"练习二","t":"多选","q":"数据获取中的几个技术关键点包括哪些（）。","o":["目标判断与分析","数据获取与清洗","数据转换与存储","数据分析与应用"],"a":[0,1,2],"e":"【考点】数据获取的技术关键点\n【答案】ABC\n【解析】数据获取的关键在手：明确目标并分析需求、实际获取并清洗、转换与存储落地。\n【辨析】数据分析与应用属于获取之后的下游环节，故 D 不选。","k":"xunlian"},
{"id":535,"m":"练习二","t":"多选","q":"Harrington将业务流程管理分为（）。A理解流程","o":["梳理流程","执行流程","测量与控制流程","E持续改进流程"],"a":[0,1,2,3],"e":"【考点】Harrington 的流程管理划分\n【答案】ABCD\n【解析】Harrington 把业务流程管理分为理解流程、梳理流程、执行流程、测量与控制流程、持续改进流程五个阶段。\n【辨析】五项（含题干的理解流程）构成闭环。","k":"jichu"},
{"id":536,"m":"练习二","t":"多选","q":"要进行数据的质量检查，可以使用0的方法。","o":["普查","排查","抽查","检查"],"a":[1,2],"e":"【考点】数据质量检查方法\n【答案】BC\n【解析】质量检查常用排查（定向核查疑点）与抽查（抽样检验）两种方式，兼顾效率与覆盖。\n【辨析】普查成本过高、不适合常规质量检查，检查是泛称，故 A、D 不选。","k":"yewu"},
{"id":537,"m":"练习二","t":"多选","q":"医疗行业通过0等应用，结合机器学习技术，快速实现医学编码和注释。","o":["人体标框","3D画框","骨骼点标记","病历转录"],"a":[0,1,2,3],"e":"【考点】医疗领域的标注形式\n【答案】ABCD\n【解析】医疗数据标注包括人体标框、3D 画框、骨骼点标记、病历转录等，配合机器学习实现医学编码与注释。\n【辨析】四项覆盖影像、三维、姿态、文本四类医疗数据。","k":"xunlian"},
{"id":538,"m":"练习二","t":"多选","q":"（）是常用的标注团队。","o":["统一管理的标注生产团队","众包团队","校企团队","私人团队"],"a":[0,1,2],"e":"【考点】常见标注团队形态\n【答案】ABC\n【解析】标注团队常见有统一管理的标注生产团队、众包团队、校企合作团队三种组织形式。\n【辨析】私人团队不是行业标准形态，故 D 不选。","k":"peixun"},
{"id":539,"m":"练习二","t":"多选","q":"一个包含数据标注的项目，可以运用项目管理知识按照0的步骤进行全流程管理。启动","o":["规划","执行","监控","收尾"],"a":[0,1,2,3],"e":"【考点】项目管理的五大过程组\n【答案】ABCD\n【解析】数据标注项目按项目管理知识体系走启动、规划、执行、监控、收尾五个过程组，形成全流程管理。\n【辨析】五项（含题干的启动）构成项目全生命周期。","k":"yewu"},
{"id":540,"m":"练习二","t":"多选","q":"数据标准化处理主要涉及两个方面，分别是（）。","o":["最优化处理","数据同趋化处理","无量纲化处理","数据最大量处理"],"a":[1,2],"e":"【考点】数据标准化的两个方面\n【答案】BC\n【解析】标准化包含数据同趋化处理（把不同方向的指标转为同向可比）与无量纲化处理（消除单位与量纲影响）。\n【辨析】最优化、最大量处理都不是标准化的组成，故 A、D 不选。","k":"jichu"},
{"id":541,"m":"练习二","t":"多选","q":"数据规约是一种数据预处理技术，常见的方法包括（）.A样本归约","o":["数据采样","属性选择","特征归约","E特征值归约"],"a":[1,2],"e":"【考点】数据规约的常见方法\n【答案】BC\n【解析】属性选择（挑出关键属性）与特征归约（用更少的特征表达原信息）是两类典型规约方法，前者减少列、后者压缩特征。\n【辨析】数据采样属样本规约，题干已单列，故 A、D 不选。","k":"yewu"},
{"id":542,"m":"练习二","t":"多选","q":"实时的数据标注质量检验方法具有多个优点，包括（）.能够及时发现问题并解决问题","o":["能够有效减少标注过程中重复错误的重复出现","对于人员的配备及管理要求较高","能够保证整体标注任务的流畅性","能够实时掌握数据标准的任务进度"],"a":[0,1,3],"e":"【考点】实时质检的优点\n【答案】ABD\n【解析】实时质检能及时发现并纠正问题、减少同类错误反复出现、实时掌握任务进度并保证流程顺畅。\n【辨析】对人员配备与管理要求高是它的缺点，故 C 不选。","k":"peixun"},
{"id":543,"m":"练习二","t":"多选","q":"图像标注常用的方式包括0标框标注","o":["区域标注","语音标注","视频标注","EAB"],"a":[0,1],"e":"【考点】图像标注的方式\n【答案】AB\n【解析】图像标注常用标框（矩形框）与区域标注（多边形/掩码）两种方式，前者用于检测、后者用于分割。\n【辨析】语音标注、视频标注处理的是其他模态数据，故 C、D 不选。","k":"xunlian"},
{"id":544,"m":"练习二","t":"多选","q":"对人脸数据进行标注通常包括（）。","o":["人脸位置标框标注","特征点描点标注","分类标注","关系标注"],"a":[0,1],"e":"【考点】人脸数据标注\n【答案】AB\n【解析】人脸标注主要是位置标框（确定人脸区域）与特征点描点（标出五官关键点），前者用于检测、后者用于对齐与识别。\n【辨析】分类标注、关系标注不针对人脸几何结构，故 C、D 不选。","k":"xunlian"},
{"id":545,"m":"练习二","t":"多选","q":"常用的文件扩展名，用于存储图像数据的标注结果其中包括（）。","o":["TXT","JSON","EXE","XML"],"a":[1,3],"e":"【考点】标注结果的存储格式\n【答案】BD\n【解析】图像标注结果常用 JSON（COCO 风格）与 XML（PASCAL VOC 风格）保存框坐标与类别。\n【辨析】TXT 虽也能存，但不是标准标注格式；EXE 是可执行程序，故 A、C 不选。","k":"xunlian"},
{"id":546,"m":"练习二","t":"多选","q":"Python提供了多个数据合并的函数，包括（）。","o":["concato","merge0","joino","appendo"],"a":[0,1,2,3],"e":"【考点】Python 数据合并函数\n【答案】ABCD\n【解析】concat 纵向/横向拼接，merge 按键关联（类似 SQL join），join 按索引合并，append 追加行，都是 pandas 的合并手段。\n【辨析】四个函数分别适用于不同合并场景。","k":"jichu"},
{"id":547,"m":"练习二","t":"多选","q":"下列选项中0是导致数据不完整的原因。","o":["数据收集工具的问题","数据源不同所致","数据输入","传输错误"],"a":[0,2,3],"e":"【考点】数据不完整的原因\n【答案】ACD\n【解析】采集工具缺陷（漏采）、录入错误（人为遗漏）、传输错误（丢包截断）都会造成数据不完整。\n【辨析】数据源不同只是差异，不必然导致缺失，故 B 不选。","k":"jichu"},
{"id":548,"m":"练习二","t":"多选","q":"在错误识别阶段，利用0等技术，自动检测数据居性中的错误。","o":["统计","聚类","关联规则","随机抽取"],"a":[0,1,2],"e":"【考点】错误自动检测技术\n【答案】ABC\n【解析】用统计方法找离群值、用聚类找不合群的记录、用关联规则找违反业务约束的组合，都能自动识别数据错误。\n【辨析】随机抽取只是取样手段，不检测错误，故 D 不选。","k":"jichu"},
{"id":549,"m":"练习二","t":"多选","q":"人工智能数据采集中使用的传感器有哪些（）。","o":["温度传感器","湿度传感器","压力传感器","微波雷达"],"a":[0,1,2,3],"e":"【考点】AI 数据采集的传感器\n【答案】ABCD\n【解析】温度、湿度、压力传感器采集环境与工况数据，微波雷达采集距离与运动目标数据，都是 AI 数据采集的常用传感器。\n【辨析】四项分别对应环境量、物理量与雷达感知。","k":"yewu"},
{"id":550,"m":"练习二","t":"多选","q":"人工智能的研究和应用是跨学科的，下面哪一项可以与人工智能相结合（）。","o":["心理学","化学","地理","经济学"],"a":[0,3],"e":"【考点】AI 的跨学科结合\n【答案】AD\n【解析】人工智能与心理学结合可研究认知与情感计算，与经济学结合可做量化决策与市场预测，这两条是最成熟的交叉方向。\n【辨析】化学、地理虽也能用 AI 做数据分析，但题库设定的跨学科结合对象是心理学与经济学，故 B、C 不选。","k":"jichu"},
{"id":551,"m":"练习二","t":"多选","q":"人工智能的优点和缺点都包含哪些方面0","o":["提高效率和降低成本","需要大量的训练数据和标注","更好地懂得情境和语义","可能引发就业变化和道德问题"],"a":[0,1,2,3],"e":"【考点】AI 的优缺点\n【答案】ABCD\n【解析】优点：提高效率、降低成本，更好理解情境与语义；缺点：依赖大量训练数据与标注，可能带来就业结构变化与伦理道德争议。\n【辨析】四项分别对应两条优点、两条缺点。","k":"jichu"},
{"id":552,"m":"练习二","t":"多选","q":"人工智能技术在教育领域的应用可以实现哪些方面的改进0","o":["个性化教育","智能化教学管理","智能化评价与考核","智能化学习资源管理"],"a":[0,1,2,3],"e":"【考点】AI 在教育领域的改进\n【答案】ABCD\n【解析】AI 可支撑个性化教育、智能化教学管理、智能化评价考核、智能化学习资源管理，覆盖教、管、评、资四环节。\n【辨析】四项都是智慧教育的标准组成。","k":"jichu"},
{"id":553,"m":"练习二","t":"多选","q":"人工智能的发展给人类带来了哪些影响（）。","o":["缓解了经济压力","提高了生活质量","加速了工业化进程","增加了社会不平等"],"a":[1,3],"e":"【考点】AI 的社会影响\n【答案】BD\n【解析】AI 一方面提高生活质量（便利、医疗、服务），另一方面可能加剧社会不平等（技能鸿沟、岗位替代）。\n【辨析】缓解经济压力、加速工业化不是 AI 带来的直接普遍影响，故 A、C 不选。","k":"jichu"},
{"id":554,"m":"练习二","t":"多选","q":"人工智能在医疗领域的应用可以实现哪些方面的改进（）。","o":["加强疾病预防和控制","提高医疗服务效率和准确性","减少医疗费用和用药成本","缓解医疗资源短缺问题"],"a":[0,1,2,3],"e":"【考点】AI 在医疗领域的改进\n【答案】ABCD\n【解析】AI 可加强疾病预防控制、提高服务效率与准确性、降低费用与用药成本、缓解医疗资源短缺。\n【辨析】四项覆盖预防、诊疗、成本、资源四个维度。","k":"jichu"},
{"id":555,"m":"练习二","t":"多选","q":"人工智能的发展与隐私保护之间存在哪些关系0","o":["人工智能会增加隐私泄露的风险","人工智能可以增强隐私保护的效果","隐私保护与人工智能发展没有关联","人工智能对隐私保护无影响"],"a":[0,1],"e":"【考点】AI 与隐私的关系\n【答案】AB\n【解析】AI 是双刃剑：大规模采集数据会增加泄露与滥用风险；同时联邦学习、差分隐私等技术又能增强隐私保护。\n【辨析】C、D 否认二者关联，与事实相反。","k":"jichu"},
{"id":556,"m":"练习二","t":"多选","q":"（）是处理重复数据的常用方法","o":["合并","留存","拷贝","消除"],"a":[0,3],"e":"【考点】重复数据的处理\n【答案】AD\n【解析】处理重复数据可合并（多条折成一条、保留完整信息）或直接消除（删除冗余副本）。\n【辨析】留存与拷贝会让重复问题更严重，故 B、C 不选。","k":"jichu"},
{"id":557,"m":"练习二","t":"多选","q":"语音分割标注可分为0几种方式。","o":["有效片段分割","无效片段分割","主说话人语音分割","起止时间段分割"],"a":[0,1,2,3],"e":"【考点】语音分割标注的方式\n【答案】ABCD\n【解析】语音分割可按有效片段、无效片段、主说话人、起止时间段四种口径切分，分别服务于识别、降噪、说话人分离与对齐。\n【辨析】四项对应四类切分需求。","k":"xunlian"},
{"id":558,"m":"练习二","t":"多选","q":"（）是最常使用文本标注应用的行业。","o":["安防行业","客服行业","金融行业","医疗行业"],"a":[1,2,3],"e":"【考点】文本标注的主要行业\n【答案】BCD\n【解析】客服（意图识别、对话质检）、金融（合同与舆情分析）、医疗（病历实体抽取）是文本标注需求最集中的行业。\n【辨析】安防行业以图像与视频标注为主，故 A 不选。","k":"xunlian"},
{"id":559,"m":"练习二","t":"多选","q":"语义分割是一种应用0等技术的方法，它能够将一幅图像分割成多个区域，每个区域能够被赋予一个具有语义含义的标签。","o":["图像分类","目标检测","图像分割","声纹识别"],"a":[0,1,2],"e":"【考点】语义分割的技术基础\n【答案】ABC\n【解析】语义分割融合图像分类（判断类别）、目标检测（定位目标）与图像分割（划分区域）三类技术，做到逐像素赋标签。\n【辨析】声纹识别处理语音，与图像分割无关，故 D 不选。","k":"xunlian"},
{"id":560,"m":"练习二","t":"多选","q":"文本标注主要包含（）类型。","o":["音泰标注","序列标注","关系标注","属性标注"],"a":[1,2,3],"e":"【考点】文本标注的类型\n【答案】BCD\n【解析】文本标注主要包括序列标注、关系标注、属性标注三大类，分别对应词级标签、实体关系、对象属性。\n【辨析】音素标注属语音标注，故 A 不选。","k":"xunlian"},
{"id":561,"m":"练习二","t":"多选","q":"测试人工智能模型需要考虑（）。","o":["测试用例","测试方法","测试计划","测试报告"],"a":[0,1,2,3],"e":"【考点】模型测试的要素\n【答案】ABCD\n【解析】测试 AI 模型要准备测试用例、选择测试方法、制定测试计划、输出测试报告，四者构成完整测试闭环。\n【辨析】四项分别对应“测什么、怎么测、何时测、测得怎样”。","k":"yunwei"},
{"id":562,"m":"练习二","t":"多选","q":"测试报告可以分为两种类型，分别是（）.","o":["版本测试报告","总结测试报告","单元测试报告","集成测试报告"],"a":[0,1],"e":"【考点】测试报告的类型\n【答案】AB\n【解析】测试报告按用途分为版本测试报告（针对某一版本）与总结测试报告（针对整个项目/阶段）。\n【辨析】单元测试报告、集成测试报告是按测试阶段划分的，不是报告类型分类，故 C、D 不选。","k":"yunwei"},
{"id":563,"m":"练习二","t":"多选","q":"版本测试报告中的测试过程缺陷统计应当记录相关指标，包括（）。","o":["新建bug数","修复bug数","未修复bug数","bug总数"],"a":[0,1,2,3],"e":"【考点】缺陷统计指标\n【答案】ABCD\n【解析】版本测试报告要记录新建 bug 数、修复 bug 数、未修复 bug 数以及 bug 总数，用于判断质量趋势与收敛情况。\n【辨析】四项共同构成缺陷统计的面貌。","k":"yunwei"},
{"id":564,"m":"练习二","t":"多选","q":"常见的算法模型测试方法包括0","o":["分类算法测试","回归算法测试","聚类算法测试","关联规则算法测试"],"a":[0,1,2],"e":"【考点】常见算法模型测试方法\n【答案】ABC\n【解析】分类、回归、聚类是三类基本算法任务，各有对应的测试方法（准确率、误差、簇质量）。\n【辨析】关联规则测试不在题库所列的常见方法内，故 D 不选。","k":"yunwei"},
{"id":566,"m":"练习二","t":"多选","q":"对于功能测试用例的作用，正确的叙述的是（）。","o":["可以避免测试的盲目性","使得软件测试的实施重点突出、目的明","在回归测试中无需修正测试用例便可继续开展测试工作","可有效地节省时间和资源，提高测试效"],"a":[0,1,3],"e":"【考点】功能测试用例的作用\n【答案】ABD\n【解析】好的用例能避免盲目测试、让实施重点突出目的明确、节省时间资源提高效率。\n【辨析】回归测试中用例往往需要随版本修正，不能说“无需修正”，故 C 不选。","k":"yunwei"},
{"id":567,"m":"练习二","t":"多选","q":"数据可视化的基本特点涵盖（）方面。","o":["易懂性","必然性","片面性","专业性"],"a":[0,1,2,3],"e":"【考点】数据可视化的特点\n【答案】ABCD\n【解析】可视化追求易懂（直观可读）、有其必然性（数据本身决定呈现形式）、存在片面性（视角选择会遮蔽信息）、具备专业性（需遵循图形规范）。\n【辨析】四项都是其固有特点。","k":"sheji"},
{"id":568,"m":"练习二","t":"多选","q":"数据可视化是一种将数据运用集成起来的方法，它包括（）。","o":["数据获取","导出报表","数据处理","可视化模式和可视化应用"],"a":[0,2,3],"e":"【考点】可视化的组成\n【答案】ACD\n【解析】数据可视化包含数据获取、数据处理、可视化模式与应用四环，是完整链路而非单一画图。\n【辨析】导出报表是输出动作，不属于可视化的方法构成，故 B 不选。","k":"yunwei"},
{"id":569,"m":"练习二","t":"多选","q":"（）是属于可视化分析工具。","o":["Excel","Processing","ECharts","PPT"],"a":[0,1,2],"e":"【考点】可视化分析工具\n【答案】ABC\n【解析】Excel（图表功能）、Processing（编程可视化）、ECharts（前端图表库）都能做数据可视化分析。\n【辨析】PPT 是演示工具，虽有图表但不算可视化分析工具，故 D 不选。","k":"sheji"},
{"id":570,"m":"练习二","t":"多选","q":"以下的0情形比较适合使用曲线图。","o":["要表示两个变量之间的函数关系","描述某种现象在时间上的发展趋势","描述各事物之间的数量大小和数量之间的差异情况","描述一种变量随另一种变量变化的情形"],"a":[0,1,3],"e":"【考点】曲线图的适用场景\n【答案】ABD\n【解析】曲线图适合表现两个变量的函数关系、现象随时间的发展趋势、一个变量随另一变量变化的情形。\n【辨析】比较各事物的数量大小与差异适合用条形图，故 C 不选。","k":"jichu"},
{"id":571,"m":"练习二","t":"多选","q":"在进行机器学习时，通常需要对收集到的数据集进行分割，这个过程被称为数据集划分，即将原始数据集分为（）。","o":["训练数据集","验证数据集","测试数据集","评估数据集"],"a":[0,2],"e":"【考点】数据集划分\n【答案】AC\n【解析】标准做法是把原始数据分为训练数据集（学参数）与测试数据集（评估泛化）。\n【辨析】验证集是训练过程中从训练集再切的子集，评估数据集不是标准划分名称，故 B、D 不选。","k":"xunlian"},
{"id":572,"m":"练习二","t":"多选","q":"过拟合的原因可能是由于0导致的。","o":["模型本身过于复杂","模型本身过于简单","训练集样本过多","训练集样本过少"],"a":[0,3],"e":"【考点】过拟合的成因\n【答案】AD\n【解析】过拟合来自两个方向：模型过于复杂（参数太多记住了噪声），或训练样本过少（不足以代表真实分布）。\n【辨析】模型过简导致欠拟合，样本过多是好事，故 B、C 不选。","k":"xunlian"},
{"id":573,"m":"练习二","t":"多选","q":"卷积神经网络由若干基本层组成，包括（）。A.输入层","o":["卷积层","池化层","全连接层","输出层"],"a":[0,1,2,3],"e":"【考点】卷积神经网络的层结构\n【答案】ABCD\n【解析】CNN 由输入层、卷积层、池化层、全连接层、输出层组成，卷积提特征、池化降维、全连接做分类。\n【辨析】五项（含题干的输入层）构成完整网络。","k":"xunlian"},
{"id":574,"m":"练习二","t":"多选","q":"模型复杂度和数据集大小之间存在密切关系，说法正确的是（）.","o":["模型复杂度与训练数据集中输入数据的变化密切相关","数据集中包含的数据点变化范围越大，在不发生拟合情况下，模型就越复杂","更大的数据集可以用来构建更复杂的模","仅复制相同的数据点或收集非常相似的数据对构建复杂模型也有非常大的帮助"],"a":[0,1,2],"e":"【考点】模型复杂度与数据量的关系\n【答案】ABC\n【解析】数据变化范围越大、样本越多样，模型才有必要也更可能变复杂；大数据集能支撑更复杂的模型而不易过拟合。\n【辨析】复制相同数据点或收集高度相似数据没有增加信息量，对复杂模型无帮助，故 D 不选。","k":"xunlian"},
{"id":575,"m":"练习二","t":"多选","q":"以下哪些是处理自然语言(NLP)的基础技术O。","o":["分词","实体识别","情感分析","演绎推理"],"a":[0,1,2],"e":"【考点】NLP 基础技术\n【答案】ABC\n【解析】分词（切词）、实体识别（找实体）、情感分析（判断倾向）都是自然语言处理的基础任务。\n【辨析】演绎推理属逻辑推理范畴，不是 NLP 的基础技术，故 D 不选。","k":"jichu"},
{"id":576,"m":"练习二","t":"多选","q":"以下哪些机器人被用于工业制造（）.","o":["SCARA机器人","清洗机器人","医疗机器人","儿童陪护机器人"],"a":[0,1],"e":"【考点】工业制造机器人\n【答案】AB\n【解析】SCARA 机器人用于装配、搬运等精密作业，清洗机器人用于工业清洗，二者都是产线设备。\n【辨析】医疗机器人、儿童陪护机器人服务于医疗与家庭场景，故 C、D 不选。","k":"jichu"},
{"id":577,"m":"练习二","t":"多选","q":"以下哪些企业是AI领域的领头羊0","o":["亚马逊","谷歌","脸书","全球通"],"a":[0,1,2],"e":"【考点】AI 领域领军企业\n【答案】ABC\n【解析】亚马逊（AWS 与 Alexa）、谷歌（DeepMind、TensorFlow）、脸书（PyTorch、FAIR）都是 AI 技术与生态的领军者。\n【辨析】全球通是通信运营商品牌，不是 AI 企业，故 D 不选。","k":"jichu"},
{"id":578,"m":"练习二","t":"多选","q":"在什么情况下标注师需要调整自己的标注方式和标注准则（）.","o":["数据的特点和需求发生变化","标注师个人的理解和标注方式产生了偏","标注队伍发生了变动，富需要进行统一规范和标准化","数据样本量发生了变动，需要重新评估标注的覆盖率和准确性"],"a":[0,1,2,3],"e":"【考点】标注准则的调整时机\n【答案】ABCD\n【解析】数据特点与需求变化、标注师理解出现偏差、团队人员变动需要统一、样本量变化需重估覆盖率与准确性，都要调整标注方式与准则。\n【辨析】四种情况都会破坏标注一致性，必须及时修订规范。","k":"peixun"},
{"id":579,"m":"练习二","t":"多选","q":"下面哪些是数据标注质量的度晕指标（）。","o":["准确性","一致性","可重复性","覆盖率、质量得分"],"a":[0,1,2,3],"e":"【考点】标注质量度量指标\n【答案】ABCD\n【解析】衡量标注质量看准确性（标得对不对）、一致性（多人标得是否一致）、可重复性（重标是否稳定）、覆盖率与质量得分（覆盖是否充分、综合评分）。\n【辨析】四项构成完整的质量度量体系。","k":"peixun"},
{"id":580,"m":"练习二","t":"多选","q":"标注师需要注意哪些标准来保证标注数据的准确性（）.","o":["数据的上下文和环境","标注的领域和专业知识","标注的对象和居性","标注数据的保密性和安全性"],"a":[0,1,2],"e":"【考点】保证标注准确性的要点\n【答案】ABC\n【解析】标注要结合数据上下文与环境、领域专业知识、标注对象的属性，才能判断准确。\n【辨析】保密性与安全性是合规要求，不属于“准确性”标准，故 D 不选。","k":"peixun"},
{"id":581,"m":"练习二","t":"多选","q":"（）是常用的聚类性能度量外部指标。","o":["Jaccard系数",".FM指数","Rand指数","指数"],"a":[0,1,2],"e":"【考点】聚类外部指标\n【答案】ABC\n【解析】外部指标用真实标签比对聚类结果：Jaccard 系数、FM 指数、Rand 指数都是常用外部度量。\n【辨析】D 项表述残缺、不是标准指标名，故不选。","k":"xunlian"},
{"id":582,"m":"练习二","t":"多选","q":"（）是常用的聚类性能度量内部指标。","o":["DB指数","Rand指数","Dunn指数","FM指数"],"a":[0,2],"e":"【考点】聚类内部指标\n【答案】AC\n【解析】内部指标不看标签、只看簇内紧凑与簇间分离：DB 指数（越小越好）与 Dunn 指数（越大越好）是代表。\n【辨析】Rand 指数、FM 指数属外部指标，故 B、D 不选。","k":"xunlian"},
{"id":583,"m":"练习二","t":"多选","q":"根据数据分析的深度，数据分析可分为（）。","o":["筛选性分析","描述性分析","预测性分析","规则性分析"],"a":[1,2,3],"e":"【考点】数据分析的深度层次\n【答案】BCD\n【解析】按深度分为描述性分析（发生了什么）、预测性分析（可能发生什么）、规则性分析（该怎么做），层层递进。\n【辨析】筛选性分析只是数据操作，不构成分析深度层次，故 A 不选。","k":"yewu"},
{"id":584,"m":"练习二","t":"多选","q":"（）居于基本的数据统计分析方法。","o":["最邻近算法","Kernel算法","PCA算法","图论算法"],"a":[0,1,2,3],"e":"【考点】基本统计分析算法\n【答案】ABCD\n【解析】最邻近、Kernel（核方法）、PCA、图论算法都是数据统计与机器学习的基础算法族。\n【辨析】四类分别对应相似性、核映射、降维、图结构分析。","k":"xunlian"},
{"id":585,"m":"练习二","t":"多选","q":"（）居于线性模型。","o":["决策树","多项式回归","Lasso回归","岭回归"],"a":[1,2,3],"e":"【考点】线性模型\n【答案】BCD\n【解析】多项式回归（线性模型的非线性特征扩展）、Lasso 回归、岭回归都是线性模型或其正则化变体。\n【辨析】决策树是基于规则的树结构模型，不是线性模型，故 A 不选。","k":"xunlian"},
{"id":586,"m":"练习二","t":"多选","q":"对比分析的常用维度包括（）。与目标对比","o":["：不同时期对比","同级同部门、地区对比","行业内对比","E活动效果对比"],"a":[0,1,2,3],"e":"【考点】对比分析的维度\n【答案】ABCD\n【解析】对比可与目标比、不同时期比、同级同部门地区比、行业内比、活动效果比，维度越多结论越立体。\n【辨析】五项（含题干的与目标对比）都是常用维度。","k":"yewu"},
{"id":588,"m":"练习二","t":"多选","q":"某个APP的同一项功能采用AB测试方法进行优化包含的内容有（）。","o":["设计不同的样式风格","只是设计一种页面布局","将不同风格的页面随机分配给使用者","根绝浏览转化率来评估样式优劣"],"a":[0,2,3],"e":"【考点】AB 测试的设计\n【答案】ACD\n【解析】AB 测试要设计不同样式方案、把不同版本随机分配给用户、按转化率等指标评估优劣。\n【辨析】只设计一种页面布局就没有对照，无法比较，故 B 不选。","k":"yunwei"},
{"id":589,"m":"练习二","t":"多选","q":"关于贝叶斯定理针对的可能性函数，说法正确的是（）.","o":["如果可能性函数大于1，意味着先验概率被增强","如果可能性函数小于1，意味着先验概率被增强","如果可能性函数大于1，意味着先验率被削弱","如果可能性函数小于1，意味着先验概率被削弱"],"a":[0,3],"e":"【考点】贝叶斯定理中的可能性函数\n【答案】AD\n【解析】后验 = 先验 × 可能性函数。可能性函数大于 1 会放大先验概率（增强），小于 1 会缩小先验概率（削弱）。\n【辨析】B、C 把大小与增强削弱的对应关系说反了。","k":"xunlian"},
{"id":590,"m":"练习二","t":"多选","q":"关于均值说法，正确的是（）。","o":["均值适用于分类数据","概况一个数值型数据集合的指标","均值就是平均数","容易收到极端值或离群点的影响"],"a":[1,2,3],"e":"【考点】均值的性质\n【答案】BCD\n【解析】均值是数值型数据的概括指标，就是算术平均数，但会受极端值严重影响。\n【辨析】均值不能用于分类数据（类别无法求和平均），故 A 不选。","k":"jichu"},
{"id":591,"m":"练习二","t":"多选","q":"描述性统计分析是一种数据分析方法，主要用于展示数据集合中的一些重要特征，例如（）。","o":["集中趋势","离散程度","频数分布","可行范围"],"a":[0,1,2,3],"e":"【考点】描述性统计的内容\n【答案】ABCD\n【解析】描述性统计展示数据集合的重要特征：集中趋势（均值中位数）、离散程度（方差极差）、频数分布、可行范围。\n【辨析】四项覆盖位置、散布、分布、边界四类特征。","k":"xunlian"},
{"id":592,"m":"练习二","t":"多选","q":"（）是常见的探索性统计分析方法。","o":["时间序列分析","聚类分析","因子分析","对应分析"],"a":[1,2,3],"e":"【考点】探索性统计分析方法\n【答案】BCD\n【解析】聚类分析（找分群）、因子分析（找潜在维度）、对应分析（找类别关联）都是探索未知结构的常用方法。\n【辨析】时间序列分析属预测/推断方向，故 A 不选。","k":"yewu"},
{"id":593,"m":"练习二","t":"多选","q":"（）是常用的推断性统计分析方法。","o":["假设检验","相关分析","回归分析","时间序列分析"],"a":[0,1,2,3],"e":"【考点】推断性统计分析方法\n【答案】ABCD\n【解析】假设检验、相关分析、回归分析、时间序列分析都用于由样本推断总体规律，是推断性统计的标准方法。\n【辨析】四项都涉及参数估计或显著性判断。","k":"yewu"},
{"id":594,"m":"练习二","t":"多选","q":"（）是常见的降维方法","o":["结合分析","回归分析","投影","流形学习"],"a":[2,3],"e":"【考点】降维方法\n【答案】CD\n【解析】投影（把高维数据投到低维子空间，如 PCA）与流形学习（假设数据位于低维流形上）都是降维的典型思路。\n【辨析】结合分析是多属性偏好分析，回归分析是预测建模，故 A、B 不选。","k":"xunlian"},
{"id":595,"m":"练习二","t":"多选","q":"Matplotlib中绘制柱状图时，barO函数可以选择不同的对齐方式，包括（）。","o":["color","center","edge","edgecolor"],"a":[1,2],"e":"【考点】bar 函数的对齐方式\n【答案】BC\n【解析】plt.bar 的 align 参数可取 center（柱中以刻度为中心）或 edge（柱边对齐刻度）。\n【辨析】color、edgecolor 是颜色参数，不是对齐方式，故 A、D 不选。","k":"sheji"},
{"id":596,"m":"练习二","t":"多选","q":"以下选项关于饼图的描述，正确的是（）。","o":["一种用来描述定性数据频数或百分比的图形","通常以园饼或椭园饼的形式出现","饼图的整个圆代表一个总体的全部数据","园中的一个扇形表示总体的全部类型"],"a":[0,1,2],"e":"【考点】饼图的特征\n【答案】ABC\n【解析】饼图描述定性数据的频数或百分比，用圆或椭圆表示，整个圆代表总体全部数据。\n【辨析】一个扇形表示总体中的某一类型，而不是“全部类型”，故 D 错误。","k":"sheji"},
{"id":597,"m":"练习二","t":"多选","q":".如何提高标注数据的准确性（）.","o":["增加数据的样本量","加入更多的专业领域知识和经验","采用多个标注师的标注结果进行比对和调整","提高标注师的工作效率和速度"],"a":[1,2],"e":"【考点】提高标注准确性\n【答案】BC\n【解析】提升准确性靠补充专业领域知识与经验、用多名标注师交叉比对并修正分歧。\n【辨析】单纯加样本量不必然更准，追求速度反而牺牲质量，故 A、D 不选。","k":"xunlian"},
{"id":598,"m":"练习二","t":"多选","q":"标注师应该如何处理标注任务中的异常情况（）。","o":["忽略异常情况直接标注","根据标注的准则进行标注并记录异常情","根据异常情况调整标注的准则和方法","退回任务并重新安排标注师进行处理"],"a":[1,2],"e":"【考点】异常情况的处理\n【答案】BC\n【解析】遇到异常应按准则处理并记录异常，必要时依据异常情况调整准则与方法，并把问题反馈给管理方。\n【辨析】忽略异常会造成错误累积；直接退回重排并不是标注师的职责，故 A、D 不选。","k":"peixun"},
{"id":599,"m":"练习二","t":"多选","q":"在进行图像标注时，需要注意哪些因素0","o":["标注的面积","标注的精度和准确性","标注的一致性和可重复性","标注的目的和任务"],"a":[0,1,2,3],"e":"【考点】图像标注的注意事项\n【答案】ABCD\n【解析】图像标注要控制标注面积（框贴合目标）、保证精度与准确性、保证一致性与可重复性、明确标注目的与任务。\n【辨析】四项分别对应质量、一致性、目标三方面要求。","k":"xunlian"},
{"id":600,"m":"练习二","t":"多选","q":"对于一份需要标注的数据，标注师应该做什么（）。","o":["快速完成标注任务","对数据进行细致的分析和理解","确认数据标注的质量和准确性","不必考虑标注的上下文和环境"],"a":[1,2],"e":"【考点】标注师的工作方式\n【答案】BC\n【解析】拿到数据应先细致分析和理解（看清内容与边界情况），并确认标注质量与准确性，再动手。\n【辨析】一味求快会降低质量，不考虑上下文环境会标错，故 A、D 不选。","k":"peixun"},
{"id":601,"m":"练习二","t":"多选","q":"在标注数据时，标注师应该注意的是（）。","o":["尽量使用简单清晰的语言和术语","：保证标注的一致性和准确性","遵循标准化的标注规范和方法","最大限度地考虑每个样本的内容信息"],"a":[0,1,2],"e":"【考点】标注时的注意点\n【答案】ABC\n【解析】标注要用简单清晰的语言与术语、保证一致性与准确性、遵循标准化的规范与方法。\n【辨析】D 追求“每个样本信息最大化”会偏离统一规范，故不选。","k":"peixun"},
{"id":602,"m":"练习二","t":"多选","q":"下面哪些是常见的数据标注方式（）。","o":["文本标注","图像标注、视频标注","语音标注","手写标注"],"a":[0,1,2,3],"e":"【考点】常见数据标注方式\n【答案】ABCD\n【解析】按数据模态分为文本、图像、视频、语音标注，手写（手写体识别）标注也是常见形式（如手写数字与文字标注）。\n【辨析】四项覆盖主要标注形态。","k":"xunlian"},
{"id":603,"m":"练习二","t":"多选","q":"在人机界面设计中，有很多方式可以表达用户体验其中包括（）。","o":["感官体验","情感体验","环境体验","文化体验"],"a":[0,1,3],"e":"【考点】用户体验的表达方式\n【答案】ABD\n【解析】用户体验可通过感官体验（视听触）、情感体验（愉悦与信任）、文化体验（价值认同）来表达。\n【辨析】环境体验不是界面体验的标准分类，故 C 不选。","k":"sheji"},
{"id":604,"m":"练习二","t":"多选","q":"人机交互界面的分类主要包括（）。","o":["纯硬件操作界面","纯软件操作界面","触控式操作界面","感应式操作界面"],"a":[0,1,2],"e":"【考点】人机界面的分类\n【答案】ABC\n【解析】人机交互界面分为纯硬件操作界面（按钮旋钮）、纯软件操作界面（图形界面）、触控式操作界面。\n【辨析】感应式操作界面不在题库的分类中，故 D 不选。","k":"sheji"},
{"id":605,"m":"练习二","t":"多选","q":"交互性体现在（）.","o":["产品的技术系统","非电子类产品","服务","组织"],"a":[0,1,2,3],"e":"【考点】交互性的体现范围\n【答案】ABCD\n【解析】交互性不只存在于电子产品：技术系统、非电子类产品（如家具的形态反馈）、服务流程、组织结构中都存在互动关系。\n【辨析】四项都在广义交互的范围内。","k":"sheji"},
{"id":606,"m":"练习二","t":"多选","q":"一种好的用户界面应当具有0的特性。","o":["清晰、简明","熟悉、易响应","操作一致、有吸引力","高效和容错性"],"a":[0,1,2,3],"e":"【考点】好界面的特性\n【答案】ABCD\n【解析】优秀界面应清晰简明、熟悉易响应、操作一致且有吸引力、高效并具备容错性。\n【辨析】四组特性覆盖可读性、可学性、一致性、效率与安全。","k":"sheji"},
{"id":609,"m":"练习二","t":"多选","q":"在交互设计中，结构层的重点在于（）.","o":["视觉设计","交互设计","信息框架","界面"],"a":[1,2],"e":"【考点】结构层的重点\n【答案】BC\n【解析】结构层确定信息架构与交互流程：内容如何组织、用户如何一步步操作，是骨架层。\n【辨析】视觉设计与界面属表现层/框架层，故 A、D 不选。","k":"sheji"},
{"id":610,"m":"练习二","t":"多选","q":"在人机交互界面设计中，通常使用0进行设计。","o":["设计师模型","实现者模型","用户模型","机器模型"],"a":[0,1,2],"e":"【考点】界面设计的三类模型\n【答案】ABC\n【解析】人机界面设计同时使用设计师模型（设计意图）、实现者模型（技术实现）、用户模型（用户认知与目标），三者需对齐。\n【辨析】机器模型不是设计模型分类，故 D 不选。","k":"sheji"},
{"id":611,"m":"练习二","t":"多选","q":"交互设计作为一门跨学科的研究领域，涉及多个方面，例如（）。","o":["信息架构设计","视觉传达设计","工业设计","人机工程学"],"a":[0,1,2,3],"e":"【考点】交互设计的跨学科性\n【答案】ABCD\n【解析】交互设计涉及信息架构、视觉传达、工业设计、人机工程学等多个学科，还要吸收心理学与社会学。\n【辨析】四项都是其学科支撑。","k":"sheji"},
{"id":612,"m":"练习二","t":"多选","q":".以下0届于交互系统设计的步骤","o":["需求分析、用户研究","概念设计、信息架构设计","原型设计、交互方式设计","视觉设计、程序实现"],"a":[0,1,2,3],"e":"【考点】交互系统设计的步骤\n【答案】ABCD\n【解析】完整流程为：需求分析与用户研究 → 概念设计与信息架构 → 原型与交互方式设计 → 视觉设计与程序实现。\n【辨析】四步构成从研究到落地的闭环。","k":"sheji"},
{"id":613,"m":"练习二","t":"多选","q":"标注师需要具备哪些技能0","o":["严谨的运辑思维和分析能力","熟悉数据标注相关工具和软件的使用","对被标注的数据领域有较强的了解","全面掌握机器学习和深度学习算法"],"a":[0,1,2],"e":"【考点】标注师的能力要求\n【答案】ABC\n【解析】标注师需要严谨的逻辑分析能力、熟练使用标注工具、了解所标数据领域的基本知识。\n【辨析】全面掌握机器学习算法不是标注师的必备要求，故 D 不选。","k":"peixun"},
{"id":614,"m":"练习二","t":"多选","q":".在A系统运维中，以下哪项措施可以提高系统的稳定性（）。","o":["使用最新的硬件设备","使用稳定的容器或虚拟化技术","使用最新的操作系统版本","及时清理系统垃圾文件"],"a":[1,2],"e":"【考点】提高系统稳定性\n【答案】BC\n【解析】使用稳定的容器或虚拟化技术可隔离故障、便于迁移；使用成熟最新的操作系统版本能减少已知缺陷。\n【辨析】最新硬件不一定稳定（可能有兼容问题），清理垃圾文件对稳定性帮助有限，故 A、D 不选。","k":"yunwei"},
{"id":615,"m":"练习二","t":"多选","q":"在AI系统运维中，以下哪项措施可以提高系统的安全性（）。","o":["定期备份数据","确保系统补丁及时更新","加密敏感数据传输","开启系统所有账户的root权限"],"a":[0,1,2],"e":"【考点】提高系统安全性\n【答案】ABC\n【解析】定期备份（可恢复）、及时打补丁（堵漏洞）、加密敏感数据传输（防窃听）都是有效的安全措施。\n【辨析】给所有账户开 root 权限等于放大风险，故 D 不选。","k":"yunwei"},
{"id":616,"m":"练习二","t":"多选","q":"在AI系统运维中，以下哪种方式可以有效降低系统崩溃的风险0","o":["使用防火墙系统","定期更新操作系统","配置系统日志告皆","提高系统运行负荷"],"a":[1,2],"e":"【考点】降低崩溃风险\n【答案】BC\n【解析】定期更新操作系统修复缺陷、配置日志告警以及早发现异常，都能降低崩溃概率。\n【辨析】防火墙主要防攻击，提高运行负荷会加剧崩溃，故 A、D 不选。","k":"yunwei"},
{"id":617,"m":"练习二","t":"多选","q":"AI系统运维中，常见的日志管理方法包括哪些（）.","o":["自动存档","数据清理","压缩归档","手动记录"],"a":[0,1,2],"e":"【考点】日志管理方法\n【答案】ABC\n【解析】日志要自动存档（留档备查）、定期清理（释放空间）、压缩归档（长期保存省空间）。\n【辨析】手动记录效率低且易漏，不是运维的标准做法，故 D 不选。","k":"yunwei"},
{"id":618,"m":"练习二","t":"多选","q":"AI系统运维中，以下哪项属于常见的故障类型O。","o":["人为误操作","网络中断","电源故障","PU过载"],"a":[0,1,2,3],"e":"【考点】常见故障类型\n【答案】ABCD\n【解析】人为误操作、网络中断、电源故障、CPU 过载都是运维中高频出现的故障类型。\n【辨析】四类分别对应人、网、电、算力四个层面。","k":"yunwei"},
{"id":619,"m":"练习二","t":"多选","q":"AI系统运维中，以下哪项属于常见的性能指标（）。","o":["平均响应时间","系统内存占用率","最大磁盘容量","系统安全性评估分数"],"a":[0,1],"e":"【考点】性能指标\n【答案】AB\n【解析】平均响应时间与内存占用率直接反映系统运行快慢与资源压力，是核心性能指标。\n【辨析】最大磁盘容量是容量规划参数，安全评分是安全指标，故 C、D 不选。","k":"yunwei"},
{"id":620,"m":"练习二","t":"多选","q":"在AI系统运维中，下面哪种方式是常见的扩容方式（）.","o":["交换机扩容","虚拟化扩容","数据库扩容","Linux网络扩展"],"a":[1,2],"e":"【考点】常见扩容方式\n【答案】BC\n【解析】扩容分纵向（提升单机性能）与横向（增加节点）：虚拟化扩容与数据库扩容都是常见做法。\n【辨析】交换机扩容属网络设备调整，Linux 网络扩展不是通用扩容方式，故 A、D 不选。","k":"yunwei"},
{"id":621,"m":"练习二","t":"多选","q":"在AI系统运维中，有哪些措施可以提高系统可用性（）.","o":["配备几余硬件设备","定期备份数据","对系统进行及时升级","使用虚拟化技术"],"a":[0,1,2,3],"e":"【考点】提高系统可用性\n【答案】ABCD\n【解析】冗余硬件避免单点故障、定期备份可快速恢复、及时升级减少缺陷、虚拟化便于迁移与快速重建，都能提升可用性。\n【辨析】四项从硬件、数据、软件、架构四方面保障。","k":"yunwei"},
{"id":622,"m":"练习二","t":"多选","q":"AI系统运维软件是如何处理网络问题的（）。","o":["捕获和分析网络流量","支持VPN隧道","提供跟踪资源使用情况的报告","监控网络拓扑"],"a":[0,3],"e":"【考点】运维软件处理网络问题\n【答案】AD\n【解析】运维软件通过抓包分析流量定位异常、监控网络拓扑发现链路故障，这是其处理网络问题的主要手段。\n【辨析】VPN 隧道支持属网络功能而非排障手段，资源使用报告属性能监控，故 B、C 不选。","k":"yunwei"},
{"id":623,"m":"练习二","t":"多选","q":"AI系统运维软件可以通过哪些方式提高效率O","o":["实现自动化","提高可伸缩性","自动扩展","降低维护成本"],"a":[0,1,2,3],"e":"【考点】提升效率的方式\n【答案】ABCD\n【解析】自动化减少人工、可伸缩性支撑弹性、自动扩展应对峰值、降低维护成本，都直接提升运维效率。\n【辨析】四项分别对应人力、架构、弹性、成本。","k":"yunwei"},
{"id":624,"m":"练习二","t":"多选","q":"AI系统运维软件中的警报功能主要用于什么（）.","o":["警示管理员关于出现故障的潜在问题","监测某些资源的性能水平","记录用户应用程序的使用情况","监测服务器的硬件状况"],"a":[0,1,3],"e":"【考点】警报功能的用途\n【答案】ABD\n【解析】警报用于提示潜在故障、监测资源性能水平、监测硬件状况，让管理员在故障扩大前介入。\n【辨析】记录用户应用使用情况属审计与行为分析，不是警报功能，故 C 不选。","k":"yunwei"},
{"id":625,"m":"练习二","t":"多选","q":"AI系统运维软件的主要优势包括以下哪些0","o":["效率提高","强大的自动化功能","提高安全性","降低维护成本"],"a":[0,1,2,3],"e":"【考点】AI 运维软件的优势\n【答案】ABCD\n【解析】效率提高、自动化能力强、安全性提升、维护成本降低，是 AI 运维软件的四项核心优势。\n【辨析】四项分别对应省人、省事、稳、省钱。","k":"yunwei"},
{"id":626,"m":"练习二","t":"多选","q":"语音交互系统采用的途径有（）。","o":["用基于语音识别和理解技术","依靠音频进行交互","利用语音技术与系统的其他交互方式结","眼神传递信息"],"a":[0,1,2],"e":"【考点】语音交互系统的途径\n【答案】ABC\n【解析】语音交互可基于语音识别与理解技术、依靠音频本身交互，也可与其他交互方式（触屏、视觉）结合形成多模态。\n【辨析】眼神传递属视觉交互，不是语音途径，故 D 不选。","k":"xunlian"},
{"id":627,"m":"练习二","t":"多选","q":"语音识别技术将人类的语言转化为计算机能够理解的形式，例如将语言内容转换为（）.","o":["输入按键","二进制编码","绘图","字符序列"],"a":[0,1,3],"e":"【考点】语音识别的输出形式\n【答案】ABD\n【解析】识别结果可转为字符序列（文本）、二进制编码（供计算机处理）、甚至映射为按键指令（语音控制）。\n【辨析】绘图不是语音识别的输出，故 C 不选。","k":"jichu"},
{"id":628,"m":"练习二","t":"多选","q":"初级数据标注员需要掌握0等数据标注类型的基本操作技能。","o":["2D图像标注","文字标注","图像采集","语音标注"],"a":[0,1,2,3],"e":"【考点】初级标注员的技能范围\n【答案】ABCD\n【解析】初级标注员要掌握 2D 图像标注、文字标注、图像采集、语音标注等基础操作技能，是上岗的基本功。\n【辨析】四项覆盖主要标注模态的入门操作。","k":"peixun"},
{"id":629,"m":"练习二","t":"多选","q":"语音特征提取的过程包含（）步骤。","o":["声音录入","数字化采样","信号预处理","模型匹配"],"a":[0,1],"e":"【考点】语音特征提取的步骤\n【答案】AB\n【解析】特征提取的前置环节是声音录入（采集）与数字化采样（模数转换、分帧），之后才做预处理与特征计算。\n【辨析】信号预处理与模型匹配属后续环节，故 C、D 不选。","k":"xunlian"},
{"id":630,"m":"练习二","t":"多选","q":"一个全面的语音识别系统可以分为0几个部分。","o":["语音特征提取","：字典建立","声学模型与模式匹配","语意理解"],"a":[0,2,3],"e":"【考点】语音识别系统的组成\n【答案】ACD\n【解析】完整系统包含语音特征提取（听清）、声学模型与模式匹配（识别音素序列）、语义理解（明白意思）。\n【辨析】题库未把字典建立列入该系统组成，故 B 不选。","k":"xunlian"},
{"id":631,"m":"练习二","t":"多选","q":"建立一个完整的数据标注培训体系，包括0，以培养和提高数据标注员的能力和素质。","o":["建立严格的培训流程","有完善的职称等级制度","设立激励制度","提供多元化的美食"],"a":[0,1,2],"e":"【考点】标注培训体系的构成\n【答案】ABC\n【解析】培训体系要建立严格培训流程、完善职称等级制度、设立激励制度，从而既提能力又稳队伍。\n【辨析】提供美食与培训体系无关，故 D 不选。","k":"peixun"},
{"id":632,"m":"练习二","t":"多选","q":"帮助有超过两周以上标注经验的数据标注员提升质量，计划内容包括（）。","o":["强化基础数据标注规范，查漏补缺","数据标注过程问题总结指导","质检一条其他人的数据","培训员进行指导，能力巩固"],"a":[0,1,2,3],"e":"【考点】两周以上标注员的质量提升计划\n【答案】ABCD\n【解析】对有一定经验的标注员，计划包括强化基础规范查漏补缺、过程问题总结指导、质检他人数据、培训员跟盯巩固能力。\n【辨析】四项构成“规范—复盘—互检—巩固”的完整训练。","k":"peixun"},
{"id":633,"m":"练习二","t":"多选","q":"数据主要来源包括以下（）。","o":["手写字以及画图数据","泛互联网数据","大呈传感器的机器数据","行业的多结构专业数据"],"a":[1,2,3],"e":"【考点】数据主要来源\n【答案】BCD\n【解析】泛互联网数据、传感器机器数据、行业多结构专业数据是数据的主要来源，构成大数据的主体。\n【辨析】手写字与画图数据是细分采集形式，不属“主要来源”，故 A 不选。","k":"jichu"},
{"id":634,"m":"练习二","t":"多选","q":"数据预处理包括0等方面的工作。","o":["数据清理","数据集成","数据变换","数据归约"],"a":[0,1,2,3],"e":"【考点】数据预处理的环节\n【答案】ABCD\n【解析】数据预处理包括数据清理、数据集成、数据变换、数据归约四大环节，缺一都会影响建模效果。\n【辨析】四项正是预处理的标准框架。","k":"yewu"},
{"id":635,"m":"练习二","t":"多选","q":"Kettle是一款数据O工具，旨在帮助用户更便捷地管理数据。","o":["复制","转换","备份","抽取"],"a":[1,3],"e":"【考点】Kettle 的定位\n【答案】BD\n【解析】Kettle 是数据抽取与转换（ETL）工具，负责从源系统取数、做转换加工，再加载到目标库。\n【辨析】复制、备份不是其核心定位，故 A、C 不选。","k":"yewu"},
{"id":636,"m":"练习二","t":"多选","q":"在一个数据标注项目的顺利完成过程中，通常需要涉及到0等多个方面的合作。","o":["销售部","项目部","生产部和平台部","资源部和财务部"],"a":[0,1,2,3],"e":"【考点】标注项目的协作部门\n【答案】ABCD\n【解析】标注项目要销售部（接需求）、项目部（管理）、生产部与平台部（标注与工具）、资源部与财务部（人力与预算）共同配合。\n【辨析】四项覆盖商务、管理、生产、保障四条线。","k":"xunlian"},
{"id":637,"m":"练习二","t":"判断","q":"重点强调人文科学的理论指导，是人机交互学科的理论体系的重要特点。","o":["正确","错误"],"a":0,"e":"【考点】人机交互的理论特点\n【答案】正确\n【解析】人机交互学科高度重视人文科学（心理学、认知科学、社会学）的理论指导，用它解释人的感知、认知与行为，这是其学科体系的重要特点。\n【辨析】易误判为“错误”，因为人们常以为人机交互只讲技术实现；实际上心理学、认知科学等是其理论根基，故题干说法正确。","k":"sheji"},
{"id":638,"m":"练习二","t":"判断","q":"对于采集回来的数据，不需要做数据清洗即可直接使用。","o":["正确","错误"],"a":1,"e":"【考点】数据清洗的必要性\n【答案】错误\n【解析】采集回来的原始数据普遍存在缺失、重复、格式不一、异常值等问题，必须清洗后才能用于分析建模，直接使用会污染结果。\n【辨析】易误判为“正确”，觉得数据拿到就能直接用；实际原始数据普遍含缺失、重复、异常，不清洗会直接污染模型结果。","k":"yewu"},
{"id":639,"m":"练习二","t":"判断","q":"视频标注以图片顿为单位，对视频素材中的目标对象进行跟踪，对包括道路、车辆、行人等在内的目标物的特征信息、结构信息、语义信息等进行标记，从而形成训练数据集。","o":["正确","错误"],"a":0,"e":"【考点】视频标注\n【答案】正确\n【解析】视频标注以帧为单位，对道路、车辆、行人等目标做跟踪与特征、结构、语义标记，从而生成训练数据集，符合定义。\n【辨析】易误判为“错误”，把视频标注只理解成打标签分类；实际它是以帧为单位做跟踪，并对目标特征、结构、语义做多维标记。","k":"xunlian"},
{"id":640,"m":"练习二","t":"判断","q":"语音交互仅仅包括语音采集。","o":["正确","错误"],"a":1,"e":"【考点】语音交互的范畴\n【答案】错误\n【解析】语音交互是完整闭环：语音采集（拾音）→ 识别 → 理解 → 决策 → 语音合成（输出），远不止采集一环。\n【辨析】易误判为“正确”，只想到麦克风拾音；实际语音交互是采集—识别—理解—决策—合成的完整闭环。","k":"xunlian"},
{"id":641,"m":"练习二","t":"判断","q":"将用户界面的设计画在纸上来模拟原型，这种方法被称为高保真原型。","o":["正确","错误"],"a":1,"e":"【考点】原型的保真度\n【答案】错误\n【解析】画在纸上的原型是低保真原型（快速验证结构），高保真原型要用真实视觉与可交互实现（如 Figma 或代码原型）。\n【辨析】易误判为“正确”，把纸面草图当高保真；实际上纸面原型只验证结构流程，属低保真，高保真需接近真实视觉与可交互。","k":"sheji"},
{"id":642,"m":"练习二","t":"判断","q":"高级数据标注员是负责管理数据标注团队、总结数据标注经验以及为数据标注员提供培训的职位。","o":["正确","错误"],"a":0,"e":"【考点】高级数据标注员职责\n【答案】正确\n【解析】高级标注员承担团队管理、经验总结与新人培训，是标注团队的组织者与质量负责人。\n【辨析】易误判为“错误”，容易与中级标注员的质检职责混淆；高级岗的核心是团队管理、经验沉淀与培训。","k":"peixun"},
{"id":643,"m":"练习二","t":"判断","q":"在App应用中使用语音识别技术会遇到方言种类繁多和口音各异的主要问题。","o":["正确","错误"],"a":0,"e":"【考点】方言语种的识别难点\n【答案】正确\n【解析】汉语方言众多、口音差异大，同一句式发音不同会导致声学模型识别率下降，这是 App 接入语音识别的主要难点。\n【辨析】易误判为“错误”，以为难点只在网速或麦克风质量；实际上方言与口音造成的识别率下降才是核心问题。","k":"xunlian"},
{"id":644,"m":"练习二","t":"判断","q":"文本实体标注就是对自然语言文本中的实体进行标注，定位出某些预定义实体的字串。","o":["正确","错误"],"a":0,"e":"【考点】文本实体标注\n【答案】正确\n【解析】实体标注是在文本中定位预定义实体（人名、地名、机构、时间、金额等）的字串并打上类别，是信息抽取的基础。\n【辨析】易误判为“错误”，以为实体标注就是分词；实际上还要定位实体的字串边界并给出类别标签。","k":"xunlian"},
{"id":645,"m":"练习二","t":"判断","q":"语音交互是人以自然语音或机器合成语音同计算机进行交互的综合性技术。","o":["正确","错误"],"a":0,"e":"【考点】语音交互的定义\n【答案】正确\n【解析】语音交互既包括人用自然语音输入，也包括机器用合成语音回应，是双向的综合性技术。\n【辨析】易误判为“错误”，以为语音交互只是机器说给人听；实际上人说话输入与机器语音输出是双向过程。","k":"jichu"},
{"id":646,"m":"练习二","t":"判断","q":"一个人的职业态度可以从他们的心态、职业道德和工作态度中得出。","o":["正确","错误"],"a":0,"e":"【考点】职业态度的体现\n【答案】正确\n【解析】职业态度由心态（积极或消极）、职业道德（守规与否）、工作态度（认真或敷衍）三方面共同体现。\n【辨析】易误判为“错误”，以为评价职业态度只看业绩；实际上心态、职业道德、工作态度三者共同体现职业态度。","k":"peixun"}];
